// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":20,"question":"هل يجب على الابن الدّعاء لوالده بعد وفاته، خاصةً إذا كان الوالدُ في حياته يُفرِّق بينه وبين أخٍ في عمره تفريقًا شاسعًا؟ وهل على الابن إثمٌ في عدم الدعاء له أم لا؟ أفيدونا أثابكم الله.","title":"هل يجب على الابن الدعاء لوالده بعد وفاته؟","answer":"الجواب: لا ريب أنه يُشرع للولد أن يدعو لوالده ولو قصَّر والده في حقِّه في حياته،  فإنَّ حقَّ الوالد عظيمٌ، فالدعاء له من أهم أنواع البر.\nثبت عن رسول الله عليه الصلاة والسلام أنه قال: إذا مات ابنُ آدم انقطع عملُه إلا من ثلاثٍ: صدقة جارية، أو علم يُنتفع به، أو ولد صالح يدعو له خرّجه الإمام مسلم في \"صحيحه\".\nوثبت عنه أيضًا عليه الصلاة والسلام أنه قيل له: يا رسول الله، هل بقي من برِّ أبويَّ شيءٌ أبرّهما به بعد وفاتهما؟ قال ﷺ: نعم، الصلاة عليهما، والاستغفار لهما، الصلاة عليهما يعني: الدّعاء لهما، مثل قوله: وَصَلِّ عَلَيْهِمْ إِنَّ صَلَاتَكَ سَكَنٌ لَهُمْ [التوبة:103]، فالصلاة عليهم من الدعاء، ومنها صلاة الجنازة، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما يعني: الوصية التي يعهدان بها، وإنفاذ عهدهما من بعدهما يعني: إذا كانت الوصية شرعيةً -ليس لها مانعٌ شرعًا- فإنَّ من برِّهما إنفاذ تلك الوصية، وإكرام صديقهما أصدقاء الوالد والوالدة، وصلة الرحم التي لا تُوصل إلا بهما كلُّ هذا من برِّهما بعد الوفاة.\nالأول: الصلاة عليهما، والاستغفار لهما، هذا كله دعاء.\nالثاني: إنفاذ عهدهما من بعدهما، الوصية التي لا تُخالف الشرع.\nالثالث: إكرام صديقهما.\nالرابع: صلة الرحم التي لا تُوصل إلا بهما، مثل: أعمامك، وأخوالك، وعمَّاتك، وخالاتك، كل هؤلاء من أقرباء الوالدين، وثبت عنه ﷺ أنه قال: إنَّ من أبرِّ البر: صلة الرجل أهل ودِّ أبيه وفي لفظٍ: إنَّ أبرَّ البر رواه مسلم من حديث ابن عمر: إنَّ أبر البر أن يصل الرجلُ أهل وُدِّ أبيه، وفي اللفظ الآخر: إنَّ من أبرِّ البر أن يصل الرجلُ أهلَ وُدِّ أبيه يعني: أحباب أبيه، فهذا من برِّ الوالدين.\nوالله قال في الكافِرَين وهما كافران: وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا [لقمان:15]، فأمر في حقِّ الوالدين الكافرين أن يصحبهما الولدُ في هذه الدنيا معروفًا: بنصيحتهما، والإحسان إليهما، ودعوتهما إلى الهدى، والحرص على أن يرجعا إلى الحقِّ، وأن يتوبا، إلى غير هذا من وجوه المعروف في هذه الدنيا، وهما كافران، فكيف بالمُسْلِمَيْنِ؟!\nولو كان من الوالد شيءٌ من التقصير في حقِّ الولد -كإيثار بعضهم على بعضٍ، أو هجره له، أو طرده له، أو غير هذا- فإن هذا لا يمنع من برِّه والدّعاء له، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/2799/هل-يجب-على-الابن-الدعاء-لوالده-بعد-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0272.mp3","categories":["إهداء القرب للميت","فضائل الحج والعمرة"]},{"id":404,"question":"ما الأمور التي تُقوي الرابطة بين المسلمين في الحجِّ؟","title":"ما الأمور التي تقوي الرابطة بين الحجيج؟","answer":"الجواب: أعظمها التزاور والتعليم والتوجيه، كل هذه من أعظم الأسباب: التزاور بين الجيران والإخوان، في منى، وفي عرفة، وفي السكن في مكة، حسب التيسير، التزاور والإهداء ومُواساة الفقير، والتعليم في المساجد وفي المسجد الحرام، والتعرف على أحوال الحجيج وحاجاتهم. كل هذا من أسباب تقوية الروابط؛ لأنَّ الحجاج كثيرون، فالحاجة ماسَّة إلى الزيارة والتَّعرف عليهم وعلى أحوالهم، وتعليم جاهلهم، وإرشاد ضالهم، ومُواساة فقيرهم، ونحو ذلك من الأسباب التي تُعينهم على الاتِّصال.","link":"https://binbaz.org.sa/fatwas/4814/ما-الامور-التي-تقوي-الرابطة-بين-الحجيج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0462.mp3","categories":["إهداء القرب للميت","فضائل الحج والعمرة"]},{"id":834,"question":"ما حكم إهداء الأعمال إلى الأموات: من حجٍّ وعمرةٍ وصومٍ وصدقةٍ؟","title":"حكم إهداء الأعمال الصالحة إلى الأموات","answer":"الجواب: هذا فيه تفصيلٌ: من أهل العلم مَن قال: يُهدى إليه كل شيءٍ، وذكر ذلك ابنُ القيم رحمه الله في كتابه المعروف كتاب \"الروح\" وفي غيره، وذكره آخرون قال: يهدى له كل قربةٍ يتقرب بها الإنسانُ المسلم حيًّا أو ميتًا، واستدل على هذا بأنه يُصام عن الميت إن كان عليه صيام، ويحج عنه، ويُوفَى دينُه، قال: ثم يُقاس على ذلك الصلاة عنه وتوجيه الصلاة له تثويبها له والصوم المجرد كذلك، وقراءة القرآن، والأذكار، إلى غير ذلك. وبعضهم أفاد أن هذا قول الجمهور.\nثم ذهب آخرون إلى أنَّ هذا الأمر توقيفي، يعني: عبادة توقيفية، لا مجال للرأي فيها، ولا ينبغي أن يُقاس فيها هذا على هذا، وأنَّ هذا أمرٌ توقيفي، فلا يلحق بالميت إلا ما جاء به الشرعُ، فالصلاة عليه صلاة الجنازة تنفعه، أداء الصوم عنه إذا مات وعليه صيامٌ صام عنه وليُّه ينفعه، قضاء الدَّين إذا كان عليه حقوق ينفعه، الحج عنه ينفعه، هذا هو الذي جاء به الشرع.\nأما أن يُصلَّى عنه، أو يُقرأ القرآن له، أو يُطاف عنه؛ هذا ليس عليه دليلٌ. وهذا الأقرب إلى الصواب، وأحوط في إصابة الحق، هذا القول: إن هذه الأمور توقيفية، هذا هو الأقرب عندي، وهو قول جماعةٍ من أهل العلم، وهو مقتضى كلام الشافعي رحمه الله... وجماعة آخرين، هذه الأمور لا تُقال بالرأي ولا بالقياس على يقال: كما يُصام عنه الواجب ويُصام عنه التطوع، لا، ولا يقال: كما يُصام عنه يُصلَّى عنه، لا، ليس إلينا هذا، هذا إلى الشرع، والشرع ما قال لنا: صلّوا على الأموات، ولا اقرؤوا عنهم، لا، أمرنا بالدعاء، ندعو له ونتصدق، كل هذا جاء في الشرع: الصدقة، الدعاء، الحج عن الميت، العمرة، أو العاجز الذي ما يقدر لكبر سنِّه، أو ما وجد..... يُحج عنه ويعتمر، نصوم عنه إذا كان ترك صومًا..... عليه دَينٌ يُقضى عنه، نتصدق عنه، كذلك ندعو له، هذا جاء به، أما أن نُصلِّي عنه، أو نقرأ في المسجد القرآن، أو نطوف عنه؛ هذا ليس عليه دليلٌ، والأقرب عندي والأظهر عندي أنَّ هذا لا يلحق..... ولا ينفع الميت؛ لعدم الدليل، وقول الجمهور له حظ من الوجاهة، ولا نُشدد في الإنكار، لكن نقول: هذا هو الأقرب، وهذا هو الأحرى، ونسأل الله للجميع التوفيق والهداية.","link":"https://binbaz.org.sa/fatwas/20856/حكم-اهداء-الاعمال-الصالحة-الى-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0651ما حكم أهداء الأعمال إلى الأموات من حج وعمرة وصوم وصدقة ؟ ابن باز فتاوى المحاضرات.mp3","categories":["إهداء القرب للميت","فضائل الحج والعمرة"]},{"id":906,"question":"هل يجوز أن أطوف وأهدي ثوابَ طوافي لميتٍ أو حيٍّ؟","title":"ما حكم إهداء الطواف للميت والحي؟","answer":"الجواب: هذه المسألة فيها خلافٌ بين أهل العلم: منهم مَن أجاز ذلك، جماعة من أهل العلم قالوا: لا مانع من تثويب الصلاة والطواف والقراءة وغير ذلك، للأموات وغيرهم, وآخرون من أهل العلم قالوا: لا، إلا ما ورد به الشرعُ، فليس للعبد أن يُثَوِّب إلا ما جاء به الشرع؛ لأنَّ العبادات توقيفية. وهذا هو الأظهر والأقرب، أنها توقيفية، وأنه لا يطوف عن غيره، ولا يقرأ عن غيره، وإنما يفعل ما جاء به الشرعُ من الصدقة عن الغير، والحج عن الغير، والعمرة عن الغير، وأداء الدَّين، والدُّعاء له، والاستغفار له، هذا هو الذي ينفع، أما كونه يطوف له، أو يقرأ له، أو يستغفر له، أو يُسبّح له؛ فليس عليه دليلٌ.","link":"https://binbaz.org.sa/fatwas/20937/ما-حكم-اهداء-الطواف-للميت-والحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0733هل يجوز أن أهدي طوافي للميت أو الحي؟ ابن باز فتاوى المحاضرات.mp3","categories":["إهداء القرب للميت","فضائل الحج والعمرة"]},{"id":987,"question":"أنا أعتمر في شهر رمضان المبارك خمس مرات: واحدة عني، وواحدة عن والدي، وواحدة عن والدتي، وواحدة عن أخي المتوفى، وواحدة عن زوجتي المُتوفاة، وسألتُ عن ذلك بعض المشايخ فقال: لا يجوز ذلك، أرجو إفادتي جزاكم الله خير الجزاء.","title":"حكم من اعتمر في رمضان عنه وعن آخرين","answer":"الجواب: لا نعلم في هذا شيئًا، يقول النبيُّ ﷺ: العمرة إلى العمرة كفَّارةٌ لما بينهما، والحج المبرور ليس له جزاء إلا الجنة، ولم يحدد حدًّا بين العمرتين، وإذا كانوا أمواتًا فالاعتمار لهم والحج عنهم كله طيب، وإذا جعلت بين العمرتين شيئًا من الأيام حسنٌ إن شاء الله، وإلا فالنبي لم يُحدد شيئًا عليه الصلاة والسلام.\nفالعمرة للقريب ولغير القريب من العمل الصالح: كالصَّدقة والدعاء، وفي حديث ابن عباس لما سمع النبيُّ رجلًا يقول: \"لبيك عن شبرمة\"، قال: مَن شبرمة؟ قال: أخٌ لي، أو قريبٌ لي، قال: حججتَ عن نفسك؟ قال: لا، قال: حُجَّ عن نفسك ثم حُجَّ عن شبرمة، ولم يقل: هذا حج نافلة أو فريضة؟ فدلَّ ذلك على التوسعة في هذا.\nوهكذا مَن سأل عن الحج... يُجيبهم ولا يقول لهم: هل هو فريضة؟ فهذا يقول: أردتُ أن أحجَّ عن أمي، وهذا يقول: أردتُ أن أحجَّ عن أبي، ويقول له: أوفِ بنذرك، ولم يقل له: هل هو فريضة أو نافلة.","link":"https://binbaz.org.sa/fatwas/21021/حكم-من-اعتمر-في-رمضان-عنه-وعن-اخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0818أنا أعتمر في رمضان خمس مرات عني وعن والدي وعن والدتي وعن زوجتي المتوفاة فهل هذا جائز؟.mp3","categories":["إهداء القرب للميت"]},{"id":1147,"question":"هل يجوز التَّصدُّق للميت بعد وفاته؟ ومعروفٌ أنه قد ورد الدعاء له، فهل تُرفع الأيدي عند الدعاء عند الوقوف على القبر؟","title":"حكم التصدُّق للميت والدعاء عند قبره","answer":"الجواب:\nلا بأس بالصدقة، بل يُشرع له الصدقة عن الميت، سواء من ماله الذي ورثه الوارث، أو من أموالٍ أخرى، سواء كان المتصدقُ وارثًا أو غير وارثٍ، ثبت عنه ﷺ أنه سُئل، سأله رجلٌ قال: إنَّ أمي ماتت ولم تُوصِ، وأظنُّها لو تكلَّمتْ تصدَّقتْ، أفلها أجرٌ إن تصدَّقْتُ عنها؟ قال النبي: نعم، لها أجر.\nوقال عليه الصلاة والسلام: إذا مات ابنُ آدم انقطع عملُه إلا من ثلاثٍ: صدقة جارية، أو علم يُنتفع به، أو ولد صالح يدعو له، فإذا دعا له ولده الصالح وتصدَّق عنه ينفعه...، وهكذا لو دعا له غير ولده من المسلمين: من إخوان، أو أخوات، أو أقارب، أو غيرهم، أو تصدَّق عنه بعضُ أقاربه أو غيرهم، كل ذلك ينفع، الصَّدقة عن الميت تنفع حتى من غير أقاربه.\nس: هل يُشرع رفع الأيدي؟\nالشيخ: والرفع كذلك، لا بأس بالرفع، رفع الأيدي من أسباب الإجابة، وقد ثبت عنه ﷺ أنه رفع يديه لدعاء الموتى، زار البقيع ورفع يديه ﷺ ودعا لهم، ثبت عن عائشة رضي الله عنها أنه فعل ذلك عليه الصلاة والسلام، فإذا رفع يديه ودعا لا بأس ولا حرج في ذلك، فالدعاء مشروعٌ، ورفع الأيدي من أسباب الإجابة، في الحديث الصحيح يقول ﷺ: إنَّ ربَّكم حيي كريم، يستحي من عبده إذا رفع يديه أن يردَّهما صفرًا.\nلكن المواضع التي ما رفع فيها النبيُّ لا نرفع فيها، مثل: خطبة الجمعة، وخطبة العيد، ما رفع فيها النبيُّ ﷺ، ما نرفع، مثل: بعد الفريضة إذا سلَّم ما يرفع؛ لأنَّ النبي ما كان يرفع بعد الفريضة، كذلك بين السَّجدتين إذا جلس يدعو ما يرفع، ولا في آخر الصلاة إذا جلس يدعو قبل أن يُسلِّم ما يرفع؛ لأنَّ الرسول ما رفع في هذه المواضع، فلو كان خيرًا لفعله ﷺ، أو فعله أصحابه.\nأما المواضع الأخرى التي ما ورد فيها شيءٌ يرفع فيها المؤمن إذا دعا، كذلك المواضع التي رفع فيها النبيُّ ﷺ: كدعاء الاستسقاء، أو الاستغاثة، يرفع فيها؛ لأنَّ الرسول رفع فيها عليه الصلاة والسلام، وهكذا إذا دعا دعاءً عارضًا في بعض الأحيان، دعا لأهله أو للمسلمين ورفع يديه. كل هذا طيب، لا بأس، ومن أسباب الإجابة.","link":"https://binbaz.org.sa/fatwas/21185/حكم-التصدق-للميت-والدعاء-عند-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0981هل يجوز التصدق للميت والدعاء له؟.mp3","categories":["إهداء القرب للميت"]},{"id":1646,"question":"هل أفضل الصَّدقة في حقِّ الميت هي الماء أم أن هناك أفضل منها؟","title":"ما أفضل الصدقة في حق الميت؟","answer":"الجواب:\nجاء في بعض الروايات ما يقتضي أنَّ صدقة الماء من أفضل الصَّدقات، لكن على كل حال يتحرَّى حاجة المسكين: بالنقود، بالطعام، بالملابس، بالماء، تختلف الأحوال، فالصدقة كلها خير.","link":"https://binbaz.org.sa/fatwas/21751/ما-افضل-الصدقة-في-حق-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما أفضل الصدقة في حق الميت.mp3","categories":["إهداء القرب للميت"]},{"id":1942,"question":"الأضحية على الأموات؟","title":"حكم الأضحية عن الأموات وتخصيصهم بها","answer":"الجواب:\nداخلة في العموم، تعمّها الأحاديث، إذا ضحَّى عنه وعن أهل بيته يعمّها.\nس: تخصيصهم بالأُضحية؟\nج: لا مانع؛ لأنها صدقة، الضحية صدقة.\nس: مَن قال أنها بدعة؟\nج: لا، ما عنده خبر؛ لأنها صدقة ومساعدة وتقرّب إلى الله جل وعلا بالذبح.\nس: تدخل في باب الصَّدقة؟\nج: نعم، والنبي ﷺ ضحَّى بالضحية عنه وعن أهل بيته، وأهل بيته فيهم الميت وفيهم الحي، فيهم خديجة ميتة، وفيهم بعض بناته عليه الصلاة والسلام.\nس: تخصيص الأموات؟\nج: إذا خصَّهم لا بأس، كان النبيُّ ﷺ كثيرًا ما يُضَحِّي بذبح الشاة عن خديجة، يتصدق بها عن خديجة، ويقسمها بين صواحبات خديجة بعد وفاتها رضي الله عنها.","link":"https://binbaz.org.sa/fatwas/22055/حكم-الاضحية-عن-الاموات-وتخصيصهم-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الإضحية عن الأموات وتخصيصهم بها.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":2141,"question":"الصدقة للميت؟","title":"حكم الصدقة للميت وأنواعها","answer":"الجواب:\nتنفع الميت، إذا مات ابنُ آدم انقطع عملُه إلا من ثلاثٍ: صدقة جارية، أو علم يُنتفع به، أو ولدٌ صالحٌ يدعو له.\nس: والصدقة في أثناء حياته؟\nج: إذا وقف وقفًا في وجوه البر ينفعه، أو تصدَّق عنه أولاده أو غيرهم نفعه ذلك.\nس: بعد وفاته؟\nج: نعم.","link":"https://binbaz.org.sa/fatwas/22260/حكم-الصدقة-للميت-وانواعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصدقة للميت.mp3","categories":["إهداء القرب للميت"]},{"id":2196,"question":"رفع اليدين عند القبر للدعاء للميت؟","title":"حكم وكيفية الدعاء عند القبر","answer":"الجواب:\nلا بأس به، تقول عائشةُ أنه ﷺ رفع يديه لما زار القبور.\nس: ويجعل القبر بينه وبين القِبلة؟\nج: من أي جهةٍ، الأمر واسع.","link":"https://binbaz.org.sa/fatwas/22319/حكم-وكيفية-الدعاء-عند-القبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدعاء للميت عند القبر.mp3","categories":["إهداء القرب للميت"]},{"id":2616,"question":"بالنسبة لإهداء ثواب الحج والعمرة، التطوع، يصل للميت؟","title":"حكم وكيفية إهداء الثواب للميت","answer":"الجواب: للميت والهَرِم.\nس: وهو تطوع ثبت هذا عن رسول الله ﷺ؟\nالشيخ: الحديث عام.\nس: وصيام التطوع؟\nالشيخ: نعم، الصيام..... يُؤدَّى فريضة، صوم الفريضة، يقول النبي ﷺ: من مات وعليه صيام صام عنه وَلِيُّه يعني قريبه.\nس: وأحاديث الصوم ألم ترد كلها عن السؤال عن الفريضة؟\nالشيخ: النافلة مثل..... حديث شبرمة ما فيه فريضة، لما سمعه يقول: لبيك عن شبرمة. قال: من شبرمة؟ قال: أخ لي أو قريب لي. قال: حجيت عن نفسك؟ قال: لا، قال: حج عن نفسك ثم حج عن شبرمة ولم يسأله هل هو فريضة أو نافلة.  س: إهداء الثواب للميت عن الصدقة وغيرها؟\nالشيخ: نفس الصدقة، يتصدق بنيّة عنه، ينويها له، أو الحج أو العمرة أو الدعاء.\nس: بعض الناس يقول أن ثوابها يصل أو أهديها إلى فلان مثلا؟\nالشيخ:...... النية، الله أعلم ما في قلبه، إذا نواها بقلبه؛ كفى، إذا نوى عن فلان يكفي، فهو يعلم المغيّبات ويعلم ما في القلوب.","link":"https://binbaz.org.sa/fatwas/22751/حكم-وكيفية-اهداء-الثواب-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إهداء ثواب العمل الصالح للميت.mp3","categories":["إهداء القرب للميت"]},{"id":2992,"question":"ثواب الصيام هل يصل للميت مطلقًا؟ أم هناك تفصيل بين النَّذْر والقضاء؟","title":"هل يصل ثوابُ الصيام للميت فرضًا ونفلًا؟","answer":"الجواب: يصل له ثواب الصيام المشروع كأن يُصام عنه نَذْر أو رمضان أو كفارات، يصل إليه، النبي عليه الصلاة والسلام يقول: من مات وعليه صيام صام عنه وليه.\nس: مطلقًا؟\nالشيخ: مطلقًا إذا كان واجبًا، أما النفل ما يُصام عنه.\nس تفصيل ابن القيم؟\nالشيخ: لا، بعض أهل العلم أحمد وجماعة رأوه في النذر خاصة، ولكن الصواب أنه عام؛ النذر وغير النذر.","link":"https://binbaz.org.sa/fatwas/23149/هل-يصل-ثواب-الصيام-للميت-فرضا-ونفلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يصل ثواب الصيام للميت مطلقا.mp3","categories":["إهداء القرب للميت"]},{"id":4756,"question":"التَّابعون ما ثبت أنَّهم قرأوا القرآنَ على أمواتهم؟","title":"هل ثبت عن السلف أنَّهم قرأوا القرآنَ على أمواتهم؟","answer":"القراءة على الأموات ليس لها أصل يُعتمد، فلا ينبغي اعتماد ذلك، والأمور توقيفية، هذا هو الأصل، ليس بالآراء والاستحسانات، فالاستحسان والآراء يجرّ شرًّا كثيرًا.","link":"https://binbaz.org.sa/fatwas/25108/هل-ثبت-عن-السلف-انهم-قراوا-القران-على-امواتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ثبت عن التابعين أنَّهم قرأوا القرآنَ على أمواتهم.mp3","categories":["إهداء القرب للميت"]},{"id":4787,"question":"الذي يعتمر عن أبيه أو أمه؟","title":"ما حكم الحج والعمرة عن الوالدين أحياء وأمواتًا؟","answer":"إذا كان ميتًا لا بأس، أو عاجزًا لكبر سن أو مرض لا يرجى برؤه لا بأس، مثل الميت العاجز، مثل الميت إذا كان فيه مرض لا يرجى برؤه أو كبر سن، جاءته امرأة فقالت: يا رسول الله إن أبي شيخ كبير لا يثبت على الراحلة أفأحج عنه؟ قال: حجي عن أبيك، وجاءه آخر فقال: يا رسول الله إن أبي شيخ كبير لا يستطيع الحج ولا الظعن أفأحج عنه وأعتمر؟ قال: حج عن أبيك واعتمر.\nس: العمرة نافلة؟\nالشيخ: نافلة عن الميت له والعاجز، سواء نافلة وإلا فريضة.","link":"https://binbaz.org.sa/fatwas/25155/ما-حكم-الحج-والعمرة-عن-الوالدين-احياء-وامواتا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يعتمر عن أبيه أو أمه.mp3","categories":["إهداء القرب للميت"]},{"id":4886,"question":"أفضل الصَّدقة عن الميت؟","title":"ما أفضل الصَّدقة عن الميت؟","answer":"ما تيسَّر: دراهم، أو طعام، أو ملابس، الذي تيسَّر، ولو شقّ تمرةٍ: اتَّقوا النارَ ولو بشقِّ تمرةٍ.\nس: ما ذُكر أنَّ أفضل الصَّدقة سقي الماء؟\nج: محلُّ نظرٍ، يُروى أنه قال له في قصة سعد بن عُبادة لما أوصى لأمِّه، أوصاه بسقي الماء، ولكن ما أعرف صحَّة اللفظ، هذا أفضل الصدقة: سقي الماء، لكنه من أفضل الصَّدقات، من أفضل الصَّدقة سقي الماء.","link":"https://binbaz.org.sa/fatwas/25395/ما-افضل-الصدقة-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما أفضل الصَّدقة عن الميت.mp3","categories":["إهداء القرب للميت"]},{"id":4985,"question":"بعض الناس يدعو لطعام ويُكلّفون قراءة الإخلاص للميت؟","title":"حكم الدعوة لطعام مع قراءة الإخلاص للميّت","answer":"الجواب: ما له أصل، ما له أصل، لا صنع الطعام ولا القراءة، ما له دليل، أما إذا صنع لهم جيرانهم، أهدوا لهم جيرانهم؛ طيب، مثل ما أمر النبي ﷺ أهله أن يُهدوا لآل جعفر، لما مات جعفر؛ لأنه قد أتاهم ما يشغلهم، جيران الميت إذا أهدوا لأهل الميت عشاء أو غداء؛ طيب، أما أهل الميت يصنعون للناس ويضيفون للناس بسبب الموت، لا، هذا من عمل الجاهلية.","link":"https://binbaz.org.sa/fatwas/28497/حكم-الدعوة-لطعام-مع-قراءة-الاخلاص-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعوة لطعام مع قراءة الإخلاص للميت.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":5291,"question":"سائل يقول: سألت والدتي عن أبي فقالت: كان يعمل الخير ولكنه كان لا يصلي، فهل يجوز لي أن أحج عنه وأستغفر له وأدعو له؟","title":"هل يجوز الاستغفار لميت كان لا يصلي؟","answer":"الجواب: إن كان لا يصلي فهو كافر - نعوذ بالله - لا يُحجّ عنه ولا يُدعى له؛ لقول الله جل وعلا: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى  ۝  وَمَا كَانَ اسْتِغْفَارُ إِبْرَاهِيمَ لِأَبِيهِ إِلَّا عَنْ مَوْعِدَةٍ وَعَدَهَا إِيَّاهُ فَلَمَّا تَبَيَّنَ لَهُ أَنَّهُ عَدُوٌّ لِلَّهِ تَبَرَّأَ مِنْهُ إِنَّ إِبْرَاهِيمَ لَأَوَّاهٌ حَلِيمٌ [التوبة:113-114]. ويقول النبي ﷺ: بين الرجل وبين الكفر والشرك ترك الصلاة ويقول ﷺ: العهد الذي بيننا وبينهم الصلاة فمن تركها فقد كفر فالصلاة عمود الإسلام من حفظها حفظ دينه ومن ضيَّعها أضاع دينه، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/30939/هل-يجوز-الاستغفار-لميت-كان-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 011.mp3","categories":["إهداء القرب للميت"]},{"id":5501,"question":"قراءة القرآن للأموات من أهل العلم مَن قال أنه يصل؟","title":"هل تصل قراءة القرآن للأموات؟","answer":"الجواب: الصواب أنه لا يصل، ذكر الشيخ تقي الدين أنه لا يصل بلا نزاعٍ، قراءة القرآن ما تصل، ولا يجوز أخذ الأجرة عليها أيضًا؛ لأنه لم يرد عن النبي ﷺ ما يدل على وصولها، إنما جاء التقرب بالصدقات والحج والعمرة، هذا يصل، ينفع الأموات، أما مسألة كونه يقرأ لهم، كذلك الدعاء بإجماع المسلمين ينفعهم، الدعاء، أما القراءة لهم ما عليها دليل. س: الذي وردت به النصوص هو الذي يُؤخذ به؟ ج: نعم، العبادات توقيفية.[1]","link":"https://binbaz.org.sa/fatwas/31411/هل-تصل-قراءة-القران-للاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 015.mp3","categories":["إهداء القرب للميت"]},{"id":5719,"question":"..........؟","title":"حكم قراءة القرآن على الميت بعد الدفن","answer":"الجواب: ما نعرف هذا، يسأل عن تلاوة القرآن للموتى، ما له أصل هذا، فالذي يتلو القرآن على الميت بعد ما يموت، أو في القبر، أو على الجنائز في القبر، كل هذا لا أصل له. يعني قراءة القرآن على الموتى في المقابر، أو عند دفنه، أو في الليلة التي مات فيها جلس الناس يقرؤون عليه هذا كله لا أصل له، ولا نعلم له أصلًا في الشريعة.","link":"https://binbaz.org.sa/fatwas/1023/حكم-قراءة-القران-على-الميت-بعد-الدفن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_45.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":5816,"question":"..........؟","title":"الوصية بالصلاة للميت","answer":"الجواب:  لا ما له أصل، لا يصلى عن الأموات، أما الصيام فيصام عنهم، إذا كان عليه صيام، ولا قضى صيام رمضان، أو كفارة، وقد عاش أيام وهو صاح، وطيب، ولا قضى؛ يصام عنه. النبي -عليه الصلاة والسلام- قال: من مات وعليه صيام؛ صام عنه وليه سواء كان الصيام صيام رمضان، أو كفارة، أو نذر، هذا هو الصواب، بعض أهل العلم يقول: لا يصام إلا النذر، وهذا قول ضعيف. والصواب الذي دلت عليه الأحاديث الصحيحة: أنه يصام عنه النذر، وغيره.","link":"https://binbaz.org.sa/fatwas/1134/الوصية-بالصلاة-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_140.mp3","categories":["إهداء القرب للميت"]},{"id":5843,"question":"في المؤتمر الإسلامي الذي عقد في الطائف قيل: إنهم في آخر الجلسة توقفوا قليلًا، وقرؤوا سورة الفاتحة على روح الملك فصيل، فهل هذا النوع من القراءة جائز بأن يدعى جماعة، أو مفرد؟","title":"حكم قراءة الفاتحة وغيرها من السور للموتى","answer":"الجواب:  ما نعرف له أصلًا، كونه يقرأ للأموات سورة الفاتحة، وغيرها ما نعرف له أصلًا، هذا مما أحدثه الناس، وعند بعض أهل العلم يجوز أن يقرأ الإنسان، ويثوبه للميت، قاله جماعة، وحكى بعضهم قول الجمهور كما يصام عنه الصوم، ويتصدق عنه بالمال؛ فقاسوا هذا على هذا، قالوا: لا بأس أن يقرأ للموتى، وتثوب لهم القراءة، ولكن أنا لا أعلم ما يدل في الشرع على ذلك والأولى ترك ذلك. الأولى أن يقرأ لنفسه، ويدعو لنفسه، ويدعو للمسلمين إذا ختم القرآن لا بأس، أما أن يقرأ قراءة، ويثوبها للميت، كالفاتحة، أو البقرة، أو ختمة كاملة ما أعرف له أصلًا، لكن جمهور أهل العلم قالوا: لا بأس بهذا، وأنه مثل ما يتصدق عنه بالمال، أو يدعى له ، أو يحج عنه أن هذا مثله قياسًا عليه، وبعض أهل العلم لم يرتض هذا القياس، وقالوا: لا يقاس في العبادات، والأولى ألا يقرأ أحد لأحد، بل يقرأ لنفسه، ويدعو عند الختمة بما تيسر من الدعوات الطيبة لنفسه، وللمسلمين، وهذا هو الأحوط، والأولى -كما ذكر- والأمر واسع،  إن شاء الله. السؤال: لماذا تخصص الفاتحة فقط؟ الجواب: لأنها أعظم السور، أفضل السور، أعظم سورة في القرآن سورة الفاتحة.","link":"https://binbaz.org.sa/fatwas/1187/حكم-قراءة-الفاتحة-وغيرها-من-السور-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_183.mp3","categories":["إهداء القرب للميت"]},{"id":5988,"question":"وأخ يسأل فيقول: والدتي توفيت، ولم توص أحدًا بأن يحج عنها، هل يجوز لي أن أحج عن والدتي؟","title":"هل الحج عن الوالدة جائز؟","answer":"الجواب: نعم إذا كانت ما حجت تحج عنها الفريضة، وإذا كانت قد حجت فهو نافلة، وجزاك الله خيرًا، هذا من أهم البر، وقد سمعتم الحديث أن النبي ﷺ سأله رجل، فقال: هل بقي من بر والدي شيء أبرهما بعد وفاتهما، قال: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدها، وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما.  فالحج عنهما من أفضل الأعمال، وإنفاذ عهدهما الوصية التي يوصيان بها إذا أوصيان بشيء تنفذ إذا كانت الوصية ما تخالف الشرع، تنفذ الصلاة عليهما، الدعاء لهما، وصلاة الجنازة، والاستغفار لهما.","link":"https://binbaz.org.sa/fatwas/1357/هل-الحج-عن-الوالدة-جاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_315.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":6115,"question":"ما حكم قراءة سورة الفاتحة للميت؟","title":"حكم قراءة سورة الفاتحة للميت","answer":"الجواب: اختلف العلماء في ذلك، بعض أهل العلم يرى أنه لا بأس أن يقرأ القرآن للموتى، ويثوبه للميت، قالوا: إنه كسائر القربات، كما تدعو له، كما تتصدق عنه، كذلك إذا قرأ القرآن .. قالوا: لا بأس أن يثوبها للميت.  وقال آخرون: هذا شيء لم ينقل عن السلف، لا عن الصحابة، ولا عن من بعدهم من السلف المعروفين أنهم فعلوا هذا للميت، ثوبوا له؛ فالأولى تركه، فالأولى ترك ذلك، الأقرب والأولى ترك هذا أن يقرأ لنفسه .. هذا هو الأولى، والأفضل، والأحوط. السؤال:.. الشيخ: ما له أصل، النبي ﷺ دفن كثيرًا من الصحابة، ولم يقرأ عند القبر -عليه الصلاة والسلام- هذا من البدع، عند القبر يكون الوعظ، والتذكير لله، والتذكير بالآخرة، والتذكير بالقبر، وما فيه من الأهوال، هذه السنة، أما أن يقرأ عند القبر لا. النبي ﷺ لما جلس عند القبر، وحوله الناس؛ ذكرهم، ووعظهم، ذكرهم بأمر القبور، وأمر الجنة، والنار؛ حتى يستعدوا للقاء الله، يذكر الأحياء الحاضرين.","link":"https://binbaz.org.sa/fatwas/1541/حكم-قراءة-سورة-الفاتحة-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_471.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":6297,"question":"هل يصل ثواب القرآن إلى الميت، أم لا؟","title":"حكم وصول ثواب القرآن للموتى","answer":"الجواب:  هذا فيه خلاف بين أهل العلم، فبعض أهل العلم يرى أنه يصل، وقال الآخرون: أنه لا يصل؛ لأنه لم يرد عن السنة، فالأقرب والأولى أنه لا يستعمل.  ولكن يصل للميت الصدقة، والدعاء، والحج عنه، والعمرة عنه، وقضاء الصيام إن كان عليه صيام، هذا ينفعه، ويصل إليه. أما قراءة القرآن فليس عليها دليل، فالأولى ترك التلاوة للميت، وإنما يستعمل مع الميت الصدقة عنه، والدعاء بالمغفرة، والرحمة، وصلاة الجنازة، والاستغفار له، والحج عنه، والعمرة كل هذا يفيده.","link":"https://binbaz.org.sa/fatwas/1791/حكم-وصول-ثواب-القران-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_630.mp3","categories":["إهداء القرب للميت"]},{"id":6392,"question":"من هم الأقارب الذين تجب صلة الرحم معهم، وتكون واجبة في حقهم؟","title":"تحديد الأقارب الذين يجب صلتهم","answer":"الجواب: كل الأقارب يوصلون، لكنهم يتفاوتون في القرب، فكل من كان أقرب؛ صارت صلته أوجب، فأقربهم الآباء، والأمهات، وإن علوا، والأولاد وأولاد البنين، والبنات، وإن نزلوا، ثم يليهم الإخوة، والأخوات، ثم بنو الإخوة، وبنات الإخوة، ثم الأعمام، والعمات، وهكذا. يقول النبي -عليه الصلاة والسلام- لما سئل، قال له رجل: أي الناس أحق بالصحبة وفي لفظ بحسن الصحبة؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟  قال: أمك قال: ثم من قال: أبوك، ثم الأقرب فالأقرب وفي اللفظ الآخر: يا رسول الله من أبر؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من في الرابعة قال: أباك، ثم الأقرب، فالأقرب فهو مأمور بأن يبر والديه، ثم الأقرب، فالأقرب، كأولاده، وإخوته، ونحو ذلك.","link":"https://binbaz.org.sa/fatwas/1968/تحديد-الاقارب-الذين-يجب-صلتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_755.mp3","categories":["النيابة في الحج","إهداء القرب للميت","فضائل الأعمال"]},{"id":6727,"question":"رجل زار قبور أقاربه، وبعد الزيارة ذبح ذبيحة لله صدقة، وقال: أجرها لهؤلاء الموتى، فما حكم ما فعله؟","title":"حكم الذبح والتصدق به وإهداء الثواب للموتى","answer":"الجواب: لا بأس، إذا تصدق عنهم بذبيحة  .. سواء قبل الزيارة، أو بعد الزيارة، الزيارة سنة، زيارة القبور، والدعاء لهم بذكر الآخرة، وذكر الموت، فإذا ذبح ذبيحة، وتصدق بها عن موتاه المسلمين، أو تصدق بنقود، أو ملابس، أو فرش، أو غير هذا؛فهو يلحق الموتى، وينفعهم.","link":"https://binbaz.org.sa/fatwas/2609/حكم-الذبح-والتصدق-به-واهداء-الثواب-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1105.mp3","categories":["إهداء القرب للميت"]},{"id":6924,"question":"هل يجوز أن أقرأ، وأختم المصحف، وأهديه إلى والدي، وهما الآن متوفيان؟","title":"حكم إهداء قراءة القرآن للوالدين","answer":"الجواب: لم يرد في هذا ما يدل على شرعية ذلك؛ وإن كان بعض أهل العلم يرى إهداء القرآن، لكن لم يرد فيه دليل. فالأفضل: أن تدعو لهما، وأن تتصدق عنهما بالمال، هذا هو المشروع المجمع عليه بين أهل العلم.","link":"https://binbaz.org.sa/fatwas/2852/حكم-اهداء-قراءة-القران-للوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1300.mp3","categories":["إهداء القرب للميت","القرآن وعلومه"]},{"id":6945,"question":"في الجنوب إذا مات ولد، أو بنت، أو ماتت بنت، وهو صغير السن؛ يتصدقون على نيته، مع العلم أنه في شهور، ولم يبلغ المتوفي في عمره سنة، وهذه الصدقة لها صفة خاصة، فمثلًا يتصدقون بهدبة.. وهو جلد، وبعض الأشياء العينية، أفتونا باركم الله فيكم؟","title":"حكم الصدقة عن الطفل المتوفى","answer":"الجواب: الصغار لا .. عليهم، الذين ماتوا قبل الحلم لا ذنب عليهم، لكن إذا تصدق عنه أهله؛ فهي تزيده خيرًا، الصدقة تزيده خيرًا، تنفعه، ولو كان صغيرًا، لكن إذا كانت الصدقة على طريقة خاصة، يتعبدون بها، نوع معين يفعلونه في يوم معين؛ فهي بدعة. أما صدقة مطلقة، مثل ما يتصدقون على آبائهم، وأمهاتهم، ويتصدقون على أولادهم، متى تيسرت الصدقة، في أي وقت، في أي مكان؛ لا بأس، أما يخص هذا بيوم معين، أو دراهم معينة، أو طعام معين، هذا يكون بدعة.","link":"https://binbaz.org.sa/fatwas/2875/حكم-الصدقة-عن-الطفل-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1323.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":7076,"question":"رجل مات وهو مدمن الخمر، والزنا، وقتل النفس التي حرم الله، فهل يستحق الترحم له بعد الموت؟","title":"حكم الترحم على مرتكب الكبائر","answer":"الجواب:\n\nإذا كان مسلمًا معروفًا أنه كان موحدًا، ومسلمًا، يؤمن بالله واليوم الآخر، ولكن بُلي بهذه المعاصي؛ فلا مانع من الدعاء له، والله يغفر لنا وله وللمسلمين، يدعى له بالمغفرة والرحمة؛ لأن المعاصي ما تخرجه من الإسلام، الخمر، والزنا، وأشباه ذلك، ما يخرجه من الإسلام عند أهل السنة والجماعة، لكن يكون ضعيف الإيمان.\n\nأما إن كان معروفًا بشيء آخر يدل على كفره، مثل سب الدين، مثل إنكار وجوب الصلاة، إنكار وجوب الزكاة، الاستهزاء بالدين، هذا كافر، ما يدعى له، ولا يترحم عليه، أما إذا كان معروفًا بمحبة الإسلام، وأنه مسلم يصلي وموحد، لا يشرك بالله شيئًا، ولكن بُلي بهذه القاذورات، بهذه المعاصي؛ فهذا يدعى له، وأمره إلى الله.","link":"https://binbaz.org.sa/fatwas/3082/حكم-الترحم-على-مرتكب-الكباىر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1465.mp3","categories":["إهداء القرب للميت","مسائل متفرقة في العقيدة"]},{"id":7217,"question":"إذا كان ولد له أم ما تصلي إلا أنها يعني مقرة بالتوحيد يعني، وماتت، وهي تاركة للصلاة نهائيًا، وعارفة الحكم في ترك الصلاة، وعلى عقيدة شرك في الأولياء والصالحين وشيء من هذا، تعتقد فيهم، هل يضحي لها، يستغفر لها؟","title":"إهداء الثواب للميت إذا كان مقرًا بالتوحيد ولكنه لا يصلي","answer":"الجواب:\n\nلا لا، من مات على الشرك لا يستغفر له، النبي ﷺ استأذن ربه أن يستغفر لأمه -وماتت في الجاهلية- فلم يأذن له  أذن له أن يزورها، ولم يأذن له أن يستغفر لها، وهكذا لم يأذن له أن يستغفر لعمه أبي طالب، مع أنه نصره وحماه، وأنزل الله في هذا: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى [التوبة:113].\n\nفلا يستغفر للمشرك، ولو أنها أمه إذا ماتت على الشرك، أو على ترك الصلاة، لا يستغفر لها، ولا يدعى لها، لكن لا يدعى عليها، لا يدعى لها ولا يدعى عليها، لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا، لكن من مات على الشرك ولو كان والدًا، ولو كان أمًا، ولو كان أخًا، لا يدعى له، ولا يستغفر له، نسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/3275/اهداء-الثواب-للميت-اذا-كان-مقرا-بالتوحيد-ولكنه-لا-يصلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1600.mp3","categories":["قضاء الصيام","حكم الصلاة وأهميتها","إهداء القرب للميت"]},{"id":7594,"question":"الرسالة هذه وردتنا من العراق من الجمهورية العراقية، محافظة واسط من المسلم هادي مطشر عيال يقول في رسالته هذه يسأل عن البر بالوالد الكافر بعد موته، يقول: إني أنا وأخي قد آمنا بالله الواحد الأحد، فله الحمد أنه هدانا، ونحن نعيش في قرية مملوءة بالكفر والشرك والظلم خصوصاً العائلة التي نعيش فيها أنا وأخي، وأني أطرح عليكم مشكلتي وهي: لقد توفي أبونا ونحن أطفال وكانت لنا أم لا تؤمن بالله تعالى، وكثيرة الكفر، وعندما سألناها عن أبينا هل هو مؤمن أم لا؟ فقالت لنا: إنه كان يسرق الناس أشياءهم وليس مؤمن بالله بل يقول في لسانه: الله ربنا محمد نبينا، لكنه لا يقيم الصلاة، بصراحة إنه كما يقول الناس وخصوصاً أمنا: إنه لا يؤمن باليوم الآخر، وعندما مات لم يترك لي ولأخي مال ولا حلال، سؤالي هو: أولاً: هل أقوم بذبح الضحايا له أم يكون ذلك حرام علي؟","title":"حكم القيام بأعمال البر للوالد الكافر بعد موته","answer":"الجواب: هذا السؤال إذا كانت الوالدة ما هناك ما يكذبها فإن مثل هذا لا يضحى له ولا يستغفر له؛ لأنه يترك الصلاة، وتارك الصلاة كافر على أصح قولي العلماء، أما إذا وجد غيرها ممن يعرفه يسأل عنه إذا وجد من يعرفه أنه يصلي وأنه مستقيم فلا بأس أن يضحى له ولا بأس أن يدعى له ويستغفر له ويتصدق عنه، أما هي فهي ليست ثقة ما دامت كافرة لا تؤمن بالله واليوم الآخر فهي ليست ثقة في الخبر، لكن إذا وجد ما يصدقها من القرائن والدلائل التي تصدقها فيما قالت أو شهادة بعض الناس فإنه لا يضحى له ولا يصدق عليه، أما إذا كان ما هنا إلا شهادة الوالدة وليس هناك ما يؤيدها وقد عرف أنه يشهد أن لا إله إلا الله وأن محمداً رسول الله وغالبه يتظاهر بالإسلام، فلا ينبغي ترك الصدقة عنه والدعاء له بل يدعى له ويتصدق عنه حتى يعرف أنه كان يتعاطى شيئاً من المكفرات التي تكفره تخرجه عن الإسلام؛ إما ترك الصلاة، وإما الاستهزاء بالدين، وإما سب الدين، وإما شبه ذلك من نواقض الإسلام. \nفحينئذ لا يدعى له ولا يصلى ولا يتصدق عنه ولا يضحى عنه، أما هي وحدها لا تكفي؛ لأن شهادة الكافر لا تعتبر ولكن إذا وجد ما يؤيدها من قرائن أو شهادة آخرين بأنه لا يصلي فلا يضحى له ولا يتصدق عنه ولا يستغفر له. \nالمقدم: المرسل هادي يقول: لكنه لا يقيم الصلاة، بصراحة إنه كما يقول الناس وخصوصاً أمنا، الناس يقولون له: إن أباك..؟ \nالشيخ: إذا كان مشهور عند الناس أنه لا يصلي فلا يدعى له ولا يضحى عنه. نعم.","link":"https://binbaz.org.sa/fatwas/4647/حكم-القيام-باعمال-البر-للوالد-الكافر-بعد-موته ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_020/02002.mp3","categories":["إهداء القرب للميت"]},{"id":7630,"question":"أيضاً يقول لي والدي: كنت أجمع هذا الدعاء وأنا أشاهد اللوح المحفوظ، لا أيضاً قبله يقول: في إهداء قراءة القرآن الكريم لروح الرسول ﷺ وإلى أرواح الأموات؟","title":"حكم إهداء القرآن إلى الميت","answer":"الجواب: هذا لا أصل له أيضاً، إهداء القرآن ليس بمشروع ولا فعله الصحابة ، والخير في اتباعهم، ولكن الرسول ﷺ يعطى مثل أجورنا، ما فعلنا من خير فله من أجورنا؛ لأنه الدال على الخير عليه الصلاة والسلام، وقد قال عليه الصلاة والسلام: من دل على خير فله مثل أجر فاعله فهو الذي دل أمته على الخير وأرشدهم إلى الخير، فإذا قرأ الإنسان أو صلى أو صام أو تصدق فالرسول يعطى مثل أجور هؤلاء من أمته؛ لأنه هو الذي دلهم على الخير وأرشدهم إليه عليه الصلاة والسلام. \nأما أن يهدى.. يقرأ ويهدي له فليس لهذا أصل، والأولى ترك ذلك، اللهم صل عليه وسلم. نعم. \nكذلك الإهداء للأموات ليس له أصل، فالأولى ترك ذلك، وبعض أهل العلم يجوز أن يقرأ الإنسان الحزب من القرآن أو الختمة ثم يقول: (اللهم اهد ثوابها لأبي أو لأمي) أجاز هذا جمع من أهل العلم، وآخرون قالوا: ترك ذلك أولى؛ لأنه لم يرد عن النبي صلى الله عليه وسلم ولا عن الصحابة، فالأولى تركه وهذا هو الأرجح، الأرجح أن الأولى ترك تثويب القرآن للناس؛ لأن ليس عليه دليل، وليس من فعل السلف الصالح، فالأولى ترك ذلك، إنما جاءت الصدقة عن الميت، الدعاء له، الحج عنه، الصوم عنه، إذا كان عليه صوم هذا لا بأس به. \nأما كونه يقرأ قراءة ويثوبها للميت أو يصلي هذا لا، ليس له أصل معروف، فالأولى تركه، فلا يصلي أحد لأحد، ولا يقرأ أحد لأحد، هذا هو الأفضل وهذا هو الأحوط، لأنه لم يرد عن السلف الصالح، والخير في اتباعهم والسير على منهاجهم . نعم.","link":"https://binbaz.org.sa/fatwas/4684/حكم-اهداء-القران-الى-الميت ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_025/02506.mp3","categories":["إهداء القرب للميت"]},{"id":7665,"question":"من بغداد أيضاً من أم علا تقول: هل يحق للبنت المتزوجة أن تقوم بتوزيع الثواب لوالدتها المتوفية، علماً بأن الزوج موافق على القيام بالثواب على نفقة الزوج، وختاماً لكم الشكر الجزيل؟","title":"هل للزوجة أن تتصدق عن والدتها المتوفية؟","answer":"الجواب: لا مانع من الصدقة على والديها المسلمين من مالها أو من مال الزوج إذا سمح، كونها تتصدق من مالها أو من مال الزوج ما يسر الله من المال لوالديها المسلمين أو لأخوتها المسلمين أو لخالاتها أو لعماتها أو لأولادها لا بأس، ثبت عنه ﷺ ما يدل على ذلك وأن امرأة قالت: يا رسول الله! إن أمي ماتت ولم توص وأظنها لو تكلمت تصدقت، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم، وقد أجمع المسلمون أجمع علماء الإسلام على أن الصدقة تلحق الميت وتنفع الميت وهكذا الدعاء، فإذا تصدق الإنسان عن والديه المعروفين بالإسلام أو دعا لهم ينفعهم ذلك، سواء كان المال من ماله الخاص أو من مال غيره إذا سمح له بذلك، مثل الزوج إذا أعطى زوجته وقال: لا بأس تصدقي من مالي أو أخيها قال: تصدقي منه أو قال لها أبوها كذلك، أو عمها إذا أعطاها مالاً تتصدق به فلا بأس ينفع الميت إذا كان الميت مسلم، أما إذا كان الميت كافر لا ما يتصدق عن الكافر إنما هذا في حق الميت المسلم. نعم.","link":"https://binbaz.org.sa/fatwas/4839/هل-للزوجة-ان-تتصدق-عن-والدتها-المتوفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_038/03804.mp3","categories":["إهداء القرب للميت"]},{"id":7965,"question":"أيضاً يقول: أرجو إفادتي عن قراءة الإخلاص على روح الموتى في أي وقت من الأوقات أو في أي مكان من الأمكنة، إني في انتظار إرشادكم أرشدكم الله؟","title":"حكم قراءة سورة الإخلاص على روح الموتى","answer":"الجواب: لا نعلم لقراءة سورة الإخلاص للموتى شيئاً واضحاً ولا واردة عن السلف الصالح، لكن الأكثر يجوز عندهم أن تقرأ القرآن وأن تثوب ثوابه لوالديك أو غيرهم، هذا يراه الأكثر من أهل العلم، وأنه لا حرج في ذلك، أما تخصيص سورة معينة لبعض الناس هذا لا نعلم له أصلاً، ولا نعلم أصلاً أيضاً لثثويب القرآن، ولكن أهل العلم الذين أجازوه قاسوه على الصوم وقاسوه على الدعاء والصدقة، هذا وجه ما قاله الأكثرون من جواز تثويب القرآن لوالديك أو غيرهم.\nوأما تخصيص سورة الإخلاص أو الكافرون أو سورة من السور أو آية تثوبها لأناس معينين ما نعلم له أصلاً إلا أنه داخل في العموم عند من أجاز تثويب القرآن، والأولى عندي والأفضل عندي عدم فعل ذلك لعدم النقل عن السلف الصالح، ويكفي الدعاء والصدقة، الدعاء لهم والصدقة عنهم. نعم.","link":"https://binbaz.org.sa/fatwas/5485/حكم-قراءة-سورة-الاخلاص-على-روح-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_069/06906.mp3","categories":["إهداء القرب للميت"]},{"id":7976,"question":"هذه رسالة وردت من المستمع يقول: أخوكم في الإسلام رضوان آدم محمد تورين ، يقول: كانت لي والدة قد توفيت قبل عامين، وأنا فقير لا أملك شيئاً من المال كي أتصدق به عليها ولا أحفظ دعاءً كبير أدعو به لها، ولكن أريد أن أقرأ وأرتل القرآن وأهب هذا الأجر والثواب العظيم الذي وعد به الله الذين يرتلون القرآن، فهل يجوز لي هذا الترتيل والقراءة، أفيدوني جزاكم الله خيراً، وشكراً لكم؟","title":"حكم إهداء ثواب الأعمال للميت","answer":"الجواب: تدعو لها بالدعوات الطيبة، تسأل الله لها الجنة، تسأل الله لها السلامة من النار، تسأل الله لها المغفرة والرحمة، هذه دعوات طيبة، تتصدق عنها بما تيسر ولو درهماً واحداً، ولو طعاماً قليلاً، ولو شيئاً من الملابس كل هذا ينفعها، أما تثويب القرآن لها وإهداء القرآن لها فهذا محل خلاف، أكثر أهل العلم يرونه لا بأس به وأنه ينفعها، وبعض أهل العلم يرى أن هذا لم يرد عن النبي ﷺ فلا وجه لإهدائه؛ لأنه لم يرد كالصلاة، فكما أنه لا يصلى لها لا يهدى لها القرآن، هذا قول جماعة من أهل العلم وهو أظهر في الدليل.\nفالأولى: أن تعتني بالدعاء لها، والترحم عليها، والصدقة عنها بما تيسر ولو بالقليل، والدعاء -بحمد الله- ميسور، الدعاء واضح وميسور تقول: اللهم اغفر لأمي، اللهم أدخلها الجنة، اللهم أنجها من النار، اللهم اعف عنها، اللهم ارفع منزلتها في الجنة، اللهم أجزها عني خيرا، وما أشبهها هذا من الدعوات الطيبة. نعم.","link":"https://binbaz.org.sa/fatwas/5533/حكم-اهداء-ثواب-الاعمال-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07206.mp3","categories":["إهداء القرب للميت"]},{"id":7984,"question":"هذه رسالة وردت من المستمع يقول: أخوكم في الإسلام رضوان آدم محمد تورين ، يقول: كانت لي والدة قد توفيت قبل عامين، وأنا فقير لا أملك شيئاً من المال كي أتصدق به عليها ولا أحفظ دعاءً كبير أدعو به لها، ولكن أريد أن أقرأ وأرتل القرآن وأهب هذا الأجر والثواب العظيم الذي وعد به الله الذين يرتلون القرآن، فهل يجوز لي هذا الترتيل والقراءة، أفيدوني جزاكم الله خيراً، وشكراً لكم؟","title":"حكم إهداء ثواب الأعمال للميت","answer":"الجواب: تدعو لها بالدعوات الطيبة، تسأل الله لها الجنة، تسأل الله لها السلامة من النار، تسأل الله لها المغفرة والرحمة، هذه دعوات طيبة، تتصدق عنها بما تيسر ولو درهماً واحداً، ولو طعاماً قليلاً، ولو شيئاً من الملابس كل هذا ينفعها، أما تثويب القرآن لها وإهداء القرآن لها فهذا محل خلاف، أكثر أهل العلم يرونه لا بأس به وأنه ينفعها، وبعض أهل العلم يرى أن هذا لم يرد عن النبي ﷺ فلا وجه لإهدائه؛ لأنه لم يرد كالصلاة، فكما أنه لا يصلى لها لا يهدى لها القرآن، هذا قول جماعة من أهل العلم وهو أظهر في الدليل.\nفالأولى: أن تعتني بالدعاء لها، والترحم عليها، والصدقة عنها بما تيسر ولو بالقليل، والدعاء -بحمد الله- ميسور، الدعاء واضح وميسور تقول: اللهم اغفر لأمي، اللهم أدخلها الجنة، اللهم أنجها من النار، اللهم اعف عنها، اللهم ارفع منزلتها في الجنة، اللهم أجزها عني خيرا، وما أشبهها هذا من الدعوات الطيبة. نعم.","link":"https://binbaz.org.sa/fatwas/5533/حكم-اهداء-ثواب-الاعمال-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_072/07206.mp3","categories":["إهداء القرب للميت"]},{"id":8085,"question":"يقول: وما يفضل القول عند الميت قبل موته؟ نرجو الإفادة.الشيخ: نعم أيش؟المقدم: يريد ما الذي يقال عند الميت عند موته؟","title":"مشروعية الدعاء للميت عند موته","answer":"الجواب: لا يقال إلا خير: اللهم اغفر له، اللهم ارحمه، اللهم ثبته على الحق.. ونحوه الكلام طيب، مثلما قال النبي ﷺ: لا تدعوا إلا بخير، فإن الملائكة تؤمن على ما تقولون عند الميت لا يقال إلا خير؛ من دعاء طيب.. من ذكر الله.. من استغفار والدعاء له بالمغفرة والرحمة.","link":"https://binbaz.org.sa/fatwas/5878/مشروعية-الدعاء-للميت-عند-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_085/08503.mp3","categories":["إهداء القرب للميت","الأدعية والأذكار"]},{"id":8434,"question":"رسالة من السودان الخرطوم باعثها أخونا كمال علي محمد الكروق فيما يبدو أخونا يقول: منذ أن توفيت والدته وهو يصلي لها ركعتين؛ كأنه يريد أنه يصلي عنها نيابة سماحة الشيخ، ويسأل: هل عمله هذا صحيح أم لا؟","title":"حكم إهداء ثواب الصلاة للميت","answer":"الجواب: لا، ليس بصحيح، المشروع الدعاء لها، والترحم عليها، والصدقة عنها، أو الحج عنها، أو العمرة لا بأس، أما الصلاة لها لا، لم يشرع لنا أن نصلي عن الأموات، ولكن الحج لا بأس، العمرة لا بأس، الصدقة كل هذا مشروع، والدعاء والترحم عليهم كما قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له ما قال: يصلي له، قال: يدعو له، فتدعو لوالدتك، تستغفر لها، وتسأل الله لها الرحمة والمنزلة العالية في الجنة، وغفران الذنوب، تتصدق عنها مما تيسر من الطعام من النقود من الملابس على الفقراء والمحاويج كل هذا طيب.","link":"https://binbaz.org.sa/fatwas/6318/حكم-اهداء-ثواب-الصلاة-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11911.mp3","categories":["إهداء القرب للميت"]},{"id":8495,"question":"أخت لنا بعثت برسالة تقول فيها: أختكم في الله (ع. ع. ك) بدأت رسالتها بقولها: يسعدني أن أتقدم للقائمين على برنامج نور على الدرب الذي أنار قلوبنا وعقولنا بمنافعه الجمة وفوائده العظيمة بخالص شكري وامتناني، وأسأل الله تعالى أن يكلل جهودكم بالنجاح والسداد ويجزيكم عن المسلمين خير الجزاء، أستسمحكم بمشاركة لي أرجو عرضها على فضيلة الشيخ الموقر عبد العزيز بن عبد الله بن باز حفظه الله وبارك فيه.سؤالي الأول: والدتي أمية لا تعرف القراءة والكتابة، فهل يجوز لي أن أقرأ القرآن في فترة حياتها وأنوي ثوابه لها، وإذا كان يجوز فما حكم التلفظ بالنية في هذه الحالة، تنبيه: والدتي حية ترزق وأنا أعلم أنه لا يجوز القراءة للميت؟","title":"حكم قراءة القرآن وإهداء ثوابه للحي أو الميت","answer":"الجواب: هذه المسألة فيها خلاف بين أهل العلم، من أهل العلم من قال: يجوز أن يقرأ الإنسان للميت ويثوب له أو للحي ويثوب له، ولكن هذا ليس عليه دليل، والأظهر: أنه لا ينبغي هذا الأمر وأن الأولى والأحوط أن لا يقرأ أحد لأحد؛ لأن هذا لم يفعله النبي ﷺ ولا أصحابه رضي الله عنهم وأرضاهم، والعبادات أصلها توقيفي فلا يفعل منها إلا ما جاء به الشرع لقوله ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد.\nفالذي أنصح به أن لا تقرئي لها شيئاً سواء كانت حية أو ميتة، ولكن ما دامت حية والحمد لله تعلمينها ما تيسر حتى تستفيد، تعلمينها بعض السور القصيرة تصبرين على تعليمها، كما تعلمينها الفاتحة إذا كانت لا تحسنها وتجتهدين في ذلك وتصبرين وأنت على خير عظيم، والنبي ﷺ يقول: خيركم من تعلم القرآن وعلمه خيار الناس من تعلم القرآن الكريم وعلمه الناس، واستفاد من ذلك وعمل به، فأنت على خير عظيم في تعليم الوالدة وإرشادها وتحفيظها ما تيسر من كتاب الله ولك الأجر العظيم.\nأما الدعاء لها والصدقة عنها في المال هذا شيء طيب ينفعها حية وميتة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6555/حكم-قراءة-القران-واهداء-ثوابه-للحي-او-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12609.mp3","categories":["إهداء القرب للميت"]},{"id":8844,"question":"سؤاله الثاني يقول: توجد عقيدة في بعض الناس إذا توفي منهم أحد الأسرة يذبحون ذبيحة بعد شهر، ويقصدون بذلك قطع الشهر، وعقيدتهم الثانية: لا يأكل من الذبيحة من أسرة المتوفى أحد، ونرجو التوجيه حول هذه المعتقدات؟","title":"حكم الذبح عن الميت كل شهر","answer":"الجواب: هذه بدعة لا وجه لها ولا أساس لها، والواجب تركها؛ لأن الرسول عليه السلام يقول: من عمل عملًا ليس عليه أمرنا فهو رد يعني: فهو مردود، وكان يخطب ﷺ يوم الجمعة ويقول في خطبته: أما بعد: فإن خير الحديث كتاب الله، وخير الهدي هدي محمد صلى الله عليه وسلم، وشر الأمور محدثاتها، وكل بدعة ضلالة فكونه يذبح عن الميت كل شهر أو كل شهرين أو كل سنة أو كل أربعين يومًا هذا لا أساس له، إنما يشرع الضحية، إذا ضحى في أيام عيد النحر عن نفسه وعن أهل بيته وعن أمواته فلا بأس، فقد كان النبي ﷺ يضحي يوم العيد بكبشين أملحين يذبحهما، أحدهما يذبحه عن محمد وآل محمد، والثاني يذبحه عمن وحد الله من أمته، فهذه يقال لها: الضحية، وهي سنة، كان النبي يفعلها ﷺ ويستمر في ذلك كل سنة.\nفالسنة للأمة أن تذبح ذلك، يضحي الإنسان عن نفسه وعن أهل بيته بأضحية واحدة، وإذا ضحى بأكثر فلا بأس، وإن ضحى عن نفسه بواحدة وعن أمه واحدة وعن أبيه واحدة فلا بأس، صدقة.\nأما أن يجعل شيء من أجل الميت يفعل بالشهر أو بالأسبوع أو بالسنة يأكله فلان وفلان، أو لا يأكله فلان ولا فلان، كل هذا لا أصل له، بل هو من البدع ومن أمر الجاهلية. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/6999/حكم-الذبح-عن-الميت-كل-شهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_166/16602.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":8876,"question":"تقول في سؤالها الثاني: هل يجوز أن أختم القرآن لوالدي علماً أنهما أميان لا يقرأان ولا يكتبان، وهل يجوز أن أختم القرآن لشخص يعرف القراءة والكتابة ولكني أريد إهداءه هذه الختمة، وهل يجوز لي أن أختمه لأكثر من شخص؟","title":"حكم إهداء ثواب قراءة القرآن للآخرين","answer":"الجواب: لم يرد في كتابه العزيز ولا في السنة المطهرة عن الرسول عليه الصلاة والسلام ولا عن أصحابه رضي الله عنهم ما يدل على الإهداء بقراءة القرآن لا للوالدين ولا لغيرهما، وإنما شرع الله قراءة القرآن للانتفاع به والاستفادة منه وتدبر معانيه والعمل بذلك، كما قال الله سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] ، قال : إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قال سبحانه: قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] .\nقال النبي ﷺ: اقرءوا القرآن فإنه يأتي شفيعاً لأصحابه يوم القيامة، ويقول عليه الصلاة والسلام: إنه يؤتى بالقرآن يوم القيامة وأهله الذين يعملون به تقدمه سورة البقرة وآل عمران تحاجان عن أصحابهما .\nفالمقصود أنه أنزل للعمل به وتدبره والإكثار من قراءته من أجل الثواب، والمقصود الأعظم هو العمل بهذا الكتاب العظيم، أما الإهداء للوالدين أو لغير الوالدين فلا أعلم له أصلاً يعتمد عليه وإن كان قاله بعض أهل العلم، وقالوا: إنه لا مانع من إهداء ثواب القرآن وغيره من الأعمال الصالحات، هذا قاله جماعة من أهل العلم لكن لا أعلم دليلاً عليه واضحاً من الكتاب أو من السنة وإنما جاء الإهداء في الصدقة، يتصدق، يدعو لوالديه ولغيرهما كل هذا طيب، يحج يعتمر لا بأس عن والديه الميتين أو العاجزين لكبر سنهما، أما إهداء القرآن أو إهداء الصلاة أو إهداء الصوم أو إهداء التسبيح والتهليل هذا لا نعلم لها أصلاً.\nفالذي ننصح به ونشير به ونوصي به الترك وعدم الإهداء لكتاب الله ولا للعبادات البدنية كالصلاة ونحوها، وإنما الإهداء يكون بما شرعه الله من الصدقة والدعاء، أو الحج والعمرة للميتين أو العاجزين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7032/حكم-اهداء-ثواب-قراءة-القران-للاخرين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13902.mp3","categories":["إهداء القرب للميت"]},{"id":8921,"question":"ننتقل إلى السؤال الثاني في رسالة الأخ أبو صلاح الدين من الرياض يقول: لي والدة لا تقرأ وأحب أبرها وكثيراً ما أقرأ القرآن وأجعل ثوابه لها، ولما سمعت أنه لا يجوز عدلت عن ذلك وأخذت أتصدق عنها بدراهم وهي الآن حية على قيد الحياة فهل يصل ثواب الصدقة من مال وغيره إليها، سواء كانت حية أو ميتة، أم لا يصل إلا الدعاء حيث لم يرد إلا ذلك، كما في الحديث: إذا مات العبد انقطع عمله إلا من ثلاث -وذكر-: ولد صالح يدعو له ، وهل الإنسان إذا كان كثير الدعاء لوالديه في الصلاة وغيرها قائماً وقاعداً يشهد له الحديث بأنه صالح ويرجى له خير عند الله، أرجو الإفادة ولكم من الله الثواب الجزيل؟","title":"حكم قراءة القرآن عن الميت والصدقة عنه","answer":"الجواب: أما القرآن -قراءة القرآن- فقد اختلف العلماء هل تصل الميت يعني: ثوابها إلى الميت على قولين لأهل العلم، والأرجح بالدليل أنها لا تصل لعدم الدليل؛ لأن الرسول ﷺ لم يفعلها لأموات المسلمين، كبناته اللاتي متن في حياته عليه الصلاة والسلام، ولم يفعلها الصحابة رضي الله عنهم وأرضاهم، فالأولى بالمؤمن أن يترك ذلك ولا يقرأ للموتى ولا للأحياء ولا يصلي لهم أيضاً صلاة ذات الحق، وهكذا التطوع بالقراءة وهكذا التطوع بالصوم كل هذا لا دليل عليه، أما الصدقة فإنها تنفع الحي والميت بإجماع المسلمين.\nوهكذا الدعاء ينفع الحي والميت بإجماع المسلمين، وإنما جاء الحديث فيما يتعلق بالميت؛ لأنه محل الإشكال للميت هل يلحقه أو ما يلحقه، ولهذا جاء الحديث يقول ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له ، لما علم أن الموت تنقطع به الأعمال بين النبي ﷺ أن هذا لا ينقطع، وأما الحي فلا شك فيه أنه ينتفع بالصدقة منه ومن غيره، وينتفع بالدعاء، فالذي يدعو لوالديه وهم أحياء ينتفعون بدعائه وهكذا الصدقة عنهم وهم أحياء ينفعهم، وهكذا الحج عنهم إذا كانوا عاجزين، إذا كان الشيخ كبير، يعني الأب كبير لا يستطيع الحج أو المرأة أو الأم فإنه ينفعهم ذلك، ولهذا ثبت عنه صلى الله عليه وسلم أن امرأة قالت: يا رسول الله! إن فريضة الله في الحج أدركت أبي شيخاً كبيراً لا يثبت على الراحلة أفأحج عنه؟ قال: حجي عنه، وجاءه رجل آخر فقال: يا رسول الله! إن أبي شيخ كبير لا يستطيع الحج ولا الضعن أفأحج عنه؟ قال: حج عن أبيك واعتمر.\nفهذا يدل على أن الحج عن الميت وعن الحي العاجز لكبر سنه والمرأة العاجزة لكبر سنها ينتفع بذلك، فالصدقة والدعاء والحج عن الميت والعمرة عنه وهكذا عن العاجز كل هذا ينفعه عند جميع أهل العلم.\nوأنت أيها السائل على خير إن شاء الله في إحسانك إلى والديك والصدقة عنهما والدعاء لهما ولاسيما إذا كان الولد صالحاً صار أقرب إلى إجابة الدعاء، ذكر الرسول ﷺ: (أو ولد صالح)، لأن الولد الصالح أقرب إلى أن يجاب من الولد الفاسق وإن كان الدعاء مطلوب من الجميع للوالدين لكن إذا كان الولد صالحاً صار أقرب إلى إجابة دعوته لوالديه. نعم.","link":"https://binbaz.org.sa/fatwas/7078/حكم-قراءة-القران-عن-الميت-والصدقة-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_142/14202.mp3","categories":["إهداء القرب للميت"]},{"id":8970,"question":"أخ لنا من سوريا يقول غزوان الصواف: أرجو من سماحة الشيخ عبدالعزيز بن عبدالله بن باز أن ينبه الناس في الدول الإسلامية إلى حكم قراءة القرآن على الأموات، هل تجوز أم لا؟ وما حكم الأحاديث الواردة في ذلك؟ جزاكم الله خيراً.","title":"حكم قراءة القرآن بنية الإهداء إلى الأموات","answer":"الجواب: القراءة على الأموات ليس لها أصل يعتمد عليه ولا تشرع، وإنما المشروع القراءة بين الأحياء ليستفيدوا ويتدبروا كتاب الله ويتعقلوه، أما القراءة على الميت عند قبره أو بعد وفاته قبل أن يقبر أو القراءة في مكان بعيد حتى تهدى له فهذا لا نعلم له أصلاً، وقد صنف العلماء في ذلك وكتبوا في هذا كتابات كثيرة، منهم من أجاز أن يثوب له القرآن وأن يتلى له ختمات.\nومن أهل العلم من قال: هذه أمور توقيفية.. هذه عبادات، فلا يجوز أن يفعل منها إلا ما أقره الشرع، والنبي ﷺ قال: من عمل عملاً ليس عليه أمرنا فهو رد، وليس هناك شيء نجزم به في هذا الباب لعدم الدليل، فينبغي أن نبقى على الأصل وهو أنها عبادة توقيفية فلا تفعل للأموات بخلاف الصدقة عنهم.. الحج.. العمرة.. قضاء الدين، هذه أمور تنفعهم وقد جاءت بها النصوص، فثبت عنه ﷺ أنه قال: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له، وقال الله سبحانه: وَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ [الحشر:10] يعني: بعد الصحابة يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ وَلا تَجْعَلْ فِي قُلُوبِنَاا غِلًّا لِلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَحِيمٌ [الحشر:10]، فدعا هؤلاء المتأخرون لمن سبقهم، هذا ينفعهم الدعاء، وهكذا الصدقة تنفعهم، وفي الإمكان بدل ما يقرأ أو يستأجر يصدق بالمال الذي يريد أن يستأجر به على الفقراء والمحاويج بنية عن هذا الميت وينتفع بهذا المال، ينتفع بالصدقة، وقد ثبت في الصحيح أن رجلاً قال: يا رسول الله! إن أمي افتلتت نفسها ولم توص، وأظنها لو تكلمت تصدقت، أفلها أجر إن تصدقت عنها؟ قال النبي صلى الله عليه وسلم: نعم.\nفبين صلى الله عليه وسلم أن الصدقة عن الميت تنفعه، هكذا الحج عنه والعمرة، وقد جاءت الأحاديث بذلك بداره، هكذا قضاء دينه ينفعه، أما كونه يتلو له القرآن يثوبه له يهديه له أو يصلي له أو يصوم له تطوعاً هذا لا أصل له، الصواب أنه غير مشروع. نعم.","link":"https://binbaz.org.sa/fatwas/7128/حكم-قراءة-القران-بنية-الاهداء-الى-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_146/14603.mp3","categories":["إهداء القرب للميت"]},{"id":8996,"question":"هنا رسالة وصلت إلى البرنامج من العراق باعثها أخونا صبري يوسف أحمد ، أخونا رسالته مطولة في الواقع يقول فيها: كان لي أخ قد وافاه الأجل وكان مستقيمًا في سلوكه، أي: لا يؤذي أحدًا ولا يكذب ولا يرتكب المحرمات، وكل الناس يثنون على أدبه وخلقه، وكان محبوبًا من قبل الجميع ولكنه لم يكن يصلي ولا يصوم، علمًا بأنه كان مطربًا أي يغني ولديه أغاني، ويستمر في سرد مثل هذا الوصف ويقول في نهاية رسالته: إنه يقرأ عليه سورة (يس) عملًا بقول الرسول ﷺ: يس قلب القرآن، فاقرءوها على موتاكم، ولكنني سمعت من برنامجكم الكريم بأن الشخص الميت لا يصل إليه ثواب قراءة القرآن، أرجو التوجيه جزاكم الله خيرًا؟","title":"حكم قراءة القرآن على من مات وهو تارك للصلاة","answer":"الجواب: الذي لا يصلي حالته سيئة جدًا، وقد اختلف العلماء في كفره، إذا كان يقر بأن الصلاة واجبة ويعرف أنها واجبة فرض ولكنه يتساهل فلا يصلي، فذهب جمع من أهل العلم إلى أنه عاصي ومعصيته كبيرة أعظم من الزنا وأعظم من السرقة ولكنه لا يكون كافرًا بل تحت مشيئة الله، إن شاء غفر الله له وإن شاء عذبه إذا كان موحدًا مسلمًا يعبد الله وحده، ويعلم أن الصلاة فريضة ولكنه يتساهل.\nوالقول الثاني: أنه يكفر كفرًا أكبر ولو أقر بوجوبها؛ لقول النبي ﷺ في الحديث الصحيح: العهد الذين بيننا وبينهم الصلاة فمن تركها فقد كفر، خرجه الإمام أحمد وأهل السنن بإسناد صحيح. فنوصيك أيها السائل! أن لا تدعو لأخيك هذا ولا تتصدق عنه؛ لأنه في ظاهر حاله ليس بمسلم، ولا تدعو عليه أيضًا ولا تسبه وأمره إلى الله.\nوأما قراءة القرآن هل يلحق بالميت وينفعه؟ فهذا أيضًا فيه خلاف بين أهل العلم، من أهل العلم من قال: إن القراءة تنفع الميت إذا قرأ عليه، يعني: إذا قرأ له ثوب له، قرأ بعض القرآن وجعل ثوابها له، وقال آخرون من أهل العلم: ليس عليه دليل ولا يلحق؛ لأن القرب والعبادات توقيفية فلا يصار إلى شيء منها إلا بدليل، ولم يرد عن النبي ﷺ ولا عن الصحابة ما يدل على القراءة للأموات.\nوحديث معقل بن يسار في سورة (يس) ضعيف، فلو صح لكان المراد به المحتضر، اقرءوا على موتاكم (يس)، يعني: المحتضر الذي قد دنا أجله حتى يستفيد وحتى يتذكر لعل الله يحسن له الخاتمة، فالمعنى: اقرءوا على المحتضر على من دنا أجله، من دنا موته سورة (يس) لكنه حديث ضعيف، وهكذا قوله ﷺ: لقنوا موتاكم لا إله إلا الله رواه مسلم في الصحيح، معناه: لقنوهم عند حضور الأجل حتى يختم لهم بها، وحتى تكون هذه الكلمة آخر كلامهم، وهي: لا إله إلا الله، لقوله ﷺ: من كان آخر كلامه لا إله إلا الله دخل الجنة.\nوهذا يدل على أن معنى الموتى المحتضر، لقنوا موتاكم يعني: المحتضرين، وبذلك يعلم أن القراءة للموتى ليس عليها دليل، والأظهر عدم وصولها إليهم ولكنهم ينتفعون بالصدقة عنهم، بالدعاء لهم، بالحج عنهم، بالعمرة عنهم، بقضاء الدين الذي عليهم، كل هذا ينتفعون به بإجماع المسلمين.\nأما الصلاة عنهم والقراءة لهم فهذا لا يصل إليهم على الصحيح. نعم.\nالمقدم: ينتفعون بتلكم الأعمال التي تفضلتم بذكرها إذا لم يكونوا تاركين للصلاة؟\nالشيخ: إذا كانوا مسلمين.\nالمقدم: إذا كانوا مسلمين، ومن ترك الصلاة؟\nالشيخ: ومن كان غير مسلم لا ينتفع. نسأل الله العافية.\nالمقدم: ومن ترك الصلاة حينئذ؟\nالشيخ: حكمه حكم الكفرة على الصحيح، نسأل الله العافية.\nالمقدم: نسأل الله السلامة.","link":"https://binbaz.org.sa/fatwas/7154/حكم-قراءة-القران-على-من-مات-وهو-تارك-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17607.mp3","categories":["إهداء القرب للميت"]},{"id":9213,"question":"أيضًا من المملكة الأردنية الهاشمية هذه رسالة وصلت إلينا من جرش وباعثتها إحدى الأخوات من هناك تقول: هادية محمد الجبالي، أختنا لها مجموعة من الأسئلة:سؤالها الأول يقول: هل يجوز الترحم والدعاء لتارك الصلاة أو المتهاون فيها وكذلك النصراني أعني: الكافر، وهل يصح الدعاء عليهم ولعنهم أو سبهم بعد الوفاة؟","title":"حكم الدعاء لتاركي الصلاة والكفرة والاستغفار لهم","answer":"الجواب: أما من مات من اليهود أو النصارى أو عباد الأوثان وهكذا من مات تاركًا للصلاة أو جاحدًا لوجوبها هؤلاء كلهم لا يدعى لهم ولا يترحم عليهم ولا يستغفر لهم؛ لقول الله : مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113]، وقد ثبت في الحديث الصحيح عن النبي عليه الصلاة والسلام: أنه استأذن ربه أن يستغفر لأمه فلم يأذن له سبحانه مع أنها ماتت في الجاهلية لم تدرك الإسلام لكنها ماتت على دين قومها على عبادة الأوثان، فاستأذن ربه فلم يأذن له أن يستغفر لها، فإذا كان امرأة ماتت في الجاهلية على دين الأوثان لم يؤذن له أن يستغفر لها وهي أمه، فكيف بغيرها عليه الصلاة والسلام؟ فالذي مات على الكفر لا يستغفر له ولا يدعى له، لا تارك الصلاة، ولا عابد القبور، ولا اليهودي، ولا النصراني، ولا الشيوعي، ولا القادياني، ولا أشباههم ممن يتعاطى ما يكفره ويخرجه من دائرة الإسلام.\nأما سبهم فلا يسبون بعد الموت يقول النبي ﷺ: لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا رواه البخاري في الصحيح عن عائشة رضي الله عنها: لا تسبوا الأموات فإنهم قد أفضوا إلى ما قدموا أفضوا إلى الله، الله يجازيهم بأعمالهم فلا حاجة إلى سبهم.\nلكن ذكر جماعة من أهل العلم أنه لا بأس بسب من اشتهر بالضلال والكفر والدعوة إلى الباطل من باب التحذير ولو بعد الموت، كما يقال: قاتل الله فرعون .. لعن الله فرعون .. لعن الله دعاة الضلالة، لعن الله أبا جهل وما أشبه ذلك من دعاة الضلالة من باب التنفير من أعمالهم القبيحة، هذا قاله جماعة من أهل العلم من باب التنفير إذا كان الإنسان مشهورًا بالضلالة والكفر والدعوة إلى الضلالة، أو ظلم الناس أجاز بعض أهل العلم سبه من باب التنفير ومن باب التحذير من مثل عمله، وإن ترك سبه عملًا بهذا الحديث: لا تسبوا الأموات فهذا من باب الاحتياط وهو أحسن وأولى. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7373/حكم-الدعاء-لتاركي-الصلاة-والكفرة-والاستغفار-لهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_182/18204.mp3","categories":["إهداء القرب للميت","حكم الصلاة وأهميتها"]},{"id":9230,"question":"هذه رسالة وصلت إلى البرنامج من المستمع مكاوي أحمد محمد من جمهورية مصر العربية، يقول في رسالته: هل يصح لي أن أقوم بأداء العمرة عن والدتي المتوفية، حيث أني قد أديت العمرة عن نفسي في رمضان هذا العام، وهل يصح لي أن أقوم بأداء العمرة عن والدتي بعد أداء فريضة الحج، أو قبل أدائي لفريضة الحج، أفيدونا أفادكم الله؟","title":"حكم أداء العمرة عن المتوفى","answer":"الجواب: نعم، لا بأس بذلك، بل أنت مأجور، ومشروع لك أن تحسن إلى والدتك بالعمرة قبل الحج أو بعده، وإذا كنت في مكة تحرم من الحل، يعني: خارج مكة، خارج الحرم، من مساجد عائشة التنعيم، أو من الجعرانة، أو غيرهما من الحل، كما أمر النبي ﷺ عائشة رضي الله عنها لما أرادت العمرة بعد الحج أن تحرم من الحل من التنعيم، هكذا السنة فيمن كان في مكة إذا أراد العمرة لنفسه أو لغيره؛ أن يخرج إلى الحل ثم يلبي بعمرة هناك، ثم يدخل فيطوف سبعة أشواط بالبيت ويصلي ركعتين خلف المقام، أو في أي بقعة من المسجد، ثم يسعى بين الصفا والمروة سبعة أشواط، ثم يقصر من رأسه، هكذا العمرة، وأنت مأجور في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7390/حكم-اداء-العمرة-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_233/23310.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":9310,"question":"جزاكم الله خيرا، يسأل أيضًا عن معنى حديث رسول الله ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له وسمعت من البرنامج أن ثواب قراءة القرآن لا يصل إلى الميت، وأن ما يفعله الناس من قراءة القرآن وغيره كل هذا بدع، فكيف يدعو الولد الصالح لأبيه؟ وما هو المقصود بهذا الدعاء؟","title":"ما معنى: «إذا مات ابن آدم انقطع عمله»؟","answer":"الجواب: الحديث على ظاهره، وهو حديث صحيح رواه مسلم في صحيحه: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له والدعاء يقول: اللهم اغفر لأبي، اللهم ارحمه، اللهم أسكنه الجنة، اللهم ضاعف حسناته، اللهم كفر سيئاته، اللهم ارفع درجته في المهديين، وما أشبه هذا من الدعوات الطيبة، هذا الدعاء.\nأما قراءة القرآن كونه يقرأ ويثوب هذا فيه خلاف بين أهل العلم:\nمن العلماء من قال: إنه يلحق الميت وأنه ينتفع بذلك، وبهذا قال جم غفير من العلماء، وقاسوه على الصدقة.\nوقال آخرون: لا. لأن العبادات توقيفية، لا يسمح فيها إلا بما جاء به الشرع نصًا، ولم يرد في السنة عن النبي ﷺ ولا في الكتاب العزيز ما يدل على شرعية تثويب القرآن، أو الصلاة، أو الصوم لمن ليس عليه صوم واجب، فلما لم يأت هذا وجب تركه؛ لأن المؤمن إنما يفعل ما أمر به وشرع له، والنبي ﷺ يقول: من عمل عملًا ليس عليه أمرنا فهو رد يعني: هو مردود، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد هذا وجه هذا القول الذي قاله جمع من أهل العلم وهو أظهر في الدليل وأقرب إلى الدليل، وفيما شرع الله الكفاية من الصدقة والدعاء والحج عن الميت، وأداء الصيام الواجب عنه إذا مات وعليه صيام من رمضان أو كفارة أو نذر، يؤدى عنه، يؤدي عنه أقاربه، أما صوم يتطوعون به عنه أو صلاة أو قراءة قرآن، فهذا لم يرد فيه دليل يدل عليه، فوجب ترك ذلك وقوفًا مع النصوص. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7474/ما-معنى-اذا-مات-ابن-ادم-انقطع-عمله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18409.mp3","categories":["إهداء القرب للميت","شروح الحديث"]},{"id":9741,"question":"له سؤال ثانٍ يقول فيه: يوجد لي ابن عم يذبح لأبيه وجده بعد مضي كل حول، ونصحته أكثر من مرة ويقول لي: إني سألت وقالوا: ليس في ذلك إثم، أفيدونا هل هذا الكلام صحيح أم حرام؟","title":"حكم الذبح للأقارب الأموات","answer":"الجواب: إذا ذبح قصده الضحية في أيام العيد عيد النحر يضحي عن أبيه وجده فلا بأس، أو ذبح قصده الصدقة عنهما يعطيها الفقراء في أي وقت فلا بأس الصدقة تنفع الميت باللحوم وغير اللحوم والنقود والطعام كل ذلك ينفع الميت، وقد ثبت عن رسول الله عليه الصلاة والسلام أنه سئل عن الرجل يتصدق لأمه بعد وفاتها أفله أجر؟ قال: نعم لها أجر وله أجر، الجميع، للمتصدق أجر وللمرأة أجر.\nفالمقصود أن الصدقة على الميت نافعة له بإجماع المسلمين وهكذا الدعاء له، فإذا أراد بهذه الذبيحة الصدقة بها عن أبيه أو جده أو ذبح أيام العيد ضحية عنه فكل هذا لا بأس به، أما إن أراد التقرب إليه بأن يذبح ليتقرب إليه كما يتقرب الذين يذبحون لأصحاب القبور أو للشمس أو للقمر أو للجن هذا شرك أكبر لا يتقرب إلى أحد بالذبيحة، يقول الله جل وعلا: قُلْ إِنَّ صَلاتِي وَنُسُكِي [الأنعام:162] يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ ۝ لا شَرِيكَ لَهُ [الأنعام:162-163]، ويقول سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ [الكوثر:1-2]، ويقول النبي ﷺ: لعن الله من ذبح لغير الله رواه مسلم في الصحيح، فالذبح للجن أو لأصحاب القبور يرجو شفاعتهم أو يرجو أنهم ينفعونه أو يشفون مريضه منكر وشرك أكبر، وهكذا من ذبح لجده أو أبيه يعتقد فيه أنه ينفعه وأنه يشفي مريضه أو أنه يقربه إلى الله بهذا الذبح يتقرب إليه به هذا من جنس من يذبح للشمس والقمر والنجوم والجن كله شرك، نسأل الله السلامة. نعم.\nالمقدم: مدار ذلك على النية.\nالشيخ: نعم، على النية .نعم.\nالمقدم: والأضحية سنة.\nالشيخ: نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/7907/حكم-الذبح-للاقارب-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_196/19603.mp3","categories":["إهداء القرب للميت"]},{"id":9845,"question":"تقول أيضاً: لنا قريب يقدم لنا بعض الحاجات المنزلية البسيطة، وهذه الحاجات مما اعتاد الناس أن يبيعوها، فقدمنا له نقوداً فلم يأخذها واعتبر أن هذه الحاجة هدية، وبعد مدة استعملنا هذه الحاجات تبين لنا أنه قد سرقها من شركة أجنبية يعمل حارساً عندها، فما حكم استعمالنا لهذه الحاجة بعد معرفتنا أنها مسروقة؟","title":"حكم استعمال الهدية إذا ثبت أنها مسروقة","answer":"الجواب: متى علمتم أن هذه الحاجات مسروقة، فالواجب عليك ردها إلى أصحابها؛ لأن هذا منكر وإنكار المنكر واجب، فإذا علمتم أنها مسروقة فردوها إلى أهلها، وأخبروه أن هذا لا يجوز له، وأن الواجب عليه أداء الأمانة مع الشركة ومع غير الشركة، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/8013/حكم-استعمال-الهدية-اذا-ثبت-انها-مسروقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_262/26205.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10028,"question":"يقول: كان لي أخت توفيت قبل أربع سنوات، لكنني كثيراً ما أراها في المنام وكنت أحبها في حياتها حباً كبيراً هل هناك توجيه جزاكم الله خيراً؟","title":"ما ينتفع به الميت من الحي","answer":"الجواب: نعم، نوصيك بالدعاء لها بالرحمة والمغفرة والدرجات العالية والصدقة عنها -جزاك الله خير- كل هذا طيب، وكونك تراها كثيراً هذا من ينشأ عن حبك لها من أجل حبك لها وكونها على بالك تراها في المنام، هذا لا حرج فيه إن شاء الله خير لك وخير لها تدعو لها وتستغفر لها وتتصدق عنها كل هذا طيب بارك الله فيك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8207/ما-ينتفع-به-الميت-من-الحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30110.mp3","categories":["إهداء القرب للميت"]},{"id":10033,"question":"يقول: قمت بإحضار بعض الناس لكي يعملوا في إحدى دول الخليج وأخذت منهم بعض النقود برضاهم، فهل يحق لي ذلك وإن كان غير ذلك فماذا أفعل؟","title":"حكم أخذ المال عن الشفاعة في المنافع","answer":"الجواب: إذا كنت اتفقت معهم على مال معلوم من بلادهم حتى توصلهم إلى الخليج وتقوم بما يجب من قيمة التذاكر وغير ذلك، هذا شيء لا حرج فيه، لأنك أديت عنهم مالاً حتى توصلهم إلى إحدى دول الخليج بسبب خدمتك لهم، وسعيك لهم في إيصالهم إلى دول الخليج حتى يعملوا هناك، أما إن كانت الأموال التي أخذتها من أجل الشفاعة لهم في أن يعملوا عند فلان أو عند فلان والنفقة على حسابهم لكن أعطوك المال لأجل الشفاعة اللي عند فلان أو فلان حتى يستخدمهم فلا ينبغي لك أن تأخذ المال، في الحديث: من شفع لأخيه شفاعة فأهدى له هدية فقد أتى باباً عظيماً من أبواب الربا فلا تأخذ عن شفاعتك مالاً، أما إذا كنت خدمتهم في شيء أعطوك المال عن خدمة أخذت لهم الجوازات تعبت لهم في الإقامة عملت أعمالاً كفيتهم إياها وأعطوك المال لخدمتك فقط، فلا حرج فلا نعلم حرجاً في ذلك في مقابل الخدمة التي خدمتهم إياها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8198/حكم-اخذ-المال-عن-الشفاعة-في-المنافع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_301/30102.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10209,"question":"تقول: لدي خال أحبه كثيراً، توفي رحمه الله وكان يكثر من شرب الخمر وغيرها، ولكنه كان طيب القلب ولا يحب الأذى لأحد أبدًا، وإذا وجد مالًا أعطى المحتاج، ودائماً يسعى لعمل الخير، ما رأيكم في هذا يا سماحة الشيخ، هل من عمل أقدمه له في حياتي حتى يخفف عنه جزاكم الله خيرًا وأحسن إليكم، وإذا كان ذلك كقراءة القرآن أو العمرة أو ما أشبه ذلك وجهوني جزاكم الله خيرا؟","title":"الأعمال التي تنفع الميت بعد وفاته","answer":"الجواب: إذا كان يصلي في حياته فالصدقة عنه تنفع، الصدقة عنه تنفع، والدعاء له بالمغفرة والرحمة في سجودك وفي آخر الصلاة وفي كل وقت، والصدقة عنه والحج عنه والعمرة عنه كل هذا ينفعه إذا كان يصلي، أما إذا كان لا يصلي فالذي لا يصلي كافر مع شرب الخمر نعوذ بالله، لكن إذا كان يصلي شرب الخمر معصية ليس بكفر ليس ردة عن الإسلام، لكنه معصية كبيرة من كبائر الذنوب وخطرها عظيم، في الحديث الصحيح يقول النبي ﷺ: إن على الله حقاً لمن شرب الخمر أن يسقيه من طينة الخبال، قيل: يا رسول الله! ما طينة الخبال؟ قال: عصارة أهل النار نسأل الله العافية، وقد قال ﷺ في صاحب الخمر..: لعن الخمر وشاربهاا وساقيها لعن عشرة في الخمر، لعن الخمر وشاربها وساقيها وعاصرها ومعتصرها وحاملها والمحمولة إليه وبائعها ومشتريها وآكلل ثمنها نعوذ بالله، وقال: لا يشرب الخمر حين يشربها وهو مؤمن وعيد عظيم.\nفالمقصود أن عمله قبيح شديد الخطورة وهو شرب الخمر، لكن لا يكفر بذلك لكنه قد أتى كبيرة عظيمة وصار فاسقًا بها، فإذا كان يصلي وليس هناك ما يوجب ردته فادعي له واستغفري له وتصدقي عنه لعل الله يخفف عنه. نعم.\nالمقدم: اللهم آمين جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8384/الاعمال-التي-تنفع-الميت-بعد-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_278/27807.mp3","categories":["إهداء القرب للميت"]},{"id":10482,"question":"من السودان المستمع عصام الدين إدريس، يسأل ويقول: إن والدي متوفى هل يجوز لي عند قراءتي في المصحف أن أقول: يا رب! ببركة وفضل السورة أن تهبها لوالدي ثم أتصدق وتكون نيتي له؟ هل يجوز مثل هذا العمل؟","title":"حكم التصدق بقراءة القرآن للوالد المتوفى","answer":"الجواب: لم يرد ما يدل على الصدقة بالقرآن، ولكن تدعو له عند القراءة وفي غيرها تدعو له: اللهم اغفر له، اللهم ارحمه، أما الصدقة عنه بالآيات وقراءة القرآن فليس عليها دليل، وإنما تدعو لأبيك، تقول: اللهم اغفر له، اللهم ارحمه، اللهم أجره من النار، اللهم ضاعف حسناته، اللهم اجزه عنا خيرًا، تصدق عنه بالمال، تحج عنه، تعتمر عنه، تقضي دينه، كل هذا طيب، كله ينفعه، أما أن تقرأ عنه القرآن أو تصلي عنه هذا لم يرد. نعم.\nالمقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8657/حكم-التصدق-بقراءة-القران-للوالد-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_281/28109.mp3","categories":["إهداء القرب للميت"]},{"id":10534,"question":"تقول في الفقرة الأخيرة سماحة الشيخ: هل يجوز لنا أن نأكل مما يهديه لنا هذا الرجل من أكل وخضروات وغيره أم لا؟","title":"حكم قبول الهدية ممن يجمع الصلوات ويترك الجماعة","answer":"الجواب: الهدية لها شأن آخر، إذا كان مكسبه طيب لا بأس، الهدية تقبل حتى من الكافر إذا لم يكن هناك موجب لردها، الهدية أمرها أوسع، لكن إذا أراد ردها هجرًا له وتعزيرًا له من باب التنبيه على خطئه فإذا رد هديته وهجره حتى يتوب يكون هذا أصلح من باب التأديب، ومن باب الحث على إقام الصلاة وأدائها، فإذا لم يقبل هديته ولم يزره وهجره فهذا مشروع إذا كان فيه مصلحة، أما إذا كان قبولها والمجيء إليه أقرب إلى الصلاح وإلى أن يستفيد فلا بأس.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8709/حكم-قبول-الهدية-ممن-يجمع-الصلوات-ويترك-الجماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_284/28406.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10602,"question":"المستمع عبيد بن حسين الإبراهيم سوري مقيم في عرعر بعث برسالة مطولة بعض الشيء يقول فيها: توفي ابن خالتي وقامت أمه بالتصدق لولدها، حيث أعطتني بقرة بصفة وقف لابنها أستفيد من لبنها على أن أطعم تلك البقرة وأعتني بها، وشاء الله أن البقرة ماتت حيث نطحت فذبحتها وبعت لحمها بمبلغ سبعة آلاف ليرة سوري، وصرفت تلك الفلوس حيث أنني محتاج لها، سؤالي: هل أشتري بقرة بدلاً منها وأعطيها للمتوفى كصدقة، أو أترك من بقرتي حيث أن لدي الآن بقرة أخرى أفيدوني جزاكم الله خيراً؟","title":"حكم من وضع عنده وقف فباعه مضطراً","answer":"الجواب: نعم، الواجب عليك أن تشتري بقرة مثلها حسب الطاقة، بالفلوس التي حصلت لك حين بعت البقرة بعد الذبح تصرفها في بقرة أخرى، تكون وقفاً وصدقة بدل التي ذبحت، وإذا كان عندك بقرة تناسب وعرضتها على اثنين من أهل المعرفة والخير ورأيا أنها مناسبة فلا بأس بالقيمة التي عندك، تكون وقفاً بدل البقرة التي ذبحت، وإذا اشتريت من غيرك بالسبعة الآلاف التي عندك بقرة أو زدت عليها من نفسك فهذا أحوط لك وأبعد عن التهمة، ويكون حكم البقرة الجديدة كالبقرة القديمة. نعم.","link":"https://binbaz.org.sa/fatwas/8788/حكم-من-وضع-عنده-وقف-فباعه-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32615.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10611,"question":"المستمع عبيد بن حسين الإبراهيم سوري مقيم في عرعر بعث برسالة مطولة بعض الشيء يقول فيها: توفي ابن خالتي وقامت أمه بالتصدق لولدها، حيث أعطتني بقرة بصفة وقف لابنها أستفيد من لبنها على أن أطعم تلك البقرة وأعتني بها، وشاء الله أن البقرة ماتت حيث نطحت فذبحتها وبعت لحمها بمبلغ سبعة آلاف ليرة سوري، وصرفت تلك الفلوس حيث أنني محتاج لها، سؤالي: هل أشتري بقرة بدلاً منها وأعطيها للمتوفى كصدقة، أو أترك من بقرتي حيث أن لدي الآن بقرة أخرى أفيدوني جزاكم الله خيراً؟","title":"حكم من وضع عنده وقف فباعه مضطراً","answer":"الجواب: نعم، الواجب عليك أن تشتري بقرة مثلها حسب الطاقة، بالفلوس التي حصلت لك حين بعت البقرة بعد الذبح تصرفها في بقرة أخرى، تكون وقفاً وصدقة بدل التي ذبحت، وإذا كان عندك بقرة تناسب وعرضتها على اثنين من أهل المعرفة والخير ورأيا أنها مناسبة فلا بأس بالقيمة التي عندك، تكون وقفاً بدل البقرة التي ذبحت، وإذا اشتريت من غيرك بالسبعة الآلاف التي عندك بقرة أو زدت عليها من نفسك فهذا أحوط لك وأبعد عن التهمة، ويكون حكم البقرة الجديدة كالبقرة القديمة. نعم.","link":"https://binbaz.org.sa/fatwas/8788/حكم-من-وضع-عنده-وقف-فباعه-مضطرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_326/32615.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":10676,"question":"إذا أراد الإنسان أن يحج أو يطوف أو يتصدق أو يذبح أضحية عن والديه، هل يقول: اللهم إن هذه عن والدي، بمعنى آخر: هل يظهر النية، أم تكون في القلب؟","title":"حكم الحج والطواف والتصدق والأضحية عن الوالدين","answer":"الجواب: الضحية الأفضل له يسمي، يقول: باسم الله والله أكبر عن والدي، أو اللهم تقبل مني عن والدي هذا أفضل، وإن اكتفى بالنية فلا بأس ولا حرج، النبي ﷺ لما ضحى قال: اللهم تقبل من محمد وآل محمد، أما أنه يطوف عنهم أو يصلي عنهم هذا غير مشروع، لا يطوف عن أحد ولا يصلي عن أحد، إنما يطوف عن نفسه ويصلي عن نفسه، ويدعو لوالديه في طوافه أو في صلاته، وهكذا لا يصوم عن أحد، إلا إذا كان عليه صيام فريضة فصام عنه وليه كأخيه أو أبيه أو نحو ذلك فلا بأس، كما قال عليه الصلاة والسلام: من مات وعليه صيام صام عنه وليه، أما أن يتطوع عنه بالصوم أو بالصلاة فهذا لا أصل له، وهكذا الطواف ليس عليه دليل، فالأفضل أن لا يطوف عن أحد. نعم إذا حج حجاً كاملاً عن أبيه أو أمه أو غيرهما من أمواته وأقاربه، الأموات أو العاجزين فلا بأس بذلك، وهكذا العمرة؛ لأنه ورد في الأدلة ما يدل على ذلك، أما كونه يصلي عن فلان، أو يطوف عن فلان، أو يصوم عن فلان تطوعاً فهذا لا دليل عليه. ولا ينبغي فعله، لكن الصدقة عن الأموات والأحياء طيبة نافعة، الصدقة طيبة نافعة، كونه يدعو لهم، يستغفر لهم، يحج عن الميت، عن العاجز، يعتمر كل هذا طيب، يؤدي الدين عن المدين، كل هذا نافع. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8868/حكم-الحج-والطواف-والتصدق-والاضحية-عن-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33018.mp3","categories":["إهداء القرب للميت","الهدي والأضاحي"]},{"id":10771,"question":"يقول أيضاً: الذين يقرءون القرآن للميت يعتبرونه صدقة له، هل ثواب قراءة القرآن يصل للميت أم لا؟","title":"الصواب في وصول ثواب القراءة إلى الميت","answer":"الجواب: هذه المسألة فيها خلاف بين أهل العلم:\nمن أهل العلم من يقول: إن قراءة القرآن تصل إلى الميت، إذا قرأ وثوبها للميت تصل إليه، كما يصل إليه الصدقة والدعاء والحج عنه والعمرة وأداء الدين ينتفع بهذا كله، فقالوا: إن هذا مثل هذا، إن قراءة القرآن أو كونه يصلي له، أنه يلحقه كما تلحقه الصدقة وتنفعه الصدقة والحج عنه والعمرة والدعاء.\nوقال آخرون: لا؛ لعدم الدليل؛ لأن العبادات توقيفية لا يفعل منها شيء إلا بالدليل، لا مجال للرأي فيها، فالعبادات توقيفية بمعنى أنها تتلقى عن الله وعن الرسول ﷺ لا بالرأي والهوى والقياسات لا، العبادات توقيفية قال الله قال رسوله، ما شرعه الله في كتابه أو رسوله ﷺ في السنة فهذا هو الذي يؤخذ به ويعمل به، وما لا فلا، وهذا هو الصواب أن القراءة لا تهدى هذا هو الصواب، لا يشرع أن تهدى وهكذا الصلاة لا يصلي أحد عن أحد؛ لعدم الدليل، لأنه ما كان النبي ﷺ يفعل هذا عن أقاربه، وما فعله الصحابة  وأرضاهم عن أقاربهم.\nفالمشروع لنا أن نتبع طريقهم وسبيلهم فلا نقرأ عن الميت ولا لغير الميت، يعني: نثوب القراءة له ولا نصلي له ولا نصوم له؛ لأنه لم يرد إلا إذا كان عليه دين صوم رمضان ولم يقضه يصام عنه، كما قال ﷺ: من مات وعليه صيام صام عنه وليه، لكن لا يقاس عليه الصلاة ولا تقاس عليه القراءة، العبادات ما هي بمحل قياس، القياس في أمور أخرى غير العبادات.\nفالمؤمن حق عليه أن يلتزم بما شرعه الله ويؤدي العبادة كما شرعه الله، ولا يحدث شيئاً لم يشرعه الله؛ لقول النبي ﷺ: من عمل عملاً ليس عليه أمرنا فهو رد رواه مسلم في الصحيح؛ ولقوله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد متفق على صحته، وقوله ﷺ في خطبة الجمعة: إن خير الحديث كتاب الله، وخير الهدي هدي محمد ﷺ، وشر الأمور محدثاتها، وكل بدعة ضلالة رواه مسلم أيضاً.\nفالمؤمن يتبع ولا يبتدع فيقرأ لنفسه ويصلي لنفسه يرجو ثواب الله، أما أنه يهدي صلاته أو قراءته إلى حي أو ميت فهذا ليس بمشروع على الصواب فينبغي تركه، وإن قال آخرون من أهل العلم: إنه يفعل، فالاعتبار بالأدلة الشرعية لا بأقوال الناس، يقول الله : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]، ويقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] فهذه المسألة إذا رددناها إلى الله وإلى رسوله لم نجد في الكتاب العزيز ولا في السنة المطهرة ما يدل على أننا نصلي عن فلان أو نقرأ عن فلان، ونهدي له ثواب قراءتنا وصلاتنا، ولا صومنا، لكن جاء في السنة تصدق الصدقة عن الميت نافعة، والدعاء له بالمغفرة والرحمة نافع بإجماع المسلمين، هكذا الحج عنه والعمرة عنه، إذا كان ميتاً أو عايشاً لا يستطيع الحج لهرمه أو لمرض لا يرجى برؤه لا بأس أن يحج عنه ويعتمر، وهكذا إذا كان عليه دين قضاه أخوه المسلم ينفعه، أما أن يصام عنه تطوع أو يصلى عنه أو يقرأ عنه هذا ليس عليه دليل، فلا ينبغي أن يفعل ولا يشرع، عملاً بالأدلة الشرعية ووقوفاً عندها، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8944/الصواب-في-وصول-ثواب-القراءة-الى-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34804.mp3","categories":["إهداء القرب للميت"]},{"id":10891,"question":"من البحرين السائلة (ح. ع) تقول: هل صحيح يا سماحة الشيخ أن الزوجة لا يصح لها أن تتصدق عن زوجها بعد وفاته، ولا تترحم عليه، ولا تدعو له؟ وإذا صح ذلك فما هي الأسباب؟ نرجو منكم الإفادة الشرعية؟","title":"ما صحة أن المرأة لا يصح أن تتصدق عن زوجها؟","answer":"الجواب:  هذا ليس بصحيح! هذا غلط! الذي يقول هذا غلط، يعني جهل ومنكر، بل يشرع لها تتصدق عنه، والدعاء له والاستغفار له، والحج عنه، والعمرة كله طيب، الله جعل بينهما عشرة.. عشرة واجتماع لا ينبغي أن ينسى فضله، الله يقول: وَلا تَنسَوُا الْفَضْلَ بَيْنَكُمْ [البقرة:237] لا تنس الزوجة زوجها، ولا ينساها هو إن ماتت قبله، كل منهما يشرع له الإحسان إلى الميت قبله بالصدقة والدعاء والاستغفار والحج عنه، وقضاء دينه، وغير هذا من وجوه الخير، والذي يقول: لا يفعل، هذا قول باطل ومنكر، لا يقوله عاقل. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9068/ما-صحة-ان-المراة-لا-يصح-ان-تتصدق-عن-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28605.mp3","categories":["إهداء القرب للميت"]},{"id":10920,"question":"هل قراءة القرآن، وجعل ثوابه للميت بدعة، ولم تقره المذاهب الأربعة؟ فما هو الشيء إذًا الذي ينفع الميت؟","title":"حكم قراءة القرآن وتثويبه للميت","answer":"الجواب:  قراءة القرآن وتثويبها للموتى فيها خلاف بين العلماء، منهم من أجازها واستحبها، وقال: إنها تصل للأموات، وتنفعهم وهذا هو المعروف من مذهب أحمد وجماعة، بل حكاه بعض أهل العلم قول جمهور العلماء، ورواه ابن القيم -رحمه الله- في كتاب الروح، وأطال في ذلك، وقال آخرون من أهل العلم: إن تثويب القراءة للموتى لا تلحق ولا تشرع، إن تثويب القراءة للميت لا يشرع، ولا يلحق الميت، وهو المروي عن الشافعي -رحمه الله- وجماعة من السلف، وهذا أصح لعدم الدليل؛ لأن العبادات توقيفية، والتثويب للموتى نوع من العبادة، فلا ينبغي أن يفعل إلا بالدليل، ولا نعلم دليلًا واضحًا في شرعية أن يصلي الإنسان عن غيره، أو يقرأ عن غيره. فالأرجح والأولى عدم التثويب للموتى وغيرهم، ولكن يدعو لهم، ويستغفر لهم، ويترحم عليهم، ويتصدق عنهم لا بأس، ولكن لا نقول: بدعة، ولا نقول: محرمًا، نقول: هذا هو الأولى والأحوط؛ لأن القول الثاني له حظه من القوة، والذين قالوا بجوازه قاسوه على الدعاء، قاسوه على الصدقة، قالوا: كما يجوز أن ندعو له، ونتصدق عنه، فلا مانع من أن نقرأ ونثوب له القراءة، أو نصلي ونثوب له الصلاة، أو نطوف ونثوب له الطواف. فالقول له حظ من القوة في قياس العبادات بعضها على بعض، ولكن القاعدة الشرعية: أن العبادات لا قياس فيها، وأنها توقيفية، فلهذا قلنا: إن القول بعدم التثويب أولى وأرجح وأحوط للمؤمن، ولكن لا نقول: إنه بدعة، ولا نقول: إنه محرم، بل مسألة خلاف بين أهل العلم مشهورة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9093/حكم-قراءة-القران-وتثويبه-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36103.mp3","categories":["إهداء القرب للميت"]},{"id":10924,"question":"هل قراءة القرآن، وجعل ثوابه للميت بدعة، ولم تقره المذاهب الأربعة؟ فما هو الشيء إذًا الذي ينفع الميت؟","title":"حكم قراءة القرآن وتثويبه للميت","answer":"الجواب:  قراءة القرآن وتثويبها للموتى فيها خلاف بين العلماء، منهم من أجازها واستحبها، وقال: إنها تصل للأموات، وتنفعهم وهذا هو المعروف من مذهب أحمد وجماعة، بل حكاه بعض أهل العلم قول جمهور العلماء، ورواه ابن القيم -رحمه الله- في كتاب الروح، وأطال في ذلك، وقال آخرون من أهل العلم: إن تثويب القراءة للموتى لا تلحق ولا تشرع، إن تثويب القراءة للميت لا يشرع، ولا يلحق الميت، وهو المروي عن الشافعي -رحمه الله- وجماعة من السلف، وهذا أصح لعدم الدليل؛ لأن العبادات توقيفية، والتثويب للموتى نوع من العبادة، فلا ينبغي أن يفعل إلا بالدليل، ولا نعلم دليلًا واضحًا في شرعية أن يصلي الإنسان عن غيره، أو يقرأ عن غيره. فالأرجح والأولى عدم التثويب للموتى وغيرهم، ولكن يدعو لهم، ويستغفر لهم، ويترحم عليهم، ويتصدق عنهم لا بأس، ولكن لا نقول: بدعة، ولا نقول: محرمًا، نقول: هذا هو الأولى والأحوط؛ لأن القول الثاني له حظه من القوة، والذين قالوا بجوازه قاسوه على الدعاء، قاسوه على الصدقة، قالوا: كما يجوز أن ندعو له، ونتصدق عنه، فلا مانع من أن نقرأ ونثوب له القراءة، أو نصلي ونثوب له الصلاة، أو نطوف ونثوب له الطواف. فالقول له حظ من القوة في قياس العبادات بعضها على بعض، ولكن القاعدة الشرعية: أن العبادات لا قياس فيها، وأنها توقيفية، فلهذا قلنا: إن القول بعدم التثويب أولى وأرجح وأحوط للمؤمن، ولكن لا نقول: إنه بدعة، ولا نقول: إنه محرم، بل مسألة خلاف بين أهل العلم مشهورة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9093/حكم-قراءة-القران-وتثويبه-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_361/36103.mp3","categories":["إهداء القرب للميت"]},{"id":11031,"question":"يقول هذا السائل: ما حكم من تصدق بشيء وقال: اللهم اجعل أجر ذلك لوالدي ووالدتي، أو لزوجتي المتوفاة، أو غير ذلك، فهل يكون له أجر الصدقة كاملًا؟","title":"حكم الصدقة عن الوالدين بعد موتهما","answer":"الجواب:  نعم لا بأس في ذلك، يتصدق على الميت، أبيه أو أمه أو زوجته، كل هذا طيب ينفعها، ينفع الميت، سئل النبي ﷺ عن هذا فقال: نعم، قال رجل: يا رسول الله! إن أمي ماتت ولم توص، أفلها أجر إن تصدقت عنها؟ قال النبي: نعم -عليه الصلاة والسلام- وقال -عليه الصلاة والسلام-: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. وهكذا لما سئل عن الحج عن الميت، فأجاب: بأنه لا بأس، سألت امرأة هل تحج عن أبيها الشيخ الكبير العاجز، قال: نعم حجي عن أبيك وسأله أبو رزين العقيلي ليحج عن أبيه لأنه كان عاجزًا، قال: حج عن أبيك واعتمر وهكذا الحج عن الميت، نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/9209/حكم-الصدقة-عن-الوالدين-بعد-موتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_287/28713.mp3","categories":["إهداء القرب للميت"]},{"id":11060,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، يسأل فيها جمعًا من الأسئلة من بينها سؤال عن حكم قراءة القرآن عن الميت في أي يوم من الأيام، كيوم الجمعة مثلًا أقرأ سورة البقرة، وأقول: هذه إلى روح فلان، فهل يصح ذلك؟","title":"حكم قراءة القرآن وتثويبها للميت","answer":"الجواب:  ليس عليه دليل، القراءة على الموتى، ليس عليه دليل، قد قاله بعض أهل العلم، ولكن ليس عليه دليل، تركه أولى، تدعو للميت بالدعوات الطيبة، تتصدق عنه بالمال، تحج عنه، تعتمر عنه، كل هذا طيب، أما القراءة عنه فليس عليها دليل، وتركها أولى، تقرأ لنفسك، تدعو لأخيك الميت، أو لأبيك أو غيره: اللهم اغفر له، اللهم ارحمه، اللهم ضاعف حسناته، اللهم أنجه من النار، إلى غير ذلك، تدعو له، تتصدق عنه بالمال، تحج عنه، تعتمر، لا بأس، كله طيب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9238/حكم-قراءة-القران-وتثويبها-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36711.mp3","categories":["إهداء القرب للميت"]},{"id":11181,"question":"ما هو الدعاء الأحسن للمتوفى وفي أي وقت يكون أفضل؟","title":"أنفع الدعاء للميت","answer":"الجواب:  الدعاء مطلوب للمتوفى وينفعه، وإذا كان في أوقات الإجابة كان أنفع وأنفع مثل: آخر الليل، مثل: آخر نهار الجمعة بعد الصلاة، صلاة العصر، مثل: عند جلوس الإمام على المنبر إلى أن تقضى الصلاة يوم الجمعة، في جوف الليل، في السجود، كل هذه أقرب ما يكون إلى الإجابة. نعم.","link":"https://binbaz.org.sa/fatwas/9381/انفع-الدعاء-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37225.mp3","categories":["الأدعية والأذكار","إهداء القرب للميت"]},{"id":11184,"question":"هل قراءة القرآن للمتوفى تفيده في قبره؟","title":"حكم قراءة القرآن للموتى وانتفاعهم بذلك","answer":"الجواب:  لا دليل على هذا، قراءة القرآن لا تقرأ للأموات، ولكن يدعى لهم بالمغفرة والرحمة، يتصدق عنهم، هذا هو المشروع، أما قراءة القرآن وتثويبها للأموات، هذا لا دليل عليه، وإن كان قاله بعض العلماء لكن قول لا دليل عليه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9377/حكم-قراءة-القران-للموتى-وانتفاعهم-بذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_372/37221.mp3","categories":["إهداء القرب للميت"]},{"id":11215,"question":"لها جمع من القضايا كما قلت سابقًا سماحة الشيخ، من بينها أنها تسأل عن صحة عدد من الأمور، من بينها ما يلي: الفاتحة على روح الميت كما يفعله كثير من الناس؟","title":"حكم إهداء الفاتحة إلى روح الميت","answer":"الجواب:  ليس لهذا أصل، القراءة للميت بالفاتحة ..... ليس لهذا أصل، هذا هو الصواب، إنما يدعى للميت بالمغفرة والرحمة، ودخول الجنة والنجاة من النار، يتصدق عنه بالمال، يحج عنه، يعتمر عنه، هذا هو الوارد، أما أن يقرأ عنه القرآن ويثوب له، هذا ليس له أصل، هذا هو الصواب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9417/حكم-اهداء-الفاتحة-الى-روح-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37315.mp3","categories":["إهداء القرب للميت"]},{"id":11279,"question":"في أحد أسئلته يقول: شخص له ثلاث زوجات، كل واحدة منهن لها أولاد ذكور وإناث وتختلف عن الزوجة الأخرى من جهة عدد الذكور والإناث، ويرغب الزوج قسمة العقارات عليهن بحيث يعطي كل واحدة منهن مسكنََا لها ولأولادها الذكور والإناث، علمًا بأن المساكن تختلف بعضها عن بعض من جهة القيمة والمساحة، فهل هذه القسمة مطابقة للشرع أم كيف توجهونه؟ جزاكم الله خيرًا.","title":"حكم من قسم بين أولاده المساكن مع اختلاف قيمتها","answer":"الجواب:  إن كانت القسمة للسكن فقط والعقار باقي على ملكه بحيث يقدر عليه بعد موته ويرثونه، هذا لا حرج يجتهد في التوزيع بينهم وفي إسكانهم والإنفاق عليهم، والعقار على ملكه يبقى على ملكه، وإذا مات حكمه حكم بقية العقار وإرث بين الجميع فلا بأس. أما إذا كان المقصود تمليكه فلابد من المساواة والعدل، يعطي الزوجات على السواء ويعطي الأولاد على السواء للذكر مثل حظ الأنثيين، يعطي الذكر مثل الأنثى مرتين، وكل زوجة يساويها بالأخرى حتى يعدل بينهن لأن الرسول ﷺ يقول: اتقوا الله واعدلوا بين أولادكم ويقول ﷺ: من كانت له زوجتان فمال إلى إحداهما جاء يوم القيامة وشقه مائل. فالحاصل: أن عليه العدل حسب الطاقة في زوجاته وفي أولاده إذا كان عطاء تمليك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9466/حكم-من-قسم-بين-اولاده-المساكن-مع-اختلاف-قيمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_375/37517.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11481,"question":"يسأل أخونا هذا  هل الرجل الكافر الذي يموت بدون صلاة وصوم، هل تصل إليه الصدقة إذا أراد أولاده أو أقاربه التصدق عليه بعد الموت؟","title":"حكم الصدقة عمن مات وهو لا يصلي ولا يصوم","answer":"الجواب:  من مات كافرًا لا ينفعه شيء، لا تنفعه صدقاتهم، ولا دعاؤهم، إذا مات كافرًا؛ فلا يتصدق عنه، ولا يدعى له، ولا تلحقه تلك الصدقات، ولا تنفعه؛ لأنه مات على كفر يحبط الأعمال، ويمنع وصول الخير إليه وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88]، وفي الحديث الصحيح: إن الكافر إذا عمل حسنة أطعم بها طعمة في الدنيا نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9656/حكم-الصدقة-عمن-مات-وهو-لا-يصلي-ولا-يصوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38202.mp3","categories":["إهداء القرب للميت"]},{"id":11584,"question":"تسأل سماحتكم -جزاكم الله خيرًا- عن صديقة لها متوفىً زوجها تقول: إنها أحيانًا تأخذ منها بعض المال، ولكن تفكر في بعض الأوقات وتقول: أرجو أن لا أكون قد أخذت هذا المال بغير حقه؛ لأنه من مال أيتام، فبماذا توجهونها وذلكم الحال؟ جزاكم الله خيرًا.","title":"حكم أخذ المال من امرأة متوفى عنها زوجها","answer":"الجواب:  إذا كنت لا تعلمين؛ فلا حرج عليك، وعليك حسن الظن، والحذر من الوساوس، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9767/حكم-اخذ-المال-من-امراة-متوفى-عنها-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38613.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11597,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ن. م) تقول: يوجد عندي خماخم ذهب قد اشتريتها هدية لشغالة كانت عندي سابقًا، وعند سفرها نسيتها عندي، هل تنصحونني بإعطائها لخدامة أخرى، أم أتصرف فيها تصرفًا آخر؛ لأني أخشى إذا بعثتها إليها ألا تصل؟","title":"حكم من أهدى هدية ونسيها المهدى إليه عنده","answer":"الجواب:  الواجب بعثها إليها، إذا كنت أعطيته إياها، وتملكتها منك، ولكن نسيتها فهي ... كسائر مالها، الواجب عليك إيصالها إليها بالطريقة الممكنة، وليس لك التصرف فيها بإعطائها خدامة أخرى ولا غيرها، الواجب إيصالها إلى الخدامة التي أعطيتها إياها، ولا ترجعي في هبتك؛ يقول النبي ﷺ: الراجع في هبته كالراجع في قيئه. فالواجب إيصالها إليها بالطريقة الممكنة، أما إذا عجزت عن إيصالها إليها؛ فإنك تتصدقي بها عنها، إذا لم يتيسر إيصالها إليها؛ فإنه يتصدق بها عنها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9788/حكم-من-اهدى-هدية-ونسيها-المهدى-اليه-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38714.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11599,"question":"بعد هذا رسالة بعثت بها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (ن. م) تقول: يوجد عندي خماخم ذهب قد اشتريتها هدية لشغالة كانت عندي سابقًا، وعند سفرها نسيتها عندي، هل تنصحونني بإعطائها لخدامة أخرى، أم أتصرف فيها تصرفًا آخر؛ لأني أخشى إذا بعثتها إليها ألا تصل؟","title":"حكم من أهدى هدية ونسيها المهدى إليه عنده","answer":"الجواب:  الواجب بعثها إليها، إذا كنت أعطيته إياها، وتملكتها منك، ولكن نسيتها فهي ... كسائر مالها، الواجب عليك إيصالها إليها بالطريقة الممكنة، وليس لك التصرف فيها بإعطائها خدامة أخرى ولا غيرها، الواجب إيصالها إلى الخدامة التي أعطيتها إياها، ولا ترجعي في هبتك؛ يقول النبي ﷺ: الراجع في هبته كالراجع في قيئه. فالواجب إيصالها إليها بالطريقة الممكنة، أما إذا عجزت عن إيصالها إليها؛ فإنك تتصدقي بها عنها، إذا لم يتيسر إيصالها إليها؛ فإنه يتصدق بها عنها. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9788/حكم-من-اهدى-هدية-ونسيها-المهدى-اليه-عنده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_387/38714.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11640,"question":"امرأة توفيت سماحة الشيخ، وتركت قطعة أرض لمن يقرأ لها القرآن بعد وفاتها، فكيف التصرف في تلكم الأرض؟ ولا سيما وقد سمعنا أن قراءة القرآن، وإهداء ثوابها إلى الموتى غير جائزة، وهذا السؤال من المستمع: عيسى محمد سالم.","title":"حكم الوقف لقراءة القرآن على الواقف بعد موته","answer":"الجواب:  نعم غير مشروع قراءة القرآن للأموات، ولكن هذه الأرض تصرف غلتها في جماعة معلمي القرآن، تصرف غلتها للذين يعلمون القرآن، ولها أجرها العظيم، تعينهم.. في جماعة القرآن في البلد، أو في أي بلد، تصرف الغلة للقائمين بتعليم القرآن، حتى يستعينوا بها في أجور المدرسين، أو شراء الكتب، ونحو ذلك، أما أن يقرأ القرآن للميتة، لا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9831/حكم-الوقف-لقراءة-القران-على-الواقف-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_389/38918.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":11743,"question":"من حائل المستمع محمد حسين السيد الغويط بعث يسأل عن حكم العمرة عن الوالدة المتوفاة، هل تجوز، أو لا؟ وهل لذلك من شروط؟ جزاكم الله خيرًا.","title":"حكم عمرة الرجل عن والدته المتوفاة","answer":"الجواب:  العمرة عن الوالدة وعن الوالد قربة إذا كانا متوفيين قربة وطاعة، وهكذا الحج عنهما، فإذا كانا ما حجا، ولا اعتمرا؛ وجب أن يحج عنهما من مالهما إذا كان لهما مال، فإن كان ما لهما مال؛ شرع لأولادهما الحج عنهما، والعمرة عنهما، وهذا من البر والصلة كونه يعتمر عن والده الميت، أو والدته، أما الحي فلا، إلا إذا كان عاجزًا، إنسان كبير، أو عجوز كبيرة؛ فلا مانع من الحج عنهما، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9925/حكم-عمرة-الرجل-عن-والدته-المتوفاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42116.mp3","categories":["إهداء القرب للميت"]},{"id":11802,"question":"زوج أختي متوفى من عامين -رحمه الله- نويت أن أعتمر له -إن شاء الله- مع العلم أنني -والحمد لله- قد أديت فريضة الحج، فهل يجوز أن أذهب إلى مكة المكرمة، وأعتمر لي وله؟ أفيدوني عن هذا، جزاكم الله خيرًا.","title":"حكم العمرة عن القريب المتوفى","answer":"الجواب:  إذا كنت قد اعتمرت لنفسك؛ فلك أن تعتمر عنه -جزاك الله خيرًا- من الميقات الذي تمر عليه، تحرم من الميقات، أما إن كنت لم تعتمر لنفسك؛ فإنك تبدأ بنفسك، تعتمر عن نفسك، ثم تعتمر له إذا شئت، وأنت على أجر عظيم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9986/حكم-العمرة-عن-القريب-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42304.mp3","categories":["إهداء القرب للميت"]},{"id":12079,"question":"هل قراءة القرآن الكريم، وإهداء ثوابها للميت جائزة، أو لا؟","title":"حكم تثويب قراءة القرآن للأموات","answer":"الجواب:  ليس عليه دليل، ولا أعلم في هذا ما يدل على إهداء القرآن للموتى، ولا غير الموتى، ولكن يقرأ لنفسه، ويدعو الله للموتى بالمغفرة والرحمة، أما الإهداء يكون بالمال، الصدقة بالمال، بالحج بالعمرة، هذا هو محل الإهداء، يتصدق عليه بالمال، يصوم عنه إذا كان عليه صوم، مات وعليه صوم، وصام عنه، هذا لا بأس به، أما أن يقرأ القرآن، ويهدي له القرآن؛ فليس عليه دليل فيما أعلم، فينبغي ترك ذلك، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10264/حكم-تثويب-قراءة-القران-للاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43512.mp3","categories":["إهداء القرب للميت"]},{"id":12123,"question":"من الأخوين عبدالجليل عباس، ومحمد علي رسالة وضمناها جمعًا من الأسئلة، في أحدها يقولون: ما هو العمل الذي ينفع الميت؟ جزاكم الله خيرًا.","title":"ما ينفع الميت من أعمال","answer":"الجواب:  الأعمال التي تنفع الميت كثيرة، منها الدعاء للميت بالمغفرة والرحمة، والنجاة من النار، ومضاعفة الحسنات، فالدعاء للأموات المسلمين من أهم القربات والطاعات، قد شرع الله -جل وعلا- صلاة الجنازة لما فيها من الدعاء للميت، والترحم عليه، ومنها الصدقة عن الميت، كون قريبه، أو أخيه في الله يتصدق عنه، ينفع الميت بالنقود، أو بالطعام، أو بالملابس، أو بغير ذلك من أنواع المال، فالصدقة تنفع الميت بإجماع المسلمين وبالنص عن رسول الله -عليه الصلاة والسلام- هكذا الحج عنه، والعمرة عنه، وقضاء دينه كل هذا ينفعه، يقول النبي ﷺ: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. فالوصية لجميع إخواني المسلمين الدعاء لإخواننا المسلمين، والدعاء لأقاربهم، ووالديهم المسلمين، الدعاء لهم، الترحم عليهم، والصدقة عنهم، كل هذا ينفعهم كثيرًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10308/ما-ينفع-الميت-من-اعمال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43808.mp3","categories":["إهداء القرب للميت"]},{"id":12172,"question":"ما حكم قراءة القرآن، ولاسيما الفاتحة ويس على أرواح الموتى، وما حكم ما يفعله بعض الناس من إحضار القراء ليقرؤوا القرآن على أرواح الموتى بمبالغ باهضة، وما صحة الحديث: اقرءوا يس على موتاكم؟","title":"حكم استئجار القراء وتثويب القراءة لميت","answer":"الجواب:  هذا العمل لا يجوز، كونه يستأجر من يقرأ القرآن للموتى هذا لا يجوز، والذي يقرأ بالأجرة ما له ثواب حتى يهديه للموتى، ما قرأ لله، ما قرأ إلا للأجرة، فليس له ثواب حتى يهدى. ثم السنة عدم إهداء القراءة للموتى، لا منك، ولا من غيرك؛ لعدم الدليل على ذلك؛ لأنه لم يحفظ عن النبي ﷺ ولا عن الصحابة أنهم كانوا يفعلون ذلك. لكن بعض أهل العلم رأى جواز ذلك من غير أن يستأجر بأجرة، بل من باب التبرع، إذا تبرع وقرأ وثوب لميته، أو لإنسان حي، ذكر بعض أهل العلم أنه جائز، ولا حرج في ذلك، وقاسوه على الصدقة والدعاء، ولكن ظاهر الأدلة الشرعية أن ذلك لا ينبغي، وأنه يخشى أن يكون بدعة لعدم الدليل عليه، فالأولى بالمؤمن، والأحوط له ألا يفعل ذلك، بل يحسن إلى موتاه بالدعاء، بالصدقة عنهم، بالحج عنهم بالعمرة هذا لا بأس، كله مشروع. أما كونه يقرأ ويثوب لهم، أو يسبح ويثوب لهم هذا لا دليل عليه، فالأولى بالمؤمن ترك ذلك، لقوله ﷺ: من عمل عملًا ليس عليه أمرنا؛ فهو رد أما كونه يستأجر من يقرأ هذا لا، لا يجوز؛ لأن كونه يقرأ بالأجرة؛ هذا ليس له ثواب، فكيف يهدى؟ ما معه شيء يهدى.  وقد أجمع العلماء على تحريم أخذ الأجرة على تلاوة القرآن، ذكر ذلك أبو العباس ابن تيمية -رحمه الله- وقال: إنه لا نزاع بين أهل العلم في تحريم أخذ الأجرة على تلاوة القرآن. فالواجب الحذر من هذا العمل، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10358/حكم-استىجار-القراء-وتثويب-القراءة-لميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44210.mp3","categories":["إهداء القرب للميت"]},{"id":12347,"question":"يقول: اعتدت بعد أن أصلي النوافل أن أصلي ركعتين وأقول: بأن ثوابهما لوالدي المتوفين، فهل يصح هذا، أم لا؟","title":"حكم تثويب الصلاة للوالدين","answer":"الجواب:  ما له أصل، ليس لهذا أصل، لا، لا تفعل هذا، ولم يكن النبي ﷺ ولا الصحابة يفعلون ذلك، لكن تدعو، تدعو لوالديك، ولقراباتك المسلمين، تستغفر لهم، تتصدق عنهم، لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10541/حكم-تثويب-الصلاة-للوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_454/45411.mp3","categories":["إهداء القرب للميت"]},{"id":12412,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجزائر، باعثها أحد الإخوة المستمعين من هناك، ويسأل سؤالين: هل الشخص إذا كان في الصلاة قبل التسليم، ونوى الصلاة لرجل في وسط الصلاة، ثم أحس بعد ذلك أن النية لغير وجه الله، وشك هل قبل الصلاة نوى، أم بعدها، وهل يكون رياء؟ وجهونا جزاكم الله خيرًا.","title":"حكم تثويب الصلاة للغير أو التقرب إليه بها","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فإن الصلاة لا تثوب للغير، لا للميت، ولا غيره، لعدم ورود الأدلة على ذلك، الأدلة الشرعية، وإنما يصلي الإنسان لنفسه يرجو ثواب الله، فإذا صلى ركعتين، أو أكثر، ثم شك بعد الصلاة هل نواها عن فلان، أو فلان؛ فصلاته صحيحة؛ لأن الأصل عدم وجود هذه النية، والشك بعد الصلاة لا يؤثر في الصلاة. إلا إذا علم أن النية وقعت في الصلاة، وأنه نواها عن الغير؛ فإن هذه الصلاة لا تصح عن الغير؛ لعدم الدليل على ذلك، وعليه أن يتوب إلى الله من ذلك، وألا يعود إلى الصلاة عن الغير، وإنما الدعاء يدعو للغير، يتصدق عنه، يحج عنه، إذا كان ميتًا يعتمر، إذا كان ميتًا، أو بخير عاجز عن الحج والعمرة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، كأني به سماحة الشيخ يقول: الصلاة لفلان، وليست عن فلان؟ الشيخ: هو هذا مراده لفلان يعني: يبين هدي ثوابها له، أما إذا كان يعبده بها، يتقرب إليه، يصلي له، يعبده، ويسجد له؛ هذا شرك أكبر، هذا شرك أكبر كونه يصلي، يسجد لفلان، أو يركع لفلان، أو يسجد لفلان، أو يصوم لفلان، يتقرب إليه، يعبده من دون الله؛ فهذا شرك أكبر، نعوذ بالله، مثل الذبح لغير الله، مثل النذر لغير الله، والاستغاثة بالأموات والنجوم والأصنام كله شرك... أما الحي القادر، الحي القادر إذا طلب منه شيء، وهو حي قادر قال: سلفني كذا، وإلا أعطني كذا، هذا ليس بشرك، مثلما قال الله -جل وعلا- في قصة موسى: فَاسْتَغَاثَهُ الَّذِي مِنْ شِيعَتِهِ عَلَى الَّذِي مِنْ عَدُوِّهِ [القصص:15]. فإذا قال: للحي الحاضر: يا فلان! أقرضني، أو أعطني كذا، أو ساعدني على كذا؛ فلا بأس، ليس من الشرك، أما أن يقول للميت، أو الغائب يعتقد أنه يسمعه، وأنه غائب لسر فيه، يعتقد أنه يسمعه، أو يعتقد أنه يقضي حاجاته وهو ميت، أو يفعله مع صنم، أو مع نجم، أو مع الجن يكون شركًا أكبر، نسأل الله العافية. المقدم: نسأل الله السلامة والعافية، إذاً إذا نوى الصلاة لفلان، سواءً كان في أثناء الصلاة ،أو بعد الصلاة الشرك واقع واقع؟ الشيخ: إذا كان يصلي له، يتقرب إليه بالصلاة، ما هو بيثوبها له، يتقرب إليه بركوعها، وسجودها، يعبده؛ فهذا شرك أكبر. المقدم: نسأل الله السلامة والعافية.","link":"https://binbaz.org.sa/fatwas/10613/حكم-تثويب-الصلاة-للغير-او-التقرب-اليه-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40201.mp3","categories":["إهداء القرب للميت"]},{"id":12556,"question":"رسالة وصلت إلى البرنامج من المستمع (م. ص. ع) يقول في رسالته: دخلت أحد المساجد ومعي مصحف، ورأيت في المسجد مصاحف ذات طباعة واضحة، وقمت باستبدال مصحفي بواحد من تلك المصاحف الموجودة في المسجد، هل يحق لي ذلك، أم لا؟","title":"حكم استبدال مصحف أوقف على مسجد بمصحف آخر","answer":"الجواب:  ليس لأحد أن يأخذ من أوقاف المسجد شيئًا، لا من المصاحف، ولا من غيرها، إلا إذا كانت موضوعة للتوزيع، إذا كان وضعها الواضع للتوزيع؛ فلا بأس بذلك، إذا قال له الإمام أو المؤذن: هذه للتوزيع؛ فلا بأس، أما إذا كان وضعت لينتفع بها المصلون، والقراء في المسجد؛ فليس لأحد أن يأخذ منها شيئًا، ولا أن يضع بدلها ما هو دونها، نعم. المقدم: نذكر التعليل لو تكرمتم؟ الشيخ: لأنها وقف، لأنها وقف على القراء في المسجد. المقدم: هذه ناحية. الشيخ: ولأن وجود ما هو أصلح ينبغي أن يبقى للقارئ الذي أراده الموقف، فلا يأخذ الطيب، ويدع ما هو دونه، يبقى الطيب لأهل المسجد. المقدم: وحتى لا يخلو المسجد. الشيخ: وكذلك هذا منه حتى لا يخلو من المصاحف أيضًا، لكن قد يقول: أنا وضعت مصحفي بدل المصحف. المقدم: لا، قصدي حتى لا يخلو المسجد من المصاحف ذات الطباعة الجيدة. الشيخ: نعم هذا مطلوب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10756/حكم-استبدال-مصحف-اوقف-على-مسجد-بمصحف-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41002.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12679,"question":"المستمع: أحمد محمد مصري مقيم في جدة بعث برسالة مطولة بعض الشيء يقول فيها: لي أخت تزوجت من رجل، ثم طلقت منه بعد أن أنجبت منه بنتين، وتزوجت برجل آخر وهي تعمل، ويدخل راتبها البيت، وقد تمكنت من بناء شقة هي وأختها، وزوجها يعلم بذلك، وبعد أن انتهت من بناء هذه الشقة، فإن زوجها يطلب منها أن تكتب ما تمتلكه من هذه الشقة لابنتها التي أنجبتها منه، وحرمان ابنتيها من زوجها الأول، مع العلم أنها بنت هذه الشقة من مالها الذي كانت تعمل وتحصل عليه، وجهونا حول هذا الموضوع، جزاكم الله خيرًا؟","title":"حكم تخصيص أحد الأبناء بهبة دون غيره","answer":"الجواب:  لا يجوز لهذا الرجل أن يلزمها بذلك، ولا أن يأمرها بذلك، ولا يجوز لها أن تطيعه في ذلك؛ لأن هذا من الظلم، والرسول -عليه الصلاة والسلام- يقول: اتقوا الله، و اعدلوا بين أولادكم. فالواجب عليها أن تعدل بين بناتها، وأن يكن سواء في وصيتها وعطيتها، وليس لها أن تحيف فتزيد واحدة على أخرى، وليس له أن يأمرها بذلك، بل هذا حرام عليه، وهو من الإعانة على الإثم والعدوان، ومن الأمر بالظلم فلا يجوز، فليس لها طاعته في هذا الأمر، بل هذه معصية، والرسول  يقول: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق ولو أوصت، أو أعطت البنت التي هي بنته دون البنتين؛ فالعطية باطلة، والوصية باطلة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10889/حكم-تخصيص-احد-الابناء-بهبة-دون-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41708.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12808,"question":"المستمع محمد علي محمد عسيري بعث برسالة مطولة ملخص ما فيها طلب إيضاح أحكام الوقف، وهل يجوز بيعه إذا تعطلت منافعه، ونقله إلى مصالح أخرى، جزاكم الله خيرًا؟","title":"حكم بيع الوقف عند تعطل منافعه","answer":"الجواب:  نعم الوقف لا يباع ولا يوهب ولا يورث كما قاله النبي ﷺ: تصدق بأصلها قال لعمر تصدق بأصلها، لا يباع ولا يوهب، ولكن ينفق وثمره فالوقف لا يباع ولا يوهب ولا يورث، بل يبقى حبسًا تنفق غلته وثمرته في الوجوه التي عين، وجوه الخير التي عينها الواقف، وإذا تعطلت منافعه؛ فإنه يباع، ولا يترك، يباع ويرجع ثمنه فيما هو أصلح منه إذا تعطلت المنافع، لكن من طريق المحكمة، إذا كانت البلاد فيها محكمة؛ تراجع المحكمة حتى تضبط الأمور. أما إذا كان في بلاد ما فيها محكمة؛ فالولي يقوم بذلك، وكيل الوقف يبيعه، ويشتري به ما هو أصلح، إن كان بيتًا؛ اشترى بيتًا أصلح، ولو صغيرًا، أو دكانًا ولو صغيرًا حسب التيسير، يجتهد في تحصيل ما هو أصلح ولا يترك معطلًا؛ لأن هذا من إضاعة المال، والرسول ﷺ نهى عن إضاعة المال، فإذا تعطلت منافع الوقف؛ فإنه يباع، ويشترى به ما هو أصلح من بيت، أو دكان، أو مزرعة، أو نحو ذلك، تنفق ثمرته في الوقف الذي بيع ثمرته مثلما في غلة الوقف الذي بيع حسب الوصية، وحسب وثيقة الوقف. أما إذا كان في بلد فيها محاكم شرعية؛ فإن الوكيل يراجع المحاكم، ويرى ما توجهه إليه. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11022/حكم-بيع-الوقف-عند-تعطل-منافعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_462/46213.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12893,"question":"من المملكة الأردنية الهاشمية الأشرفية المستمع: خليل أحمد صالح بني صالح بعث برسالة، وضمنها جمعًا من الأسئلة، في أحد أسئلته يقول: هل تجوز الصلاة أو الصيام عن الأموات، وهل يصل الأجر للمتوفى كأجر الحي، أم يثاب فقط؟ وجهونا، جزاكم الله خيرًا.","title":"حكم الصلاة والصيام عن الميت","answer":"الجواب: أما الصلاة فلا يصلى عن الأموات، ولم يفعل هذا النبي ﷺ ولا أصحابه، فالصلاة لا يصلى على الأموات مطلقًا، أما الصيام فلا بأس أن يصام عنه إذا كان عليهم دين، إذا مات الميت وعليه صوم نذر، أو صوم كفارة، أو صوم من رمضان لم يصمه، وقد عافاه الله، وصح من مرضه، ولكن تساهل هذا يقضى عنه، لقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه متفق على صحته، وفي المسند بإسناد صحيح عن ابن عباس -رضي الله عنهما-: أن امرأة قالت: يا رسول الله! إن أمي ماتت وعليها صوم رمضان، أفأصوم عنها؟ قال: صومي عن أمك.  واستفتاه جم غفير من الناس، عن الصيام عن أمهاتهم، وعن آبائهم، فأفتاهم بأن يصوموا، أما صوم التطوع فلا، لا يصام عنه تطوعًا، إنما يصام عنه إذا كان عليه صوم دين، صوم فرض واجب، فإذا صام عنه ولده، أو أخته، أو عمته، أو أخوه كله طيب، لقوله ﷺ: من مات وعليه صيام؛ صام عنه وليه يعني: قريبه، يشمل الأب والابن والأخ والعم، ونحو ذلك، أما الصلاة فلا، لا يصلى عن أحد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11108/حكم-الصلاة-والصيام-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_467/46708.mp3","categories":["إهداء القرب للميت"]},{"id":12899,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من لبنان، وباعثها المستمع: حسن الصمريد، الأخ حسن عرضنا جزءًا من أسئلته، وفي هذه الحلقة بقي له مجموعة أخرى، من بين أسئلته في هذه الحلقة يقول: عندما يتوفى مسلم يقرؤون عليه سورة يس على المقبرة، وفي المنزل لمدة أسبوع، ويوم ذكرى مرور أربعين يومًا على وفاته، هل هذا جائز؟ وجهوا الناس حيال هذا الموضوع، فهو منتشر بكثرة؟ جزاكم الله خيرًا.","title":"حكم قراءة يس على الميت بعد موته","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد.  فهذا العمل الذي سأل عنه السائل بدعة، لا أصل له، فلا يشرع أن يقرأ على الميت بعد موته، لا في البيت، ولا في المقبرة، ولا على رأس الأربعين من وفاته، ولا في غير ذلك بهذا القصد، بل هذه من البدع التي أحدثها الناس، وإنما المشروع أن يقرأ عنده حين الاحتضار قبل أن يموت. إذا كان محتضرًا؛ شرع أن يقرأ عنده، وإذا قرئ عنده سورة يس؛ فذلك حسن؛ لأنه ورد فيها بعض الأحاديث: اقرؤوا على موتاكم يس وإن كان في سنده كلام، لكن لا بأس، قد يتعظ بهذا، وقد يستفيد من هذا قبل أن يموت، كما قال ﷺ: لقنوا موتاكم لا إله إلا الله يلقن، يقال له: قل: لا إله إلا الله، حتى يختم له بها، وفي الحديث: من كان آخر كلامه لا إله إلا الله؛ دخل الجنة فذلك من أسباب دخول الجنة إذا مات على التوحيد والإيمان صادقًا مخلصًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11114/حكم-قراءة-يس-على-الميت-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_468/46801.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":12920,"question":"من المستمع حسن سعيد محمد القعيدي من اليمن حضرموت رسالة ضمنها أكثر من سؤال، في سؤال له طويل ملخصه يقول: إذا انقطعت منافع الوقف فهل يباع لينتفع بثمنه في جهة أخرى؟","title":"حكم بيع الوقف إذا تعطلت منافعه","answer":"الجواب:  نعم، إذا تعطلت منافع الوقف؛ يباع ويشترى به ما هو أصلح منه، فإذا كان بيتًا تعطل، أو دكانًا تعطل؛ يباع، ويشترى به بيت أصغر، أو دكان أصغر ينتفع به، أو أرضًا تعطلت من الزراعة، ما رغب فيها الناس؛ تباع حتى تتخذ مساكن، ويشترى بها ما هو أصلح منها، أو يعمرها صاحب الوقف بيوتًا للسكن، إذا كان يستطيع ذلك، ولا تعطل؛ لا يترك الوقف عاطلًا؛ لأن هذا من باب إضاعة المال، لا يجوز، بل يجب أن ينظر في أمره، إما بإصلاحه، وتعميره، وإما ببيعه وشراء ما هو أصلح منه، ويكون ذلك بواسطة المحكمة، إذا كان في البلاد محكمة، في بلاد إسلامية فيها محكمة، وإلا يكون ذلك بواسطة أهل الخير، كمركز إسلامي، أو العالم الذي يوثق به في البلد، أو في الأقلية الإسلامية؛ حتى يتعاون مع ناظر الوقف في ذلك. المقصود: أن ناظر الوقف يتعاون مع أهل الخير في ذلك حتى يبرئ ذمته، وحتى يسلم هذا الوقف من التعطل. أما إذا كان في بلد فيها محكمة؛ فإن الناظر يستشير المحكمة، ويسير على ضوء توجيهات المحكمة في البيع، وفي شراء البديل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11135/حكم-بيع-الوقف-اذا-تعطلت-منافعه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_469/46905.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12926,"question":"على بركة الله نبدأ هذا اللقاء برسالة وصلت من اليمن السائل (ي. ع. أ) يقول: توفي والدي -يرحمه الله- وكنت أراه -والحمد لله- مداومًا على الصلاة، محافظًا على الخير، وأريد أن أقدم له عملًا يزيد من حسناته، ويخفف من سيئاته، فبماذا يتمثل هذا العمل، جزاكم الله خيرًا هل هو بتلاوة القرآن، وإهدائها له؟ أو التصدق، أم الدعاء؟ جزاكم الله خيرًا.","title":"بر الوالدين بعد وفاتهما","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن بر الوالدين من أهم الواجبات، ومن أعظم الفرائض كما قال الله -جل وعلا- في كتابه العظيم: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا [الإسراء:23] قال سبحانه: أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ [لقمان:14] فبرهما من أهم القربات وأفضلها. قد سئل النبي ﷺ فقيل: «يا رسول الله! هل بقي من بر أبوي شيء أبرهما به بعد وفاتهما؟ قال: الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وصلة الرحم التي لا توصل إلا بهما، وإكرام صديقهما كل هذا من حقهما. فنوصيك -أيها السائل- بكثرة الدعاء، كثرة الدعاء لوالديك، لأبيك وأمك، والصدقة عنهما كذلك بالقليل والكثير، على الفقراء والمحاويج، ولاسيما فقراء الأقارب بالنية عن والدك، وعن والدتك جميعًا، وعن نفسك معهما كذلك، وإذا كان له وصية شرعية تنفذها كنصاب الثلث، أو الربع في أعمال البر، في وجوه الخير؛ في ضحايا .. في حج .. في صدقات، عليك التنفيذ. كذلك صلة الأقارب من أعمامك، وبني عمك وأجدادك، تصلهم، وتحسن إليهم بالهدية.. بالصدقة.. بالدعاء.. بالزيارة، كذلك أصدقاؤه -إذا كان له أصدقاء- تكرمهم أيضًا، وتحسن إليهم، كل هذا من حق والدك، ومن حق أمك أيضًا.  أما القراءة لهما فهي غير مشروعة، لم يرد في الشرع القراءة للأموات، تقرأ لنفسك، تقرأ وتسأل ربك أن يتقبل منك، وأن يثيبك، أما إهداء القرآن إلى غيرك لا، لم يرد في الشرع. لكن الدعاء للوالدين والصدقة عنهما، الحج عنهما، العمرة عنهما بعد وفاتهما، كل هذا طيب، إكرام أصدقائهما بالصدقة .. بالزيارة، إكرام أقاربك من أبيك وأمك من أعمام وعمات وأخوال وخالات وغيرهم، كل هذا من بر الوالدين -وفق الله الجميع- نعم.  المقدم: الله آمين.","link":"https://binbaz.org.sa/fatwas/11142/بر-الوالدين-بعد-وفاتهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50101.mp3","categories":["إهداء القرب للميت","الآداب والأخلاق المحمودة"]},{"id":12933,"question":"هذه رسالة وصلت من المغرب، من أحد الإخوة المستمعين، يقول في هذا  شخص أهديت له هدية عبارة عن مجوهرات ذهبية،  هل له أن يبيعها، ويستفيد بثمنها؟ أفتونا جزاكم الله خيرًا.","title":"حكم بيع أو إهداء الهدية","answer":"الجواب:  نعم، إذا أهدي لك هدية، وليست رشوة، هدية من أخ محب، أو من قريب ليست في مقابل خيانة ولا .. فلا بأس، تكون مالًا لك تتصرف فيها .. تبيعها .. تمسكها .. تهديها إلى غيرك، لا بأس، أما إن كانت رشوة حتى تميل عن الحق، أو حتى تحكم بالجور، أو حتى تظلم أحدًا؛ فلا يجوز ذلك، إذا كانت هذه الهدية رشوة لك حتى تظلم، أو تخون في قضية عندك، أو أنت قاضي وتحكم بغير الحق، كل هذا منكر. وأما إذا كان هدية لله وفي الله؛ لأنك صديقه؛ لأنك أخوه في الله؛ لأنك قريبه؛ ليس لأي أمر آخر من أمور الخيانات والظلم؛ فلا بأس بذلك، هي مال لك تتصرف فيها، والسنة لك أن تقابله، أن تثيبه على هديته، كان النبي ﷺ يقبل الهدية، ويثيب عليها، يعني: يعطي عليها المقابل، هذا هو الأفضل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11149/حكم-بيع-او-اهداء-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_501/50108.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12961,"question":"السائل من القصيم يقول: هل إهداء المصحف جائز إذا كان قد أتاني هدية لست بحاجة إليه لوجود آخر عندي، فهل إهداء المصحف جائز؟","title":"حكم إهداء المصحف","answer":"الجواب:  نعم، إلى المسلم تعطيه المسلم، تهديه إلى أحد المسلمين طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11178/حكم-اهداء-المصحف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50217.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":12962,"question":"يقول: هل الصدقة للميت إذا كان أحد الوالدين يكون نوعًا من البر؟ وهل تكفي النية، أو التلفظ، وهل لي بها أجر؟","title":"هل الصدقة للميت إذا كان أحد الوالدين من البر؟","answer":"الجواب:  نعم، الصدقة من البر، الصدقة عن الوالد الميت، أو عن الوالدة، أو عن الأقارب بر من البر والصلة، ولك أجر، والنية كافية ما يحتاج تكلم، النية أنك لما تعطيها الفقير ناويًا أنها عن أبيك، أو أمك يكفي، تكفي النية، والحمد لله، ولك أجر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11179/هل-الصدقة-للميت-اذا-كان-احد-الوالدين-من-البر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_502/50218.mp3","categories":["إهداء القرب للميت"]},{"id":12973,"question":"السائلة تقول في هذا  سمعت بأن الإنسان لا يصله ثواب قراءة القرآن إلا إذا كان من ابنه أو ابنته، وهل هذا يعني بأننا إذا قرأنا القرآن، أو آية منه، ووهبت ثواب ذلك إلى إنسان ميت، أم حي لا يصل هذا الثواب، وهل أؤجر على ذلك، وجهونا في ضوء هذا السؤال؟","title":"الأجر الذي يصل إلى الميت","answer":"الجواب:  الصواب: أن القراءة لا تصل إلى الأموات، ذكر أبو العباس ابن تيمية شيخ الإسلام -رحمه الله- أن هذا لا يجوز بلا نزاع، أخذ الأجرة على مجرد القراءة، وأنها لا تصل إلى الموتى؛ لأنه ما قرأ لله، إنما قرأ للأجرة، وهكذا لو قرأ بدون أجرة لا تصل لعدم الدليل، فلا يصل إلى الموتى إلا ما جاء به الدليل؛ لأن هذه عبادات توقيفية، ليس للرأي فيها مجال، وقد جاءت النصوص دالة على أن الصدقة تنفع الميت، وهكذا الدعاء، هكذا الحج عنه والعمرة، وقضاء دينه. أما كونه يقرأ إنسان له، أو يصلي له، هذا ما عليه دليل، والأصل: أنه لا ينتفع بذلك إلا بدليل، وهذا هو الأرجح، أنه لا يشرع لأحد أن يقرأ لأحد من الموتى، أو يصلي له، أو يصوم له، إلا إذا مات وعليه دين الصوم؛ فإنه ينفع قضاء الدين؛ لقوله ﷺ: من مات وعليه صيام؛ صام عنه وليه إذا مات وعليه صوم من رمضان، ما قضاه، أو كفارة وقضاه عنه غيره ينفعه. أما أن يصلي تطوعًا أو يصوم له تطوعًا؛ هذا لا دليل عليه، أو يقرأ هذا لا دليل عليه، إنما ينتفع الميت بما جاءت به النصوص: بالدعاء بالصدقة عنه .. بالحج عنه .. بالعمرة عنه .. بقضاء دينه هكذا كله جاءت به السنة، يلحق الميت. أما إنسان يقرأ له ولده، و يثوب له هذا ما عليه دليل، والذي ينبغي تركه نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11190/الاجر-الذي-يصل-الى-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50306.mp3","categories":["إهداء القرب للميت"]},{"id":13073,"question":"هذا السائل حمدي يعمل بالرياض يقول: بأنه يعمل بالمملكة، فهل عند عودتي لبلدي لا بد من أخذ هدايا للأهل والأقارب، علمًا بأن ذلك الموضوع سوف يكلفني الكثير، وهل إذا لم آخذ هدايا أكون قد ارتكبت إثمًا من باب قطيعة الرحم لأهلي، وجهونا في ذلك؟","title":"حكم بذل الهدية","answer":"الجواب:  الهدايا غير واجبة، لا، ما هو بلازم، الهدايا غير واجبة، ولا تكون قاطعًا للرحم إذا ما حملت هدايا، الهدايا باختيارك إن رأيت أن تأخذ هدايا لخواص أقاربك؛ فلا بأس، وإلا ليس بلازم، أنت أعلم بالمصلحة، المهم أن تحفظ المال لحاجة البيت، وحاجتك، وحاجة أهلك، فإذا اشتريت هدية خفيفة للزوجة، أو لأبيك، أو لأمك، أو لإخوانك؛ فلا بأس، وإن شق عليك ذلك؛ فالحمد لله، ما لزوم هدية، المال احفظه لحاجة البيت، لحاجتك، أو لقضاء دينك، أما الهدايا فهي مستحبة عند اليسر .. عند القدرة واليسر إذا أهديت لإخوانك، الرسول ﷺ يقول: تهادوا تحابوا اللهم صل عليه وسلم، فالهدية طيبة مع القدرة، ومع السعة إذا تيسرت من غير تكلف. المقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11289/حكم-بذل-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50705.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13078,"question":"هذه سائلة تقول في هذا  عندي مبلغ من المال، وأريد أن أجعله وقفًا في سبيل الله  و أي الأعمال أفضل في هذا الوقف، هل هو بناء مسجد، أم غيره أفضل، دلوني يا سماحة الشيخ مأجورين؟","title":"أفضل أنواع الوقف","answer":"الجواب:  إذا كان المال كثيرًا فاجعليه في عقار... في وجوه الخير، بناء المساجد، والصدقة على الفقراء والمساكين، ومساعدة طلبة العلم في طلب العلم، مساعدة من يقوم بعمل شرعي، ويعجز عنه. المقصود: أن يكون في أعمال البر، إذا كان مالًا كثيرًا، يشترى به عقارًا كبيرًا، أو عقارات توقف في أعمال البر، ووجوه الخير، من الصدقة على الفقراء والمساكين .. من مساعدة المجاهدين في سبيل الله .. من بناء المساجد إلى غير هذا من وجوه الخير، الصدقة على الأقارب المحاويج، إلى غير ذلك. أما إن كان قليلًا فاصرفيه في الصدقة على الفقراء إذا كان في أقارب فقراء؛ فأعطيهم إياه، فإن كان ما هناك أحد؛ يصرف في تعمير المساجد، أو في الفقراء في غير البلد إذا كان ما في البلد فقراء بلدك. المقصود: أنه يكون في وجوه البر، لكن إذا كان قليلًا؛ تجعلينه في الفقراء، أو في تعمير المساجد مساهمة، كله طيب. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11295/افضل-انواع-الوقف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50710.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13092,"question":"بالنسبة -يا سماحة الشيخ- إلى قراءة القرآن عند الدفن؟","title":"حكم قراءة القرآن عند دفن الميت","answer":"الجواب:  بدعة ما لها أصل، لا يقرأ عند الدفن قرآنًا، القرآن محله المساجد والبيوت ما هو بمحل القبور، ولهذا في الحديث الصحيح يقول ﷺ: اجعلوا من صلاتكم في بيوتكم، ولا تتخذوها قبورًا؛ فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة دل على أن القبور ما هي بمحل صلاة، ولا محل قراءة، القراءة والصلاة محلها البيوت والمساجد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11309/حكم-قراءة-القران-عند-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50803.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":13106,"question":"تقول: اشتريت بمبلغ من المال كتبًا صغيرة، وهي الأذكار طرفي النهار، ونويت عند شراء هذه الكتب أن أتصدق بها، وأجعل ثواب ذلك لزوجي المتوفى، فما الحكم أيضًا في هذا السؤال؟","title":"حكم التصدق عن المتوفى","answer":"الجواب:  كل هذا طيب، تتصدق بكتب، أو بطعام عن زوجها، الكتب الطيبة المعروفة عند أهل العلم أنها طيبة، أو بطعام، أو ملابس، كله طيب، عن زوجها، وعن أبيها، وعن نفسها، الحمد لله. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11323/حكم-التصدق-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_508/50814.mp3","categories":["إهداء القرب للميت"]},{"id":13147,"question":"أم بكر من الدمام سائلة تقول: هل يصل أجر قراءة القرآن للميت حينما يقرأ الأبناء على نيتهم بالنسبة لوالدهم؟ وهل الدعاء له فضل، أم قراءة القرآن الكريم أفضل، جزاكم الله خيرًا؟","title":"هل يصل أجر قراءة القرآن للميت؟","answer":"الجواب:  القرآن لا يقرأ عن الناس، لا عن الميت، ولا عن غيره، كل يقرأ لنفسه، وثوابه لنفسه؛ لأنه لم يرد في الأدلة الشرعية أن أحدًا يقرأ عن أحد، أو لأحد، وذكر أبو العباس شيخ الإسلام ابن تيمية -رحمه الله- أنه ليس هناك نزاع بين أهل العلم في أنه لا يقرأ للميت، لا يقرأ أحد لأحد، قال: إنه لا نزاع فيه بين أهل العلم أن هذا ممنوع، لكن الصدقة والدعاء أمر مطلوب، إذا دعا للميت، وقال: اللهم اغفر له، اللهم ارحمه، اللهم أنجه من النار، اللهم تقبل أعماله، أو تصدق عنه، هذا طيب، وهذا ينفع الميت؛ لقول النبي ﷺ: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له وقد أخبر الله عن السلف الصالح أنهم كانوا يدعون لسابقيهم قال تعالى: وَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ وَلا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَحِيمٌ [الحشر:10]. فالدعاء مشروع للحي والميت بإجماع المسلمين، ليس فيه نزاع، وصلاة الجنازة دعاء للميت، المسلمون يدعون للميت بعد التكبيرة الثالثة، ما بعد التكبيرة... كله دعاء للميت، فالدعاء للميت فيه خير كثير، ومصالح جمة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11401/هل-يصل-اجر-قراءة-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51007.mp3","categories":["إهداء القرب للميت"]},{"id":13170,"question":"تقول في سؤالها الثاني: في مدينتنا يتم مباشرة بعد دفن الميت توزيع الأرز أو البر، فهل هذا جائز، علمًا بأننا لم نقم بتوزيع أي شيء، فقط وزعنا من مالها بعد وفاتها بأسبوع، وجزاكم الله خيرًا؟","title":"حكم توزيع المواد الغذائية بعد دفن الميت","answer":"الجواب:  لا أصل لهذا، كونه عند الوفاة يوزع هذا الشيء أرزًا أو تمرًا، لكن الصدقة عنه على المهل في أوقات مستقبلة لا بأس، أما اعتقاد أن التوزيع عند الموت، أو عند الدفن سنة لا، لا أصل لهذا، لكن بعد ذلك إذا أحب أهل الميت أن يصدقوا عنه للفقراء والمساكين بالنقود، أو بالطعام؛ فلا بأس بذلك، من غير أن يخصصوا وقت الموت، أو عند القبر، أو يوم الموت، هذا لا أصل له، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11425/حكم-توزيع-المواد-الغذاىية-بعد-دفن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_511/51106.mp3","categories":["إهداء القرب للميت"]},{"id":13221,"question":"يقول هذا السائل: أسأل عن قراءة الفاتحة مثلًا على أرواح الموتى، هل هذا جائز؟","title":"حكم قراءة الفاتحة على أرواح الموتى","answer":"الجواب: ما له أصل، ليس له أصل، لا الفاتحة ولا غيرها، لا يقرأ للموتى لا الفاتحة ولا غيرها، القراءة للأموات ليس له أصل، ولكن يدعى لهم بالمغفرة والرحمة، يتصدق عنهم، هذا هو المشروع، يحج عن الميت، ويعتمر عنه، أما يقرأ له القرآن هذا لا أصل له، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11501/حكم-قراءة-الفاتحة-على-ارواح-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51218.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":13231,"question":"السائلة من اليمن تقول: لي جارة ملتزمة بشرع الله، والحمد لله، ولكن زوجها شارب للخمر، وهناك شبهة في بيعه للخمر، ما حكم الأكل الذي تهديه لي هذه الجارة، هل أقوم بأكله أم لا، وهل أقبل ما تهديه إلي من هدايا؛ علمًا بأنها تدعوه إلى الله؛ فلا يجيب، وجهونا بذلك؟","title":"حكم قبول الهدايا ممن اختلط ماله بالمال الحرام","answer":"الجواب:  لا حرج في ذلك إذا كان سامحًا لها تهديه، إذا كان سامحًا لها تهديه من ماله؛ فلا بأس؛ لأن المال المختلط يجوز أخذه، والنبي ﷺ أكل من طعام أهل الكتاب، واشترى منهم، وهم يأكلون الربا، ومع هذا اشترى منهم طعامًا، وأكل من طعامهم؛ فدل ذلك على أن المال المختلط الذي فيه ربا، أو فيه ثمن خمر، أو ما أشبه ذلك، وعندهم أموال أخرى حلال لا بأس، الأصل الحل والإباحة حتى تعلم أن هذا المال ربا أو هذا المال من ثمن الخمر، فلا، إذا علمت أن هذا الطعام اشتراه من ثمن الخمر، أو اشتراه من الربا فلا يجوز، وأما إذا لم تعلم؛ فالأصل الإباحة والحل. ولكن هذا الزوج ينبغي لها أن تبتعد عنه مهما أمكن، وإن كان مسلمًا لكن كونه يعتاد شرب الخمر؛ هذه معصية عظيمة، وفسق ظاهر، فكونها تطلب الطلاق منه وتعافه خير لها وأولى لها، وخير لذريتها أيضًا، نسأل الله العافية والسلامة. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11512/حكم-قبول-الهدايا-ممن-اختلط-ماله-بالمال-الحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52014.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13273,"question":"السائل يقول: هل تقبل هدية من مشرك؟","title":"حكم قبول الهدية من المشرك","answer":"الجواب: هذا فيه تفصيل: إذا كانت الهدية لا تتضمن شرًا على مسلم، لا يتسلط بها الكافر عليه، أو لا يتجرأ بها على المسلمين، ولا يترتب عليها شر؛ فإنه يقبلها المسلم، ويكافئ عليها، يكافئ عليها مثلها، أو أحسن منها، والنبي ﷺ قبل من قوم، ورد على قوم، قبل من مشركين بعض الهدايا، ورد على آخرين، لم يقبل هداياهم. فإذا كان قبولها أصلح، يترتب عليها تأليف قلبه، ومحبته للمسلمين، ويثيب عليها أكثر من المهدى إليه؛ قبلها، فإن كان قبولها يسبب شرًا على المسلمين، أو أن هذا المهدي يتجرأ على المسلمين، أو يؤذيهم، أو يفعل أشياء تضرهم بسبب هذه الهدية، أو المُهدَى إليه هذه الهدية تفضي إلى محبته للكافر المُهدِي، والتعاون معه فيما يضر المسلمين؛ لم يقبلها؛ لئلا تضره؛ لئلا تجره إلى الباطل. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11557/حكم-قبول-الهدية-من-المشرك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_509/50910.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":13345,"question":"من أسئلة السائلة (ن. ع. م) من الأردن تقول: توفي خالي، وأردت أن أتصدق عنه، فقال لي البعض من الناس: بأنه لا يجوز أن تتصدقي إلا عن والدك بعد موته، أما غيره مثل: العم، والخال فلا تصل الصدقة لهم، فما رأيكم في ذلك سماحة الشيخ؟","title":"هل تجوزالصدقة عن غير الوالدين؟","answer":"الجواب: هذا الذي قال هذا الكلام جاهل، غالط، بل الصدقة تقبل، وتنفع عن الأب والأم، وعن غيرهما من فضل الله -جل وعلا- الصدقة للميت تنفعه، والدعاء له ينفعه، فإذا تصدقت عن عمك، أو عن أخيك، أو عن غيرهما؛ فلا بأس كله طيب، يقول النبي ﷺ: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية... هذا عام أو علم ينتفع به، أو ولد صالح يدعو له وسأله رجل، قال: يا رسول الله! إن أمي توفيت، ولم توص، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم. فالصدقة فيها خير كثير عن الحي والميت، وهكذا الدعاء والاستغفار للحي والميت، والحج عن الميت، والعمرة عن الميت، وهكذا عن الكبير العاجز، والعجوز الكبيرة، الحج عنها، والعمرة عنها. المقصود: أن الصدقة عن الميت فيها خير كثير، وعن الحي أيضًا، سواء، كان عمًا، أو أخًا، أو أبًا، أو غيرهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11631/هل-تجوزالصدقة-عن-غير-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54206.mp3","categories":["إهداء القرب للميت"]},{"id":13477,"question":"من جمهورية السودان المستمع ياسر محمد بعث يسأل ويقول: هل الصدقة والحوليات التي يعملها أهل الميت تصل إليه؟ وهذه الفاتحة هل تصل أيضًا، أم يعتبر كل ذلك خرافة؟","title":"هل الصدقة والحوليات تنفع الميت؟","answer":"الجواب: نعم الصدقات والضحايا، وسائر القربات التي شرعها الله تنفع الميت، وتصل إليه، تنفعه كما قال النبي ﷺ: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له وفي الصحيحين أن رجلًا قال: يا رسول الله! إن أمي ماتت، ولم توص، أفلها أجر إن تصدقت عنها، قال النبي ﷺ: نعم وسأله جماعة عن أمهاتهم، وآبائهم ماتوا وعليهم حج، أفيحجون عنهم؟ قال: نعم، حج عن أبيك وقال للأخرى: حجي عن أمك إلى غير ذلك. فالصدقات عن الموتى، والحج عنهم، والعمرة عنهم كل هذا ينفعهم، ويصل إليهم، وهكذا الاستغفار لهم والدعاء، وقضاء ديونهم، وقضاء ما عليهم من الصيام الذي ماتوا وعليهم صيام نذر، أو صوم كفارة، أو صوم رمضان، تساهلوا ولم يصوموه، بعدما عافاهم الله من المرض إن كانوا مرضى، هذا يصام عنهم وينفعهم، أما من مات في مرضه فلا يصام عنه؛ لأنه معذور. أما البدع التي يبتدعها الناس فلا، بدع أشياء ما شرعها الله، هذه لا تنفع، بل تضر، تضر من ابتدعها، ما تضر الميت، تضرهم هم، من ابتدع الاحتفال بالموالد، أو احتفال بأشياء ما أنزل الله بها من سلطان لأجل الموتى، حوليات ما شرعها الله، باحتفال في مثل ليلة سبع وعشرين من رجب، أو ليلة النصف من شعبان، أو ليالي أخرى يبتدعونها، ويجعلون فيها احتفالات بأشياء يفعلونها للموتى، هذه ما تنفع، هذه تضر من فعلها، لأنها بدع منكرة، والرسول  قال: من عمل عملًا ليس عليه أمرنا؛ فهو رد. وإنما الذي ينفع الموتى الصدقة عنهم، والدعاء لهم، والاستغفار، والحج عنهم، والصوم عنهم إذا كان عليهم صوم، والدعاء لهم كل هذا ينفع الميت، والضحية عنه صدقة، الضحية عنه صدقة. نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11780/هل-الصدقة-والحوليات-تنفع-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_478/47806.mp3","categories":["إهداء القرب للميت"]},{"id":13605,"question":"هذا السائلة التي رمزت لاسمها بـ (ف. أ. ط)، تقول في هذا  ما حكم قراءة الفاتحة على الميت عند قبره؟","title":"حكم قراءة الفاتحة على الميت عند قبره","answer":"الجواب: بدعة، لا يقرأ على القبور، إذا زار الميت يسلم عليه يقول: السلام عليك يا فلان، غفر الله لك، رحمنا الله وإياك، السلام عليكم يا أهل القبور، يغفر الله لنا ولكم، وأما القراءة لا، لا يشرع، لا الفاتحة، ولا غيرها، لا يقرأ عند القبور الفاتحة، ولا غيرها، بل ذلك من البدع، ولا يصلي عند القبور أيضًا، ولكن يسلم عليهم يقول: السلام عليكم أهل الديار، من المؤمنين والمسلمين، وإنا -إن شاء الله- بكم لاحقون، نسأل الله لنا ولكم العافية، يغفر الله لنا ولكم، كما علم النبي أصحابه هذا الدعاء، هكذا يعلم أصحابه، عليه الصلاة والسلام. أما الصلاة عند القبور، أو الطواف بها، أو القراءة عندها، فكل هذا لا يجوز، الصلاة عندها بدعة، والقراءة عندها بدعة، والطواف بها إذا أراد بذلك التقرب إلى الميت شرك أكبر. أما إذا ظن أن الطواف بها قربة وطاعة لله؛ يعني فهذا بدعة، مثل الصلاة عندها نسأل الله العافية، أما إذا صلى لصاحب القبر، أو طاف لصاحب القبر، يتقرب إليه بذلك؛ هذا من الشرك الأكبر، نعوذ بالله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11940/حكم-قراءة-الفاتحة-على-الميت-عند-قبره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52723.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":13990,"question":"السائل يقول في هذا  إذا مات الميت ودعا له أحد من أهله مثل: والدته أو أبوه أو إخوانه هل يصله ذلك الدعاء؟ وهل يعلم بالشخص الذي دعا له؟","title":"هل ينتفع الميت بالدعاء؟ وهل يعلم من دعا له؟","answer":"الجواب: الدعاء ينفع الميت كما ذكر الله عن المؤمنين من السلف الصالح، يقول الله عنهم: وَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ[الحشر:10] فالدعاء ينفع الميت، ويقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له وشرع الله صلاة الجنازة؛ لأن المسلمين يدعون للميت في صلاة الجنازة بعد التكبيرة الثالثة يستغفرون له ويترحمون عليه، فالدعاء ينفع الميت بإجماع المسلمين، وهكذا الصدقة عنه فإذا دعا له أقاربه أو غير أقاربه نفعه ذلك، وهكذا الصدقة عنه والحج عنه والعمرة كل هذا ينفعه ويزاد في حسناته وفي ثقل ميزانه، أما كونه يعلم ذلك فهذا إلى الله . نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12399/هل-ينتفع-الميت-بالدعاء-وهل-يعلم-من-دعا-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53911.mp3","categories":["إهداء القرب للميت","مسائل متفرقة في العقيدة"]},{"id":13992,"question":"هذا السائل ناصر إبراهيم من حوطة بني تميم، يقول في هذا  حصل وأن قمت ببيع بيت صغير مبني من الطين، وبعد البيع عثرت الوالدة على وثيقة لهذا البيت ووجد فيها وقف في أضحية من ريعه دون علمي ولم يدخل علي من هذا البيت شيء من إيجاره، والمبلغ المبيوع بهذا البيت هو خمسة آلاف ريال منذ أكثر من عشر سنوات، فهل يسقط البيع شرعًا في هذه الحالة، أم يلزمني نقل الوقف ويبقى في ذمتي سماحة الشيخ؟","title":"حكم من باع شيئًا وتبين أنه وقف","answer":"الجواب: عليك مراجعة المحكمة في إبطال البيع وبقاء الوقف على حاله، وعرض الوثيقة على القاضي والقاضي ينظر في الأمر، فإن لم يتيسر رد البيع فالثمن يجعل في وقف آخر الذي دخل عليك يكون في وقف آخر، يكون في نخلة تقع وقفًا له، يكون في أواني تكون وقفًا له تستعمل ينتفع بها، المقصود: الثمن تجعله في شيء ينفع الميت نخلة أو نخلتين ينتفع بثمرها أو غير ذلك مما ينفع الميت، حسب التيسير. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/12407/حكم-من-باع-شيىا-وتبين-انه-وقف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53916.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14019,"question":"الرسالة التالية رسالة وصلت إلى البرنامج من ألمانيا الغربية، باعث الرسالة مستمع من هناك يقول: أخوكم محمد فريحة، الأخ محمد يسأل ويقول: أرجو إفادتي عن السؤال التالي: هل يصل إهداء قراءة القرآن إلى روح الأموات؟ إذا كان الجواب نعم، فالمعروف أن الشافعي رحمه الله ينكر هذا، وقال مالك رحمه الله: ما علمنا أحدًا فعل ذلك، ومذهب أحمد أيضًا: ألا قراءة على القبر، هذا ما قرأته في كتاب رياض الصالحين، أرجو إعطائي الجواب الشافي، أسأل الله لنا ولكم العافية.","title":"هل يصل الميت ثواب قراءة القرآن؟","answer":"الجواب: هذه المسألة اختلف فيها العلماء رحمة الله عليهم: فمنهم من رأى أن القراءة للأموات تنفعهم وتلحقهم، وقاسوا ذلك على الصدقة عنهم والدعاء لهم.\nوآخرون من أهل العلم كـالشافعي رحمه الله وجماعة من أهل العلم قالوا: لا، لا تلحقهم؛ لأنه ليس عليها دليل، لم يرد عن النبي ﷺ ولا عن الصحابة فعل ذلك والعبادات ليست محل قياس العبادات توقيفية ليست محل قياس، فلا يلحق الأموات إلا ما جاء به الشرع كالصدقة عنهم والدعاء لهم والحج عنهم وقضاء الدين عنهم والعمرة عنهم فهذا هو الذي جاءت به النصوص، أما القراءة عنهم أو الصلاة عنهم هذا لم يرد وهذا هو الصواب.\nالصواب والأرجح من قولي العلماء: أنه لا يلحق الأموات إلا ما دل عليه الشرع، فالقراءة لهم والصلاة عنهم ليس عليهما دليل والصوم عنهم تطوع كذلك لا يلحقهم، هذا هو الصواب وهذا هو المعتمد، أما الصوم عنهم إذا كان ... واجب قضى عنهم ديناً واجباً كصوم رمضان مات ولم يصم بغير عذر يعني: أفطر ..... مرض مثلاً أو سفر ثم لم يقض تساهل ولم يقض فهذا يصام عنه كما قال النبي ﷺ: من مات وعليه صيام صام عنه وليه، كذلك الديون تقضى عنهم وهكذا الحج عنهم والعمرة، وهكذا الدعاء لهم والاستغفار لهم كله يلحقهم كله ينفعهم، وأما القراءة لهم والصلاة لهم هذا لا، ليس عليه، أو صوم تطوع لهم ليس عليه دليل، وقوله بأن ذلك لا يلحقهم هو الأرجح وهو الأقرب والأفضل في الدليل والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا ما قرأه أخونا في كتاب رياض الصالحين هو الصحيح؟\nالشيخ: ... فيه الخلاف .\nالمقدم: فيه الخلاف؟\nالشيخ: نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12437/هل-يصل-الميت-ثواب-قراءة-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_611/61107.mp3","categories":["إهداء القرب للميت","القرآن وعلومه"]},{"id":14108,"question":"هل يجوز أخذ أي كتاب سواء كان قرآن أو أي كتاب آخر كتب عليه وقف، هل يجوز أخذه من المسجد؟","title":"حكم أخذ كتاب أو مصحف موقوف في مسجد","answer":"الجواب: لا يجوز أخذه من المسجد، بل يترك في المسجد لينتفع به من كان في المسجد من القراء، يطالعون فيه يستفيدون منه؛ لأن الواضع الذي وضعه في المسجد أو في مكتبة المسجد قصده نفع الناس، فلا تأخذ المصحف الذي في المسجد ولا الكتاب الذي في المسجد، دعه للقراء في المسجد أو في المكتبة التي في المسجد.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12548/حكم-اخذ-كتاب-او-مصحف-موقوف-في-مسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48416.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14232,"question":"المستمع (م. م) من قطر بعث يسأل ويقول: هناك بعض أناس يأتون بمصاحف قديمة ويضعونها في المساجد ويستبدلونها بمصاحف جديدة من نفس المسجد فهل هذا جائز؟","title":"حكم استبدال المصاحف من المسجد واستعارتها","answer":"الجواب: ليس لأحد أن يأخذ من مصاحف المسجد شيء، المصاحف التي في المسجد يجب أن تبقى في المساجد وليس لأحد أن يأخذ منها شيئًا أو يبدلها، بل الواجب تركها في المساجد؛ لأن أهلها أرادوا أنها وقف لينتفع بها المسلمون في المسجد، فليس لأحد أن يأخذ منها شيئًا ولا أن يبدلها لا بقديم ولا بجديد.\nالمقدم: هل الاستعارة من المساجد جائزة أو لا؟\nالشيخ: ليس له أن يستعير، أما من المكتبات لا بأس إذا سمح مدير المكتبة والقائم عليها بالإعارة لا بأس، أما ما وضع في المسجد من الكتب أو من المصاحف فلا يستعار بل يطالعه وهو في المسجد. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12691/حكم-استبدال-المصاحف-من-المسجد-واستعارتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48606.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14241,"question":"في آخر أسئلته يقول هذا السائل من اليمن: هل يجوز الذبح وقراءة القرآن على الموتى؟","title":"حكم الذبح وقراءة القرآن على الموتى","answer":"الجواب: هذا فيه تفصيل: الذبح إن كان قصده الضحية عن الميت يضحي عنه فالضحية مشروعة للحي والميت، كونه يضحي عنه أو يذبح ذبيحة يتصدق بها يعطيها الفقراء عنه لا بأس. أما الذبح له يتقرب إليه وهو للميت هذا شرك، ... يذبح له يتقرب إليه كما يذبح عباد الأصنام لأصنامهم هذا شرك أكبر، أما أن يذبح يتقرب إلى الله أضحية عن الميت أو صدقة يعطيها الفقراء عن الميت، أو يتصدق بدراهم أو بطعام عن الميت فهذا لا بأس به، بل فيه نفع للميت، يقول ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. قال رجل: يا رسول الله! إن أمي ماتت ولم توص أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم، فهذا فيه خير عظيم.\nأما القراءة عند القبور فبدعة لا يشرع القراءة عند القبور، ولا الصلاة عند القبور، بل هذا من البدع، بل هو من وسائل الشرك، ولهذا يقول ﷺ: اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبورًا دل على أن القبور ما يصلى فيها ولا يقرأ عندها، اجعلوا من صلاتكم في بيوتكم ولا تتخذوها قبورًا، فإن الشيطان يفر من البيت الذي تقرأ فيه سورة البقرة، هذا يدل على أن البيوت هي محل الصلاة والقراءة، أما القبور لا ليست محل الصلاة والقراءة، فالبيت تصلى فيه النافلة، يصلي فيه المريض إذا عجز عن المسجد، يقرأ في البيت كل هذا طيب، أما القبور فإنما تزار للدعاء لهم والترحم عليهم والإحسان إليهم بالدعاء، أما أن يتخذها للصلاة عندها أو للذبح عندها أو للقراءة عندها فهذا بدعة. نعم.","link":"https://binbaz.org.sa/fatwas/12697/حكم-الذبح-وقراءة-القران-على-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53013.mp3","categories":["إهداء القرب للميت","نواقض الإسلام"]},{"id":14248,"question":"السائلة أم أحمد ومقيمة بالدمام تقول في هذا  هل الأموات يشعرون بما يقدم لهم من قراءة الفاتحة أو قراءة القرآن؟","title":"حكم قراءة القرآن للموتى وهل ينتفعون بها؟","answer":"الجواب: لا يشرع أن يقرأ للأموات قراءة القرآن لا الفاتحة ولا غيرها ولكن يدعى لهم، الأموات يدعى لهم ويتصدق عنهم ويحج عنهم ويعتمر لا بأس، أما قراءة القرآن لهم ليس له أصل، القارئ يقرأ يطلب الأجر من الله لنفسه ويدعو لأمواته؛ أبويه أو غيرهم يدعو لهم بالمغفرة والرحمة، فالدعاء مطلوب، أما القراءة للأموات فلا أصل لها وليس بمشروع، والدعاء ينفعهم -ينفع الأموات- الدعاء ينفعهم والصدقة تنفعهم الصدقة عنهم تنفعهم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12710/حكم-قراءة-القران-للموتى-وهل-ينتفعون-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54908.mp3","categories":["إهداء القرب للميت"]},{"id":14304,"question":"رسالة وصلت إلى البرنامج من المملكة الأردنية الهاشمية باعثها مستمع من هناك، يقول السائل (س. س. ن. د) يسأل ويقول: ما حكم قراءة الفاتحة بعد الصلاة، ذلك أن أحد الأشخاص قال: إننا نتوسل بها إلى الله أن يغفر لنا ولوالدينا ونهديها إلى موتانا ثم إلى روح النبي ﷺ، ما حكم ذلك؟ هل يصل ثوابها إلى روح الموتى؟ وجهونا جزاكم الله خيرًا.","title":"حكم قراءة الفاتحة بعد الصلاة وأهداء ثوابها للموتى","answer":"الجواب: لا نعلم لهذا أصلًا، والعبادات بالتوقيف والأدلة لا بالآراء والأهواء، العبادات توقيفية لا يشرع منها إلا ما شرعه الله ورسوله، ولا نعلم في الأدلة الشرعية شرعية قراءة الفاتحة بعد الصلاة وتثويبها للموتى، ولا الاجتماع على قراءتها لطلب الثواب، كل هذا لا أصل له، وإنما المشروع للمؤمن أن يقرأ القرآن ليتدبر ويتعقل ويستفيد وليحصل له الأجر بذلك. أما أن يخترع شيئًا ما شرعه الله في وقت لم ترد به السنة، هذا ليس بجائز؛ لأن الرسول عليه السلام يقول: من عمل عملاً ليس عليه أمرنا فهو رد، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا ما ليس منه فهو رد، ولم يرد عنه فيما نعلم من الشرع أنه شرع للأمة قراءة الفاتحة بعد كل صلاة، أو تثويبها للموتى، أو قراءتها بصفة جماعية في أي وقت من الأوقات كل هذا لم يرد ولم نعرفه من الشرع المطهر.\nوالواجب على أهل الإيمان وأهل الإسلام أن يسعهم ما وسع الرسول ﷺ وأصحابه، وليس لأحد أن يحدث شيئًا لم يشرعه الله.\nولم يرد أيضًا أن القرآن يقرأ للموتى، ويثوب للموتى وإن كان قاله جمع من أهل العلم لكن أقوال العلماء تعرض على الكتاب والسنة، فما وافق النص قبل، وما لا فلا، وقد تأملت هذه المسألة فلم أجد في النصوص ما يدل على قراءة القرآن للموتى وتثويبه للموتى، ولكن المشروع الدعاء لهم بالمغفرة والرحمة بالجنة بالسعادة، بالعفو والمسامحة الصدقة عنهم، الحج عن الميت، العمرة عن الميت، قضاء الدين عن الميت، كل هذا مشروع.\nأما أن يصلى عنه أو يقرأ عنه فليس له أصل، أو يصام عنه تطوع فليس له أصل، أما إذا كان عليه صوم فريضة مات ولم يقضه فإنه يشرع الصيام عنه، كأن يكون عليه صوم من رمضان تساهل فلم يقضه، أو كفارة فإنه يصام عنه كما قال النبي ﷺ: من مات وعليه صيام صام عنه وليه متفق على صحته، وسأله جماعة عليه الصلاة والسلام، وأحدهم يقول: إن أمي ماتت وعليها صوم كذا، والآخر يقول: إن أبي مات وعليه صيام كذا، فيقول لهم ﷺ: أرأيت لو كان على أبيك.. أرأيت لو كان على أمك دين أكنت قاضيته؟ أكنت قاضيه؟ اقضوا الله؛ فالله أحق بالوفاء هذا هو المشروع.\nوالواجب على المؤمن والمؤمنة التقيد بما جاء في الشرع، وعدم إحداث شيء لم يشرعه الله  لا في الصوم ولا في القراءة ولا في الصلاة ولا في غير ذلك. وفق الله الجميع.\nالمقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/12799/حكم-قراءة-الفاتحة-بعد-الصلاة-واهداء-ثوابها-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62209.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":14431,"question":"لدي أخت توفي ابنها في حادث سيارة، ولم يترك وراءه مالًا إلا ما يأتيه من التقاعد، ويستلمه والده، ولم يعط والدته شيئًا.الشيخ: أعد.المقدم: تقول: لدي أخت توفي ابنها في حادث سيارة ولم يترك وراءه مالًا إلا ما يأتيه من التقاعد ويستلمه والده، ولم يعطها شيئًا؛ لكي تتصدق به عنه، وعندما تقول: تصدق عنه. يقول: لو فعلت ذلك، إنها لا تملك شيئًا من المال لكي تتصدق به، هل عليها ذنب في ذلك؟ وماذا تفعل؟جزاكم الله خيرًا.","title":"حكم الصدقة عن الميت من ماله","answer":"الجواب: ليس عليها شيء، ولا بأس بذلك، وليس على أبيه شيء إذا لم يتصدق عنه، هم أحوج إلى الصدقة، إذا كانوا فقراء فهم أحوج إلى التقاعد، حتى يأكلوه، هم وأولادهم، وإذا تيسر لهم الصدقة عنه من مالهم ولو قليلًا فالصدقة تنفع الميت، لكن لا يلزم الصدقة إذا كان لم يوص بشيء فلا تلزم الصدقة.  أما إن كان أوصى بشيء من ماله إذا كان له مال وأوصى بشيء بالثلث فأقل تنفذ وصيته، وأما إن كان ما أوصى بشيء فإنه لا شيء يلزم الأم، ولا يلزم الأب، والتقاعد الذي للميت يكون للورثة لأبيه وللورثة مع أبيه، لأبيه وأمه، وإن كان له أولاد فلأولاده حصتهم، ولزوجته حصتها من التقاعد، وإن كانت الدولة جعلته لبعضهم، جعلته لأبيه وحده، أو جعلته لأمه أو لأبيه وأمه فالدولة تنظر في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12946/حكم-الصدقة-عن-الميت-من-ماله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_624/62410.mp3","categories":["إهداء القرب للميت"]},{"id":14522,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المدينة المنورة، وباعثتها إحدى الأخوات المستمعات من هناك تقول: أم عبير، أم عبير لها أربعة أسئلة في سؤالها الأول تقول: هل الذبح يندرج تحت باب الصدقة؟ وإذا أردت أن أذبح من أجل التصدق عن الميت هل هذا جائز؟وجهوني، جزاكم الله خيرًا.","title":"ما حكم الذبح بنية التصدق عن النفس والميت؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا شك أن الذبح لله، والتقرب إليه بذلك من أفضل الصدقات، ومن أفضل القربات، كما قال الله : قُلْ إِنَّ صَلاتِي وَنُسُكِي يعني: ذبحي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ  ۝ لا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ [الأنعام:162-163] وقال سبحانه: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ۝ فَصَلِّ لِرَبِّكَ وَانْحَرْ[الكوثر:1-2]. فالتقرب إلى الله بالذبائح فيه خير عظيم؛ ولهذا شرع الله -جل وعلا- الضحية في أيام عيد النحر، وكان النبي ﷺ يضحي بكبشين أملحين كل سنة -عليه الصلاة والسلام-، أحدهما عنه وأهل بيته، والثاني عمن وحد الله من أمته -عليه الصلاة والسلام-. فإذا ذبح الإنسان ذبيحة يقصد بها التقرب إلى الله، ونفع الفقراء، أن ينفع الفقراء، ويحسن إليهم، فلا بأس بذلك، وكان -عليه الصلاة والسلام- يذبح في بعض الأحيان الذبيحة، ويوزعها بين صديقات زوجته خديجة -رضي الله عنها-، وهكذا التصدق بالنقود، وبالطعام من التمر أو الأرز أو غير ذلك، أو الملابس، كل ذلك قربة وطاعة إذا كان لله وحده  على الوجه الذي شرعه الله -جل وعلا-. أما الذبح من أجل التقرب إلى الموتى كالذبح للبدوي أو للحسين أو للشيخ عبدالقادر الجيلاني يقصد التقرب إليهم ليشفعوا له أو ليشفوا مريضه، أو يقضوا حاجته أو يطلبوه المدد ويذبح لهم من أجل ذلك هذا شرك بالله، ولا يجوز؛ ولهذا قال -عليه الصلاة والسلام-: لعن الله من ذبح لغير الله. فالتقرب بالذبائح للموتى، ليشفعوا للذابح، أو ليقضوا حاجته، أو ليشفوا مريضه، أو يمدوه بمدد ينفعه، أو يحفظوا مزرعته أو بهائمه كل هذا شرك بالله ، وقد يفعل هذا بعض الجهلة وهذا من الشرك الأكبر، وهكذا الذبح للأصنام وإلى الصور المنحوتة على صور بعض العظماء، أو للجن أو للكواكب أو للملائكة يتقرب إليهم كل هذا من الشرك الأكبر، وهكذا دعاؤهم والاستغاثة بهم والنذر لهم كل هذا من الشرك الأكبر، نعوذ بالله من ذلك، نعم. المقدم: جزاكم الله خيرًا، تسأل من أجل التصدق عن الميت، هل هذا جائز؟\nالشيخ: إذا ذبح للصدقة لا بأس، إذا ذبح ذبيحة، أو إنسان ذبح ذبيحة يتصدق بها عن أبيه أو عن أمه أو عن أخواته، يتقرب بها إلى الله، ويرجو ثوابها لهذا الميت لا بأس بذلك أو للحي كذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13017/ما-حكم-الذبح-بنية-التصدق-عن-النفس-والميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63401.mp3","categories":["إهداء القرب للميت"]},{"id":14577,"question":"هذا سائل يقول في هذا  سماحة الشيخ، لي والد متوفى -رحمه الله- وأريد أن أتصدق عنه، وأخص ذلك بالصدقة فأيهما أفضل وصول الصدقة أو الدعاء؟ وما هو الدعاء الوارد من الكتاب والسنة بالنسبة للدعاء للوالدين؟","title":"مشروعية الدعاء والصدقة عن الوالدين","answer":"الجواب: السنة للمؤمن أن يدعو لوالديه، وأن يترحم عليهما، ويستغفر لهما، ويتصدق عنهما، كما قال الله -جل وعلا-: وَقَضَى رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا إِمَّا يَبْلُغَنَّ عِنْدَكَ الْكِبَرَ أَحَدُهُمَا أَوْ كِلاهُمَا فَلا تَقُلْ لَهُمَا أُفٍّ وَلا تَنْهَرْهُمَا وَقُلْ لَهُمَا قَوْلًا كَرِيمًا ۝ وَاخْفِضْ لَهُمَا جَنَاحَ الذُّلِّ مِنَ الرَّحْمَةِ وَقُلْ رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا [الإسراء:23-24] كما دعا إبراهيم: رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ [إبراهيم:41] فهذا مشروع للمؤمن، وهكذا نوح دعا لمن دخل بيته وللمؤمنين والمؤمنات. المقصود: أن الدعاء مطلوب، فالمؤمن يدعو لوالديه، ويستغفر لهما، ويطلب لهما من الله الجنة والمغفرة، ويتصدق عنهما، ومن هذا قوله ﷺ لما سأله سائل، قال: «يا رسول الله، هل بقي من بر أبوي شيء أبرهما به؟ قال النبي ﷺ: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما يعني: وصية وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما وقال آخر: «يا رسول الله، من أبر؟ -في لفظ: من أحق بحسن صحبتي؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أمك قال: ثم من؟ قال: أبوك، ثم الأقرب فالأقرب وقال رجل: «يا رسول الله، إن أمي افتلتت نفسها، ولم توصي، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم وقال -عليه الصلاة والسلام-: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتقع به، أو ولد صالح يدعو له، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13074/مشروعية-الدعاء-والصدقة-عن-الوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55703.mp3","categories":["إهداء القرب للميت","الآداب والأخلاق المحمودة"]},{"id":14590,"question":"إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (س. ح. أ) بعثت برسالة تقول فيها: هذه أول رسالة أكتبها إليكم، بعد أن وجدت أن هذا البرنامج هو خير الدروب التي تضيء للمسلم، ونحن معشر المسلمين دائمًا ما نحتاج لمثل هذه الأشياء تنير لنا طريق الدين، وسنة الرسول ﷺ، وأنا من المداومين على الاستماع لهذا البرنامج، وعليه وبعد أن وجدت طريقًا يمكن للإنسان أن يسأل فلدي سؤال عسى أن أجد الرد عليه وهو:أنا متزوجة ولدي طفل، وكنت حاملًا وزوجي يعمل بالسعودية، وعندما حضر إلينا بالسودان، قد نزل بمنزل شقيقه لضيق منزلنا، وقد أحضر إلي أشياء خاصة، وعندما أراد أن يسلمني هذه الأشياء قام بقسمتها بيني وبين زوجة شقيقه بالنصف، لدي سؤال:هل يجوز شرعًا هذه القسمة؟ وأنا كزوجة في الشرع، أريد ردًا واضحًا بما أني قد تضررت من هذه القسمة، وأرى كأنها ضرتي، وفي الختام أرجو أن أجد الرد.والسلام عليكم ورحمة الله.","title":"حكم إعطاء الرجل زوجة أخيه عطية مثل زوجته","answer":"الجواب: لا حرج في هذه القسمة، الزوج له الحرية في أن يعطيك، ويعطي زوجة أخيه، وزوجة عمه وزوجة أبيه، وله أن يعطي أيضًا من يرى من قريباته، لا حرج عليه في ذلك، ولا يجوز لك أن تكرهي ذلك، أو تضرري من ذلك، أو يكون عليك مشقة من ذلك إذا أحسن إليك، وأعطاك ما يجب لك من الكسوة والنفقة، فلا حرج عليه، إذا وسع الله عليه، وأحسن إلى زوجة أخيه من باب الصلة، ومن باب البر بأخيه، والمجاملة لأخيه، كونه سكن عندهم أيضًا، هذا من مكارم الأخلاق، ومحاسن الأعمال أن يكرم زوجة أخيه وزوجة عمه وزوجة أبيه.  وكذلك من مكارم الأخلاق أن يحسن إلى جيرانه وأقاربه جميعًا من ذكور وإناث. فينبغي أن تعينيه على هذا الخير، وأن تكوني زوجة صالحة تعين على الخير، وتساعد على بر الوالدين، وعلى صلة الرحم، وعلى إكرام الجيران، إذا أعطاك حقك، فإذا أعطاك ما يجب من الكسوة اللائقة، والحاجات اللائقة، ثم وسع الله عليه، وأعطى زوجات إخوته، أو أعطى أخواته أو عماته أو خالاته، أو نساء جيرانه على وجه ليس فيه ريبة ولا فتنة، فلا بأس بذلك، والحمد لله، هذا كله عمل طيب مشكور، ينبغي لمثلك أن يساعده على هذا، ويشكره على هذا؛ لأنه من مكارم الأخلاق، ومحاسن الأعمال إذا أدى حقك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13087/حكم-اعطاء-الرجل-زوجة-اخيه-عطية-مثل-زوجته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_635/nour_63510.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":14715,"question":"المستمع عيسى عبد النبي عبدالرحمن، يسأل عن قراءة القرآن على الميت هل هي حلال؟ وهل الذبيحة التي يذبحها أهل الميت قبل طلوعه إلى الدفن يلحقه منها شيء؟أفيدونا، جزاكم الله خيرًا.","title":"حكم قراءة القرآن على الميت والذبح له","answer":"الجواب: لا أصل للقراءة على الموتى، ولا تشرع القراءة على الموتى، ولكن يدعى لهم بالمغفرة والرحمة بعد الموت، وفي جميع الأحوال، الموتى يدعى لهم بالمغفرة، وإذا كانوا مسلمين يدعى لهم بالمغفرة والرحمة عند الموت، وقبل الموت، وبعد الموت، دائمًا يدعى له بالمغفرة والرحمة والنجاة من النار، ومضاعفة الحسنات، وتكفير السيئات، والعفو عن الزلات، يدعى لهم.  أما قراءة القرآن على الموتى، أو على القبور، هذا لا أصل له في أصح قولي العلماء، بل هو من البدع التي لا أصل لها. كذلك الذبيحة عن الميت يوم الموت، أو اليوم الرابع، أو يوم الأربعين، أو يوم السابع، اعتقاد أن هذا مشروع لا أصل لهذا، أما إذا ذبح في أي وقت وتصدق على الفقراء أو تصدق بالدراهم أو بالطعام في أي وقت من غير قصد ولا تعيين يوم معين، ولا في يوم موت، ولا في غيره بل حسب التيسير هذا لا بأس به، الصدقة عن الموتى مطلوبة فيها خير كثير، أما أن يكون عن قصد وعن الذبيحة يوم الموت، أو في اليوم الرابع أو السابع أو العاشر أو على رأس السنة أن هذا مشروع، لا ليس لهذا أصل، ولكن يتصدق متى شاء بالمال من الطعام، بالنقود، بالملابس، بالذبيحة يذبحها ويقسمها على الفقراء، أو نحو ذلك كل هذا لا بأس به، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13206/حكم-قراءة-القران-على-الميت-والذبح-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63708.mp3","categories":["إهداء القرب للميت"]},{"id":14986,"question":"أيضاً تقول: هل يجوز إهداء تلاوة القرآن لأحد ميت أو لأحد حي؟ حيث أقول: اللهم اجعل هذه التلاوة لفلان؟","title":"ما حكم إهداء تلاوة القرآن للحي أو الميت؟","answer":"الجواب: أما إهداء القرآن وتثويبه لزيد أو عمرو، فهذا فيه خلاف بين العلماء، كثير من أهل العلم يقولون: لا بأس به أن يقرأ ويثوب لأبيه أو أمه أو زيد أو عمرو من أحياء أو أموات، كما يدعو له، يدعو لغيره، كما يتصدق عن غيره، وبعض أهل العلم قال: لا يشرع ذلك؛ لأن القرآن لم يرد عن الرسول ﷺ ولا عن أصحابه أنهم كانوا يهدونه لميت ولا لحي، هذا هو الأفضل والأولى عدم إهدائه لأحد، الإنسان يقرأ لنفسه، يتلو لنفسه، يطلب الأجر في قراءته، ولا يهدي ثوابه لأحد من الناس، وإذا أراد أن يهدي يتصدق عن أبيه عن أمه بما تيسر: بدراهم ملابس طعام، يدعو لهم، يدعو لوالديه لأقاربه لأحبابه، يدعو لهم بالمغفرة والرحمة، وإذا كانوا أحياء يدعو لهم بكل خير: بسعة الرزق، والتوفيق للعلم النافع والعمل الصالح وأشباه ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13486/ما-حكم-اهداء-تلاوة-القران-للحي-او-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_651/nour_65104.mp3","categories":["إهداء القرب للميت","القرآن وعلومه"]},{"id":15141,"question":"هذا السائل يقول -يا سماحة الشيخ- من السودان: هل يجوز لي أن أمنع الهبة كالنخيل التي وهبها جدي تقربًا للسيد أو الولي؟","title":"حكم منع الولد ما أوقفه والده للأضرحة","answer":"الجواب: إذا كان جدك أو أبوك وقف نخلات، أو بيت على ضريح فلان، يبنى منه عليه، أو ينفق منه على تطييب المحل، أو البناء عليه، أو تجصيصه، أو ما أشبه ذلك، فالوقف باطل، هذا الوقف باطل، وهو يكون للورثة، يكون وقفًا باطلًا، ويكون للورثة، ولا يعتمد؛ لقوله ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد فلا بد أن تكون الأوقاف على الوجه الشرعي، فالوقف الذي لا يوافق الشرع يكون باطلًا. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13637/حكم-منع-الولد-ما-اوقفه-والده-للاضرحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56410.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15251,"question":"هذا سؤال من المرسل محمد الهنيني، من عمان بالأردن، يقول: هل يجوز قراءة القرآن، وصوم النوافل والصدقة على الفقراء عن الميت؟ وهل إذا دعي للميت أثناء الصلاة جائز؟","title":"حكم القراءة والصوم والصدقة عن الميت","answer":"الجواب: أما الصدقة فنعم سنة، ثبت في الأحاديث الصحيحة عن النبي ﷺ أنه سئل عن ذلك، فقال للسائل: نعم وبيَّن أنها تنفع الميت الصدقة، وقد أجمع المسلمون على ذلك، أن الصدقة عن الميت تنفعه إذا كان مسلمًا تنفعه الصدقة من ولده ومن غير ولده، وهكذا الدعاء والاستغفار له ينفع الميت. أما قراءة القرآن للميت ففيها خلاف بعض أهل العلم، يرى أنها تصل، وبعض أهل العلم يرى أنها لا تصل؛ لأنها لم تنقل عن النبي ﷺ ولا عن الصحابة، فالأولى أنه لا يقرأ القرآن للميت هذا هو الأولى والأفضل والأحوط، بل يقرأ لنفسه، ويدعو لأمواته إذا ختم القرآن، أو في أثناء القراءة يدعو لأمواته بالمغفرة والرحمة.  أما أنه يقرأ لأجلهم يثوب الختم لهم، فالأفضل ترك ذلك؛ لعدم الدليل؛ لأن هذا لم يحفظ عن النبي ﷺ ولا عن أصحابه أنهم فعلوه. وذهب بعض أهل العلم إلى أنه لا بأس به مثل الصدقة، أنه لا بأس أن يقرأ القرآن، ثم يثوبه لأبيه أو لأمه، ونحو ذلك، ولكن الأفضل والأولى ترك ذلك. أما الصلوات فلا، الصيام لا، لا يصلي عنهم نافلة، ولا يصوم عنهم؛ لعدم الدليل، لم يرد عن النبي ﷺ ولا عن الصحابة ما يدل على أنه يصام عن فلان نافلة، أو يصلى عنه، فالذي ينبغي ترك ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/13764/حكم-القراءة-والصوم-والصدقة-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_670/nour_67006.mp3","categories":["إهداء القرب للميت"]},{"id":15258,"question":"هذه السائلة منيرة الرميح، بعثت بسؤال تقول: والدي توفي، وأريد أن أعرف ما هي الأعمال التي أعملها ليصل ثوابها إليه؟ وهل قراءة القرآن إذا كانت نيته للميت يذهب الأجر إليه، وكذلك العمرة؟أفيدونا، جزاكم الله خير الجزاء.","title":"الأعمال المشروعة التي تنفع الميت","answer":"الجواب: الميت في حاجة إلى الدعاء والصدقة، وأحسن ما يفعل مع الميت الدعاء، الدعاء له بظهر الغيب، الدعاء له، والترحم عليه، وسؤال الله سبحانه أن يغفر له، وأن يتغمده بالرحمة، وأن يعفو عنه، وأن يرفع درجاته في الجنة، ونحو هذا من الدعاء الطيب. والصدقة كذلك، الصدقة بالنقود بالطعام بالملابس بغير هذا من أنواع المال، كل هذا ينفع الميت، وهكذا الحج عنه، وهكذا العمرة عنه، كل هذا ينفع الميت، وإن كان عليه ديون وجب البدار بقضائها من ماله إن كان له مال، وإن كان ما له مال شرع لأوليائه من ذريته وقراباته أن يوفوا عنه، فالوفاء عنه من أعظم الصدقات عليه، كل هذا مطلوب. أما القراءة فلا، لم يأت ما يدل على شرعية ذلك، وقد ذهب بعض أهل العلم إلى أن القراءة تنفع الميت، ولكن ليس عليه دليل، فالأولى ترك ذلك؛ لأنه ليس هناك دليل عن النبي ﷺ ولا عن أصحابه في أن القراءة تصل إلى الميت، وأنه يقرأ له، ويثوب له، هذا ليس عليه دليل واضح، فالأولى والأفضل والأحوط ترك ذلك. ولكن يدعى للميت، يستغفر له، يترحم عليه، يتصدق عنه بالمال بأنواع المال، يحج عنه، يعتمر عنه، يوفى عنه الدين كل هذا شيء ينفع الميت، ويأجر الله هذا وهذا الميت ينتفع والفاعل من الأحياء يؤجر على ذلك أيضًا. وقد صح عن رسول الله -عليه الصلاة والسلام- أنه قال: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. وثبت عن النبي ﷺ أيضًا أن رجلًا سأله قال: إن أمي ماتت فهل لها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم فالصدقة عن الميت تنفعه بإجماع المسلمين، وهكذا الدعاء له بإجماع المسلمين ينفعه، والله المستعان، نعم. المقدم: والصلاة والصيام؟ الشيخ: الصلاة ما هي بمشروعة، لا يصلى على الميت، لم يشرع هذا، وهكذا القراءة، أما الصيام فإذا كان عليه صوم يصام عنه.\nالمقدم: صوم الواجب.\nالشيخ: من مات وعليه صيام بأن فرط عليه صيام، ولم يصم يصام عنه، يصوم عنه أولياؤه، كما قال النبي ﷺ: من مات وعليه صيام صام عنه وليه فيصوم عنه ولده الذكر أو الأنثى أو زوجته أو غيرهما من قراباته، هذا طيب وينفع الميت. قد سأل جماعة النبي ﷺ عن أنواع من الصوم، فأجابهم النبي ﷺ بقوله: أرأيتم لو كان على فلان دين أكنت قاضيه؟ اقضوا الله، فالله أحق بالوفا فشبهه بالدين، سواء كان صوم رمضان أو كفارة أو نذر كله يصام عنه على الصحيح، ولو كان صوم رمضان ولو كان صوم الكفارة، وقال بعض أهل العلم: إنما يصام عنه النذر خاصة، ولكن هذا قول ضعيف، والأحاديث الصحيحة تدل على خلافه، الأحاديث الصحيحة دالة على أنه يصام عنه حتى رمضان؛ ولهذا قالت عائشة -رضي الله عنها- عن النبي ﷺ أنه قال: من مات وعليه صيام، صام عنه وليه أخرجه الشيخان في الصحيحين. وفي الصحيح عن عدة من الصحابة أنهم سألوا النبي ﷺ من مات وعليه صوم شهر؟ بعضهم قال: صوم شهرين، أنصوم عنه؟ فقال النبي ﷺ: صوموا عنه وشبهه بالدين، ولم يستفصل هل هو رمضان؟ هل هو كفارة؟ هل هو نذر؟ فدل ذلك على أن الأمر عام يعم الكفارة، ويعم النذر، ويعم رمضان. وفي مسند أحمد بإسناد جيد عن ابن عباس -رضي الله عنهما- أن امرأة قالت: يا رسول الله، إن أمي ماتت وعليها صوم رمضان أفصوم عنها؟ قال: صومي عن أمك، أرأيت لو كان عليها دين أكنت قاضيته؟ اقضوا الله، فالله أحق بالوفاء وهذا صريح في رمضان، وإسناده قوي جيد. أما إذا كان الميت ما فرط، بأن مات في مرضه، فهذا لا صوم عليه عند عامة أهل العلم، عند جمهور أهل العلم، لا يقضى عن صوم، ولا يطعم عنه؛ لأنه غير مفرط معذور؛ لأن الله قال: وَمَنْ كَانَ مَرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ [البقرة:185] فالذي توفي في مرضه، ما أدرك أيامًا أخر، معذور، ليس عليه صيام، وليس عليه إطعام، يعني: ليس على ورثته إطعام ولا صيام، نعم. المقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13768/الاعمال-المشروعة-التي-تنفع-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_674/nour_67406.mp3","categories":["إهداء القرب للميت"]},{"id":15286,"question":"سؤالها الآخر تقول: والدي من ذوي الأموال والعقارات، وله أولاد ذكور ومن الإناث، أنا وأختي، ولكنه لا يعدل بيننا في الهبات؛ فهو يعطي الأولاد أموالًا نقدًا وعقارات بدون مقابل، ولكي يتخلص من مطالبتنا يسجل عقود بيع بينهم صورية، وإذا طالبنا يهددنا بإعطائهم ما تبقى وحرماننا من كل شيء. علمًا أنه يصلي ويصوم ويقرأ القرآن، وإذا قلنا له: هذا حرام عليك يستهزئ بنا ويسخر منا، وحتى أختي الثانية تسبب في طلاقها من زوجها منذ ثلاثين سنة، ورفض تزويجها مرة أخرى حتى بلغ عمرها الآن خمسين سنة، ومع ذلك لا ينفق عليها، بل إخوتي مرة يعطفون عليها ويعطونها، ومرة أخرى يطردونها بسبب تأثير والدي عليهم، فقد زرع الكراهية في نفوسهم نحونا، إضافة إلى ما جرت عليه العادة عندنا من عدم تزويج الفتاة إلا من ابن عمها مهما كان، فما رأيكم في هذا؟ وبماذا تنصحون والدنا هذا؟","title":"حكم من لا يعدل بين أولاده في العطايا ويعضل بناته","answer":"الجواب: أولاً: الواجب على الرجل أن يتقي الله في أولاده، وأن يعدل بينهم في العطية، وليس له الجور والحيف، بل يجب أن يعدل بينهم في العطية، فيعطي الرجل ضعف المرأة كالميراث، هذا هو الصواب؛ لقول النبي ﷺ: اتقوا الله واعدلوا بين أولادكم ولما جاءه بشير بن سعد الأنصاري  وقد أعطى ابنه النعمان غلامًا قال له النبي -عليه الصلاة والسلام-: أكل ولدك أعطيته مثل هذا؟ قال: لا، قال: اتقوا الله واعدلوا بين أولادكم وقال لما أشهده: إني لا أشهد على جور فهذا يدل على أن التفضيل بين الأولاد، أو إعطاء بعضهم، وترك البعض جور وظلم، وهذا هو الصواب من أقوال أهل العلم كما دل عليه الحديث الشريف. فالواجب على أبيك تقوى الله، وأن يعدل في أولاده، وإذا لم يعدل وجب على الحاكم الشرعي أن يلزمه بالعدل، وأن ينقض العطايا التي فيها الحيف والجور، وإذا كانت بصور بيع لا حقيقة له يبطل هذه البيوع الباطلة إذا ثبت لدى الحاكم أنها حيلة، فالبيع الذي يكون بالحيلة باطل وجور وظلم، والله سبحانه أوجب على الآباء والأمهات العدل في أولادهم وألا يجوروا، وأن يحرصوا على أن يكونوا في البر لهم سواء. وكذلك ليس للوالد أن يمنع بناته الزواج، بل عليه أن يساعد في الزواج، ولا يجوز له أن يجبرها على ابن عمها، بل إذا جاء الكفء من بني عمها أو غيرهم وجب على الولي التزويج، سواء كان الولي أبًا أو غير أب، هذا هو الواجب، وقد جاء في الحديث: إذا خطب إليكم من ترضون دينه وأمانته فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير والله -جل وعلا- قال: فََلا تَعْضُلُوهُنَّ[البقرة:232] نهى الأولياء عن العضل، فإذا عضل الوالد زالت ولايته، وساغ للقاضي أن يولي غيره من بقية العصبة الأقرب فالأقرب. فالمقصود: أن والدك إذا كان عمله ما ذكرت فقد أساء وعصى ربه، فعليه التوبة إلى الله، وعليه أن يعدل بين أولاده، وعليه أن يرد العقود الباطلة التي تحيل بها وسماها بيعًا، وليست ببيع، وإنما هي عطايا، وعلى الحاكم الشرعي إذا علم هذا بالبينة أن يبطل العقود، وأن يرد العطايا الجائرة، وأن يلزمه بالتسوية بين أولاده. كما أن على القاضي أن يلزمه بتزويج البنت التي يخطبها الكفء، يلزم القاضي أن يلزمه بالزواج، أو يعزله عن هذا الأمر، ويحكم عليه بالعضل، ويسمح للأقرب من العصبة بعد الوالد بالتزويج، هذا هو الواجب على الأولياء وعلى حكام الشرع في علاج، هذه المسائل، نسأل الله للجميع الهداية، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13785/حكم-من-لا-يعدل-بين-اولاده-في-العطايا-ويعضل-بناته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_681/nour_68103.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15305,"question":"له سؤالان في رسالته، يقول: هل يجوز لي أن أصلي لوالدي في صلاتي ركعة زيادة في كل فرض، وأحج له وهو متوفى؟","title":"حكم زيادة ركعة في الصلاة وإهداء ثوابها للميت","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد شرع الله -جل وعلا- للعباد البر بوالديهم، والإحسان إليهم بالصدقات، والدعاء وسائر أنواع الخير التي تنفع الوالدين أحياءً وأمواتًا.  لكن الصلاة للوالدين غير مشروعة، ولم يأت بها نص، فلا يصل الولد لوالده، ولكن يدعو له ويتصدق عنه، يحج عنه إذا كان ميتًا، أو عاجزًا لا يستطيع الحج لكبر سنه أو مرضه الذي لا يرجى برؤه، ونحو ذلك. أما كونه يصلي عنه هذا غير مشروع، ولكن يدعو له، ويتصدق عنه، ويحج عنه إذا كان ميتًا أو عاجزًا، وهكذا سائر أنواع الخير التي تنفعه من الضحية عنه، والاعتمار عنه، والإحسان إلى أصدقائه وأقاربه، ونحو ذلك من وجوه الخير، نعم. المقدم: المستمع يقول: يصلي عنه زيادة في كل فرض ركعة.\nالشيخ: لا هذا غير مشروع.\nالمقدم: هذا يؤثر على صحة الصلاة؟ الشيخ: ما يجوز، إذا زاد ركعة في الصلاة أبطلها، إذا صلى الظهر مثلًا خمسًا، الخامسة لأبيه أو لأمه هذا باطل، هذا غلط وبدعة منكر، أو إذا صلاها مستقلة لا يجوز أيضًا، حتى لو صلاها مستقلة لا يجوز ذلك؛ لأن الله سبحانه لم يشرع لنا أن نصلي عن آبائنا، ولا عن أمهاتنا، فهذا منكر، وقد سئل النبي ﷺ سأله رجل قال: «يا رسول الله، هل بقي من بر أبوي شيء أبرهما به بعد وفاتهما؟ قال النبي ﷺ: نعم؛ الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما هكذا بيَّن النبي ﷺ.\nفالصلاة عليهما يدخل فيها الدعاء، وصلاة الجنازة، صلاة الجنازة والدعاء له؛ لأن الدعاء يسمى صلاة، قال الله تعالى: وَصَلِّ عَلَيْهِمْ[التوبة:103] أي: ادع لهم، والصلاة على الوالدين الدعاء لهما بالمغفرة والرحمة والنجاة من النار، والدعاء لهم في حياتهم بمضاعفة الأجر، وقبول الحسنات، والعافية والصحة، ونحو ذلك. والاستغفار لهما: طلب المغفرة لهما، وإنفاذ عهدهما من بعدهما: إنفاذ وصاياهم إذا أوصوا بشيء لا يخالف الشرع، فالولد ينفذ الوصية وصية والده؛ لأن الله -جل وعلا- شرع له ذلك، وهذا من إعانته على الخير، فإذا أوصى والده بشيء مما يحبه الله كالصدقة وبناء المساجد والضحية عنه وأشباه ذلك فإن الولد ينفذ ذلك. أما لو أوصى بشيء لا يشرع، فالولد لا ينفذ، لو أوصى أبوه أنه يبني على القبر مسجدًا، أو يبني عليه قبة، هذه بدعة منكر لا يقبل هذه الوصية، ولا ينفذها؛ لأنها مخالفة للشرع، كذلك لو أوصاه والده أن يقطع أرحامه، وألا يكلم عمه، وألا يصل إخوانه هذه وصية باطلة قطيعة للرحم لا ينفذها، ولكن ينفذ الوصايا الشرعية مثل أوصى بأنه يتصدق عنه، يعمر عنه مسجدًا على وجه الشرع، يضحي عنه، يحج عنه لا بأس. فالمقصود: أنه ينفذ عهد أبيه وأمه إذا كان ذلك شيئًا شرعيًا، أما إذا كان ذلك يخالف الشرع فلا، وهكذا إكرام صديق والديه يكرمهم، ويحسن إليهم، قد جاء في الحديث عن النبي ﷺ أنه قال: إن من أبر البر أن يصل الرجل أهل ود أبيه هذا من أبر البر، كونه يصل أحباب أبيه وأولياء أبيه وأقاربه، وكذلك صلة الرحم التي لا توصل إلا بهما، مثل الإحسان إلى أعمامه وإلى جده أبي أبيه وإلى أخواله أخوة أمه، وأخوال جداته، ونحو ذلك، هذا كله من الصلة للوالدين، صلته أقارب والديه صلة لهما، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13808/حكم-زيادة-ركعة-في-الصلاة-واهداء-ثوابها-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_682/nour_68201.mp3","categories":["إهداء القرب للميت"]},{"id":15317,"question":"هذه رسالة من المستمع (ع. ع. س. الغامدي) يقول: كان والدي -رحمه الله- قد أوقف أرضًا زراعية بجانبها بئر، على أن يصرف ريع هذه الأرض في استمرار دلو على البئر بمعنى لغرض سقاية المارة الذين كانوا في السابق يمرون بهذه الأرض مشيًا على أقدامهم، أو ركوبًا على دوابهم من الحيوانات، فأوقف الأرض لهذا الغرض، والآن لم يعد هناك من يمر بهذه الأرض من المشاة، حتى يستفيدوا من السقي من هذه البئر بواسطة الدلو الموقوفة الأرض لأجل استمرار بقائه، وأيضًا الأرض تركت من الزراعة؛ لذا فليس لها ريع الآن.فأرشدونا إلى العمل الأفضل لنا فعله تجاه هذا الوقف.","title":"كيفية التصرف في الوقف الذي لم يعد يستفاد منه","answer":"الجواب: ينبغي في مثل هذا التشاور مع قاضي البلد في بيع الوقف هذا، وصرف ثمنه في وقف أنفع للمسلمين في بلد تنتفع بهذا الوقف في البركة ماء ينتفع بها الناس، أو في إيجاد حوض، بركة من الماء لسقي مواشيهم، أو ما أشبه ذلك مما يحل محل الدلو الأولى.  يتشاور صاحب الوقف هذا مع فضيلة القاضي فيما تنقل إليه هذه الأرض، تباع ويصرف ثمنها فيما يناسب ويجانس ما أراده الواقف السابق، فإن لم يتيسر شيء من ذلك صرف ثمنها فيما ينفع المسلمين من تعمير المساجد التي هي في حاجة إلى التعمير، أو ما أشبه ذلك مما يراه القاضي نافعًا للمسلمين، ومن جملة المصالح العامة، نعم.\nالمقدم: يعني: لو أنفق نقدًا مثلًا سلم إلى أحد من المحتاجين أو وزع؟\nالشيخ: لا، إذا ينصرف في مثله يكون أحسن، إذا تيسر صرفه في بركة تنفع المسلمين في بعض القرى، أو صرفه في إيجاد بئر تسقي بعض المارة، أو تسقي بعض الفقراء في بعض القرى المحتاجة، أو بعض البادية إذا وجد شيء من هذا، فهو أفضل، حتى يجانس ما أراده الواقف، فإن ما تيسر صرف فيما هو أنفع وأبقى مثل المساجد وأشباهه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13819/كيفية-التصرف-في-الوقف-الذي-لم-يعد-يستفاد-منه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_676/nour_67606.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15482,"question":"السائلة في آخر أسئلتها تقول: سماحة الشيخ، جزاكم الله عنا وعن جميع المسلمين خير الجزاء، هل تعتبر الهدية رشوة في هذه الحالة، حيث بأنها قامت بعمل خير، وهو تدريس بنت الجيران، وقالت: إذا نجحت فلك هدية، وقلت لها: لا أريد هدية؛ لأنني أعمل هذا لله، ولكنها أصرت عليها، فما حكم أخذ هذه الهدية سماحة الشيخ؟","title":"ما حكم قبول الهدية على عمل الخير؟","answer":"الجواب: ما دمت قصدت وجه الله في عدم أخذ الهدية فالأحوط لك أن لا تأخذي شيئًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14008/ما-حكم-قبول-الهدية-على-عمل-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56903.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15510,"question":"هذه رسالة من السائل أبو إهاب مصري، يعمل بالكويت، بعث بعدة أسئلة في سؤاله الأول يقول: أنجب والدي ستة أولاد وبنتًا واحدة، ولقد جاهد -رحمه الله- حتى أتم تعليمنا إلا واحدًا من إخوتي شاء الله أن لا ينال حظه من التعليم مثلنا، وذلك لرغبة من الوالدة في أن يظل مع والده يعمل معه في فلاحة الأرض، حيث أننا من أبناء الريف، وقبل وفاة الوالد طلبت أنا من والدي أن يخص أخي المذكور بقدر معين من الأرض التي يملكها عوضًا له عن جهده طوال سنوات عدة، ولكونه لم ينل حظه من التعليم مثلنا، والحقيقة أنه -رحمه الله- رفض ذلك مرارًا، ولكنه أمام إلحاحي وإلحاح الوالدة وبعض الإخوة وافق على أن يحرر لأخي عقد بيع وشراء صوري لقطعة محددة من الأرض، ولكن دون أن يقبض منه أي ثمن، بل أخذ عليه صكًا بمبلغ سبعمائة جنيه، فما مدى صحة هذا العقد الذي تم بين الوالد وبين أخي؟علمًا بأن العقد موجود عندي بصفة أمانة لحين إتمام الإجراءات، وهل الصك الذي أخذه والدي على أخي يدخل ضمن تركته ويطالب به أخي أم لا؟","title":"حكم الأرض التي باعها الأب لأحد أبنائه قبل موته","answer":"الجواب: إذا كان الواقع ما ذكره السائل فالصك المذكور لا عبرة به؛ لأنه كذب وحيلة؛ فلا وجه له، لكن إذا سمح إخوته الورثة جميعًا بهذه القطعة لهذا الأخ للسببين المذكورين؛ لكونه ساعد أباه، ولكونه لم يتعلم، فلا بأس إذا سمحوا له بهذه القطعة، أو سمح بعضهم، فمن سمح منهم سقط حقه من هذه القطعة، ومن لم يسمح فهو على حقه، أما هذا العقد المزور فلا قيمة له، ولا يلتفت إليه، نعم.\nالمقدم: إنما تعتبر كهبة يعني من الورثة.\nالشيخ: إذا سمحوا بها.\nالمقدم: إذا سمحوا بها صحيحة. الشيخ: ومن لم يسمح فهو على حق.","link":"https://binbaz.org.sa/fatwas/14067/حكم-الارض-التي-باعها-الاب-لاحد-ابناىه-قبل-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_703/nour_70303.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":15679,"question":"من المنطقة الشرقية إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (س. ع) أختنا تسأل عدة أسئلة من بينها سؤال يقول: أريد أن أقسم تمرًا على من نعرفهم، ومن لا نعرفهم، فهي صدقة عن ميت، وهذا الميت ليس لنا به صلة قرابة، فهل هذا جائز، أم لا؟","title":"حكم التصدق عن الميت الذي لا يعرف","answer":"الجواب: المسلم أخو المسلم، يقول النبي ﷺ: من استطاع منكم أن ينفع أخاه فليفعل والمسلم أخو المسلم ينفعه بالصدقة، وينفعه بالدعاء، فإذا تصدق عن أخيه بالنقود، أو بطعام، أو بملابس؛ فله أجره عند الله ، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14226/حكم-التصدق-عن-الميت-الذي-لا-يعرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70610.mp3","categories":["إهداء القرب للميت"]},{"id":15685,"question":"من جمهورية السودان المستمع: ياسر محمد، بعث يسأل ويقول: هل الصدقة والحوليات التي يعملها أهل الميت تصل إليه؟ وهذه الفاتحة هل تصل أيضًا أم يعتبر كل ذلك خرافة؟","title":"الأمور التي تنفع الميت بعد موته","answer":"الجواب: نعم الصدقات والضحايا وسائر القربات التي شرعها الله تنفع الميت، وتصل إليه تنفعه، كما قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. وفي الصحيحين أن رجلًا قال: «يا رسول الله، إن أمي ماتت، ولم توص، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم.\nوسأله جماعة عن أمهاتهم وآبائهم ماتوا وعليهم حج أفيحجون عنهم؟ قال: نعم، حج عن أبيك وقال للأخرى: حجي عن أمك إلى غير ذلك. فالصدقات عن الموتى، والحج عنهم، والعمرة عنهم، كل هذا ينفعهم، ويصل إليهم، وهكذا الاستغفار لهم، والدعاء، وقضاء ديونهم، وقضاء ما عليهم من الصيام الذي ماتوا، وعليهم صيام نذر، أو صيام كفارة، أو صوم رمضان، تساهلوا ولم يصوموه بعدما عافاهم الله من المرض إن كانوا مرضى هذا يصام عنهم وينفعهم.\nأما من مات في مرضه فلا يصام عنه؛ لأنه معذور. أما البدع التي يبتدعها الناس فلا، ابتداع أشياء ما شرعها الله هذه لا تنفع، بل تضر، تضر من ابتدعها ما تضر الميت، بل تضرهم هم، من ابتدع الاحتفال بالموالد، أو الاحتفال بأشياء ما أنزل الله بها من سلطان؛ لأجل الموتى، وحوليات ما شرعها الله للاحتفال في مثل ليلة سبعة وعشرين من رجب، أو ليلة النصف من شعبان، أو ليالٍ أخرى يبتدعونها يجعلون فيها احتفالات بأشياء يفعلونها للموتى هذه ما تنفع، هذه تضر من فعلها، من البدع المنكرة، والرسول  قال: من عمل عملًا ليس عليه أمرنا فهو رد. وإنما الذي ينفع الموتى الصدقة عنهم، والدعاء لهم، والاستغفار، والحج عنهم، والصوم عنهم، إذا كانوا عليهم صوم، والدعاء لهم، كل هذا ينفع الميت، نعم، والضحية عنهم أيضًا صدقة، الضحية عن الميت صدقة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14237/الامور-التي-تنفع-الميت-بعد-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_572/57206.mp3","categories":["إهداء القرب للميت"]},{"id":15929,"question":"هذا السائل من السودان محمد الحسين أحمد، يقول: إلى سماحة الشيخ عبد العزيز: هل يصل ثواب قراءة القرآن إلى الميت؟","title":"هل يصل ثواب قراءة القرآن للميت؟","answer":"الجواب: ليس له أصل هذا، لكن الدعاء، أما قراءته على الموتى ليس له أصل، ولا يشرع، يقرأ الإنسان يريد الثواب لنفسه، وأما الموتى يدعو لهم بالمغفرة والرحمة، يتصدق عنهم، يحج عنهم يعتمر؛ هذا يلحقهم ينفعهم، أما قراءة القرآن أو الصلاة هذا ليس له أصل، لا يصلى على الأموات، ولا يقرأ لهم القرآن لعدم الدليل، والعبادات توقيفية، يقول النبي ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد ولم يثبت عنه ﷺ ولا عن الصحابة أنهم كانوا يقرؤون للموتى، نعم.\nالمقدم: أحسن الله إليكم، وما أفضل شيء يصل إلى الميت يا شيخ؟\nالجواب: الدعاء والصدقة، الدعاء له، والصدقة عنه، هذا ينفعه الله به كثيرًا، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14526/هل-يصل-ثواب-قراءة-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57719.mp3","categories":["إهداء القرب للميت","القرآن وعلومه"]},{"id":15939,"question":"هذا السائل عبدالله عبدالعزيز من الأردن يقول: سماحة الشيخ، السلام عليكم ورحمة الله وبركاته، والدي ووالدتي ماتوا منذ زمن طويل، وأنا كل يوم أقرأ من القرآن الكريم ما يتيسر، وفي النهاية أقرأ الفاتحة، وأقول: اللهم ابعث ثواب ما قرأت إلى روح والدي ووالدتي، فهل يجوز لي ذلك؟","title":"حكم إهداء ثواب القرآن للميت","answer":"الجواب: هذا غير مشروع، ولم يرد في السنة تثويب القراءة غير مشروع، لكن تصدق عنهم، وادع لهم، حج عنهم عنهما، أو اعتمر عنهما، أما تثويب القراءة، أو تثويب لصيام، أو تثويب صلاة؛ فهذا ليس له أصل في الشرع، فالواجب ترك ذلك، ولكن يشرع لك -يا أخي- أن تجتهد في الدعاء لهما، والترحم عليهما، والاستغفار لهما، والصدقة عنهما، والحج عنهما أو العمرة، كل هذا طيب.\nنسأل الله لك التوفيق.\nالمقدم: ثواب الأعمال يصل إلى الميت يا سماحة الشيخ؟\nالشيخ: أعمال الحي التي جاء بها النص كالصدقات ينفع الميت، الدعاء والاستغفار ينفعه كذلك، الحج عنه والعمرة كذلك ينفعه، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14544/حكم-اهداء-ثواب-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57807.mp3","categories":["إهداء القرب للميت","القرآن وعلومه"]},{"id":15943,"question":"يقول أخيرًا هذا السائل من الأردن: أنا في كل جمعة وبعد صلاة الفريضة أقول: نويت أن أصلي ركعتين طاعة لله  ولرسوله، وتبعث اللهم أجر هذه الصلاة إلى أرواح والدي ووالدتي.","title":"حكم التلفظ بالنية في الصلاة وإهداء ثوابها للموتى","answer":"الجواب: هذا غير مشروع، والتلفظ بالنية بدعة، لا يجوز التلفظ بالنية، النية محلها القلب، تنوي بقلبك الصلاة صلاة نافلة، أو فريضة أو صوم بالنية لا تتلفظ بها، ولا تثوب بالقراءة، أو الصلاة لوالديك ولا غيرهم، ولكن تدعو لوالديك، تستغفر لهم، تترحم عليهم، تتصدق عنهم، كل هذا طيب، تحج أو تعتمر، كل هذا طيب؛ إذا كانا ميتين، أو كانا عاجزين -كبيري السن عاجزين عن الحج والعمرة- لا بأس بالحج عنهما أو العمرة لعجزهما أو لموتهما، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14548/حكم-التلفظ-بالنية-في-الصلاة-واهداء-ثوابها-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_578/57808.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":16044,"question":"يقول: عندما يمر على الميت أربعين يومًا، يقوم أهله بالصدقة عنه، فهل هذا مشروع؟","title":"حكم الصدقة عن الميت بعد مضي أربعين يومًا","answer":"الجواب: ليس لهذا أصل، الصدقة عن الميت بعد أربعين يومًا، أو بعد شهر، أو أقل، أو أكثر ليس له أصل، ولكن يتصدق عن الميت متى شاء، تيسر ما له حد محدود، فالصدقة عن الميت تنفع الميت إذا تصدق عنه أهله، أو غير أهله نفعه ذلك، أما أن يحدد ذلك بأربعين يومًا، أو بشهر، أو بعشرة أيام، هذا لا أصل له، ليس له حد محدود. وثبت في الصحيح عن النبي ﷺ أن رجلًا قال: يا رسول الله! إن أمي ماتت، ولم توص، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم وفي الحديث الصحيح أيضًا يقول ﷺ: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. فالصدقة عن الميت، والدعاء له، والاستغفار كل ذلك ينفعه، كما تنفعه الصلاة عليه، والحج عنه، والعمرة عنه، قضاء دينه، كل هذا ينفعه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14674/حكم-الصدقة-عن-الميت-بعد-مضي-اربعين-يوما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71102.mp3","categories":["إهداء القرب للميت"]},{"id":16080,"question":"يسأل سماحتكم فيقول: هل يجوز لي أن أعتمر، وأن أتصدق عن ذلكم المتوفى، أرجو توضيح المسألة، وإجابتي؟ جزاكم الله خيرًا.","title":"جواز العمرة والصدقة عن المتوفى","answer":"الجواب: نعم مشكور ومأجور إذا اعتمرت عنه، أو تصدقت عنه أنت مشكور ومأجور؛ لأن هذا من باب الإحسان إلى أخيك، تنفعه العمرة، تنفعه الصدقة، ينفعه الدعاء، فأحسن إليه -جزاك الله خيرًا- وأبشر بالخير، وإذا كنت لم تعتمر في عمرك؛ ابدأ بنفسك، فاعتمر، ثم اعتمر عنه. وإذا كنت قد اعتمرت فيما مضى عن نفسك؛ فالحمد لله تعتمر على أخيك الميت، وإذا تصدقت عنه بما يسر الله من النقود، أو الطعام، أو غير ذلك؛ فكله طيب، وهكذا إذا دعوت له بالمغفرة، والرحمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14714/جواز-العمرة-والصدقة-عن-المتوفى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71105.mp3","categories":["إهداء القرب للميت"]},{"id":16271,"question":"لها سؤال قريب في معناه من الأول تقول: إذا أهدى لي شخص طعامًا، سواءً كان ذلك الشخص جارًا، أو قريبًا، أو صديقًا، وهو لا يصلي، ولا يصوم، ويشرب الخمر، هل يجوز قبول هديته؟","title":"حكم قبول هدية من لا يصلي ويجاهر بالمعاصي","answer":"الجواب: هذا فيه تفصيل: إن كان قبولها يرجى فيه خير، وأن الله يهديه، ويقبل من المهدى إليه النصيحة، ويتأثر؛ فلا مانع من قبولها، لكن إذا كان فيها لحم لا، لا تأكل اللحم إذا كان لا يصلي، إلا إذا كانت فاكهة شيء ما يحتاج ذبحًا، فاكهة، أو شبه فاكهة، لا بأس.  أما إذا كان لا، معاند، ولا يرجى فيه خير، لا تقبل هديته، اهجره، ولا تقبل هديته، لعل الله يهديه، لا تقبل هديته، ولا تقبل دعوته، ولا تزوره، بل يستحق الهجر؛ لتركه الصلاة، وإعلانه الخمر، والمعاصي الظاهرة، فهذا يستحق الهجر؛ لعله يتوب، فيتوب الله عليه. أما إذا كان في قبول هديته مصلحة شرعية، أو في زيارته مصلحة شرعية للدعوة إلى الله، وتوجيهه إلى الخير، وإنكار المنكر عليه؛ لعل الله يهديه بأسبابك، فهذا لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14978/حكم-قبول-هدية-من-لا-يصلي-ويجاهر-بالمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80907.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16285,"question":"لها سؤال قريب في معناه من الأول تقول: إذا أهدى لي شخص طعامًا، سواءً كان ذلك الشخص جارًا، أو قريبًا، أو صديقًا، وهو لا يصلي، ولا يصوم، ويشرب الخمر، هل يجوز قبول هديته؟","title":"حكم قبول هدية من لا يصلي ويجاهر بالمعاصي","answer":"الجواب: هذا فيه تفصيل: إن كان قبولها يرجى فيه خير، وأن الله يهديه، ويقبل من المهدى إليه النصيحة، ويتأثر؛ فلا مانع من قبولها، لكن إذا كان فيها لحم لا، لا تأكل اللحم إذا كان لا يصلي، إلا إذا كانت فاكهة شيء ما يحتاج ذبحًا، فاكهة، أو شبه فاكهة، لا بأس.  أما إذا كان لا، معاند، ولا يرجى فيه خير، لا تقبل هديته، اهجره، ولا تقبل هديته، لعل الله يهديه، لا تقبل هديته، ولا تقبل دعوته، ولا تزوره، بل يستحق الهجر؛ لتركه الصلاة، وإعلانه الخمر، والمعاصي الظاهرة، فهذا يستحق الهجر؛ لعله يتوب، فيتوب الله عليه. أما إذا كان في قبول هديته مصلحة شرعية، أو في زيارته مصلحة شرعية للدعوة إلى الله، وتوجيهه إلى الخير، وإنكار المنكر عليه؛ لعل الله يهديه بأسبابك، فهذا لا بأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14978/حكم-قبول-هدية-من-لا-يصلي-ويجاهر-بالمعاصي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80907.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16324,"question":"يقول: إذا كان والدي متوفيًا، وأريد أن أتصدق له بصدقة جارية، هل ثوابها يكون له، أم لي؟","title":"حصول الأجر للميت ولمن أهدى ثواب الصدقة","answer":"الجواب: إذا تصدقت عنه بصدقة جارية يكون لك أنت وإياه، له أجر ولك أجر، إذا تصدقت عنه بمال دفعته عنه، أو ببيت وقفته له، أو بدكان، أو بنخل، أو بأرض تصرف غلتها في مصالح المسلمين، أو في الفقراء، أو في عمارة المساجد، أو في تعليم القرآن، كل هذا طيب، له أجر ذلك، وأنت لك أجر في هذا الوقف، والله سبحانه فضله واسع، فضله واسع، يعطيك أجرًا عظيمًا، ويعطي والدك، والصدقة تصل الوالد، يقول النبي ﷺ: إذا مات ابن آدم؛ انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. وسئل -عليه الصلاة والسلام- عن رجل، سأله رجل قال: يا رسول الله! إن أمي ماتت، ولم توص، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم فأنت يا أخي! تصدق عن والديك، وعن أقاربك المسلمين، وأبشر بالخير، ولك أجر في الوقف، وغيره، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15026/حصول-الاجر-للميت-ولمن-اهدى-ثواب-الصدقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_810/nour_81020.mp3","categories":["إهداء القرب للميت"]},{"id":16340,"question":"عندنا وعند سنة الوليمة في الزواج يكون هناك دفتر يسجل عليه أسماء الذين يدفعون نقودًا للعريس، وعندما تكون هناك وليمة عند أحد الذين دفعوا للعريس، يخرج العريس الأول الدفتر ليرى كم دفع له من قبل هذا العريس الثاني، ثم يدفع هو زيادة على ما دفعه له الأول، فهل هذا شيء مباح؟الشيخ: أعد.المقدم: يقول: عندنا وفي بلدنا -ويسمي بلده سماحة الشيخ- وعند سنة الوليمة في الزواج يكون هناك دفتر يسجل عليه أسماء الذين يدفعون نقودًا للعريس، وعندما تكون هناك وليمة عند أحد الذين دفعوا للعريس يخرج العريس الأول الدفتر ليرى كم دفع له هذا العريس، ثم يدفع هو زيادة على ما دفعه له الأول، فهل في هذا شيء من الحرمة، وهل هو نوع من الربا؟ جزاكم الله خيرًا.","title":"ما حكم دفع مبالغ للعريس كمساعدة؟","answer":"الجواب: لا حرج في ذلك إذا كانت عادة عندكم لا حرج، الحمد لله؛ لأنه من باب المساعدة، والتعاون على الخير، وهذه عادة بين الناس مواساة للعريس بالمال، وبغير المال من الأشياء الأخرى، كل هذا تختلف فيه عادات الناس، هذا يدفع دراهم، وهذا يدفع أشياء أخرى. فالمقصود: أن هذه العادات لا حرج فيها في التعاون على الخير على البر والتقوى، ولا بأس إن شاء الله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15034/ما-حكم-دفع-مبالغ-للعريس-كمساعدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_714/nour_71403.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":16370,"question":"رسالة وصلت إلى البرنامج من المستمع سعد محمد من بقيق، الأخ سعد يقول: هل يجوز قراءة القرآن للميت؟ وهل يجوز للإنسان أن يصلي للميت؟ أم الصدقة والدعاء والحج تكفي ذلك؟ أرشدونا جزاكم الله خيرًا.","title":"حكم قراءة القرآن والصلاة وغيرهما عن الميت","answer":"الجواب: نعم، نعم ليس في الأدلة الشرعية ما يدل على شرعية القراءة عن الميت، أو الصلاة عن الميت، وإنما المشروع عن الميت، الصدقة عنه، والدعاء له، والحج عنه، والعمرة، هذا هو الوارد في الأحاديث، أما كونه يقرأ عنه، ويثوب له، أو يصلي عنه؛ هذا لا أعلم له دليلًا شرعيًا، ولو قاله بعض أهل العلم، لكن ليس عليه دليل فيما أعلم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15070/حكم-قراءة-القران-والصلاة-وغيرهما-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75404.mp3","categories":["إهداء القرب للميت"]},{"id":16393,"question":"من المستمع عبد الكريم حبيب رسالة عرضنا جزءًا من أسئلتها في حلقات مضت، وفي هذه الحلقة يسأل ويقول: ما هو الشيء الذي إذا فعله الإنسان الحي يصل ثوابه إلى الميت، وجهونا جزاكم الله خيرًا.","title":"الأعمال التي تنفع الميت","answer":"الجواب: الدعاء للميت، والصدقة عن الميت، والصلاة عليه؛ صلاة الجنازة، والحج عنه، والعمرة عنه، وقضاء دينه إذا كان عليه دين؛ كل هذا ينفعه حيًّا وميتًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15099/الاعمال-التي-تنفع-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_754/nour_75418.mp3","categories":["إهداء القرب للميت"]},{"id":16424,"question":"هذا السائل المستمع فضل الله سوداني ومقيم في ليبيا، من أسئلته يا فضيلة الشيخ يقول: هل يجوز للميت أن نقرأ عليه القرآن الكريم؟ هل هذا مكروه أم يجوز؟","title":"هل يجوز أن نقرأ القرآن على الميت؟","answer":"الجواب: الميت لا يقرأ عليه... ما يستفيد الميت من القراءة عليه، إنما يقرأ عند المحتضر سورة يس، لا بأس بذلك عند جمع من أهل العلم قبل أن يموت، أما الميت ما يقرأ عليه شيئًا، انتهى إلى الله سبحانه، ما ينتفع بهذا، يدعى له بالمغفرة والرحمة إذا كان مسلمًا، نعم.","link":"https://binbaz.org.sa/fatwas/15117/هل-يجوز-ان-نقرا-القران-على-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58125.mp3","categories":["إهداء القرب للميت"]},{"id":16585,"question":"من أحد الإخوة المستمعين رسالة، ورمز إلى اسمه بالحروف (م. ر. ل) من المملكة، له جمع من الأسئلة في أحدها يقول: بعض الناس يذبحون في رمضان، ويقولون: اللهم اجعلها لموتانا، ما حكم ذلك؟","title":"ما حكم الذبح في رمضان وإهداء الثواب للموتى؟","answer":"الجواب: لا حرج في ذلك، إذا تصدقوا لموتاهم، ذبحوا ذبيحة، أو أكثر، وقسموها على الفقراء في رمضان، في هذا الشهر الكريم، أو في غير رمضان، وزعوها على الفقراء، أو على أقاربهم؛ لا بأس بذلك، صدقة، الحمد لله، نعم. أو وزعوا فواكه، أو وزعوا أطعمة أخرى، أو ملابسَ، كله طيب، أو نقودًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15340/ما-حكم-الذبح-في-رمضان-واهداء-الثواب-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75810.mp3","categories":["إهداء القرب للميت"]},{"id":16594,"question":"يقول: ما هي الأساليب التي من الممكن أن يقدم الإنسان الحي للإنسان الميت الفائدة؟ وهل ختم القرآن يجوز كهدية للميت، وهل الصدقة تجوز عنه أيضًا؟","title":"ما يصل نفعه من الحي إلى الميت؟","answer":"الجواب: الميت ينتفع بالصدقة عنه، والدعاء له، والحج عنه، والعمرة، كل هذه تنفعه، وقضاء دينه إن كان عليه دين كل هذا ينفع الميت، أما إهداء القرآن فلا دليل عليه، وليس بمشروع إهداء القرآن يعني: كونه يقرأ من أجل يهدي ثوابه له، هذا ما هو بمشروع على الصحيح، أما الصدقة عنه هذا ينفعه بإجماع المسلمين، وهكذا الدعاء له بالمغفرة، والرحمة، ورفيع الدرجات، والعفو عن السيئات ينفعه بإجماع المسلمين، هكذا إذا حج عنه، أو اعتمر عنه ينفعه، هكذا إذا أدى دينه إن كان عليه دين، كل هذا ينفع الميت، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15336/ما-يصل-نفعه-من-الحي-الى-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_817/nour_81716.mp3","categories":["إهداء القرب للميت"]},{"id":16613,"question":"المستمع فايح منور المطيري بعث برسالة يسأل سؤالًا قريبًا من السؤال السابق فيقول: هل يجوز ذبح الحسنة للميت في عشوة رمضان، إذ أن هناك أناس يقولون: إن هذا العمل بدعة؟","title":"حكم الذبح في رمضان وإهداء ثواب ذلك للميت","answer":"الجواب: لا حرج في ذلك، إذا ذبح شاة، أو غيرها في رمضان، ويوزع على الفقراء، أو على أقاربه، أو جيرانه في هذا الشهر الكريم، هذا من باب تحري مضاعفة الأجر، فإن الصدقة في رمضان مضاعفة، وإذا ذبحها في غير رمضان، وتصدق بها أيضًا كذلك لا بأس بذلك، الصدقة على الميت ما هي ببدعة، سنة، في رمضان، وفي غيره، باللحم، أو بالفاكهة، أو بالنقود، أو بالملابس؛ كله طيب. المقدم: الحمد لله. الشيخ: نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15348/حكم-الذبح-في-رمضان-واهداء-ثواب-ذلك-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_758/nour_75818.mp3","categories":["إهداء القرب للميت"]},{"id":16638,"question":"سماحة الشيخ، إذا زرع شخص زرعًا، ونوى ثوابه للميت إذا أكل منه شخص، أو بهيمة، أو طير، فهل يصل ثواب ذلك إليه؟","title":"حكم من تصدق عن الميت بزرع أو ثمر","answer":"الجواب: هذا من الصدقة عنه، ينتفع به الميت، هذا من الصدقة، الزرع، والنخل، والثمار إذا تصدق بها عن الميت، ونواها للميت ينتفع بها الميت. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15371/حكم-من-تصدق-عن-الميت-بزرع-او-ثمر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71701.mp3","categories":["إهداء القرب للميت"]},{"id":16655,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلينا من أحد الإخوة المستمعين، آثر فيها عدم ذكر اسمه، أخونا عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة له جمع آخر من الأسئلة، فيسأل سماحتكم شيخ عبدالعزيز، ويقول: هل صحيح أن ثواب العمرة، أو الحجة تصل إلى الميت، وترفع درجاته في الجنة؟ جزاكم الله خيرًا.","title":"الحج والعمرة عن الميت","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فإن الحج عن الميت والعمرة عن الميت من أفضل القربات، وينتفع بها الميت المسلم كثيرًا، فقد سئل النبي ﷺ عن ذلك مرات كثيرة، فقال للسائل: حج عن أبيك وللسائلة: حجي عن أبيك والآخر: عن أمك وسأله آخر قال: إني لبيت عن شبرمة قال: من شبرمة؟ قال: أخ لي، أو قريب لي، قال: حج عن نفسك، ثم حج عن شبرمة. فالناس أقسام، منهم من قد حج الفريضة، وأدى العمرة الفريضة، هذا إذا حج عنه؛ يكون نافلة، وإذا اعتمر عنه؛ يكون نافلة، حج عنه أخوه، أو أبوه، أو قريب له، أو أخ من إخوانه في الله، كل ذلك طيب، وهكذا العمرة. وإذا كان ما أدى الحج، ولا أدى العمرة؛ فإن الذي يحج عنه يكون قد أدى عنه الفريضة، وهكذا العمرة يكون قد أدى عنه عمرة الفريضة، وهو على كل حال مأجور، والميت مأجور، كلاهما مأجور، هذا عن عمله الطيب، وإحسانه إلى أخيه مأجور، والميت مأجور بذلك، وهكذا الصدقة، وهكذا الدعاء إذا تصدق عن أخيه؛ يؤجر هو والميت جميعًا، وهكذا إذا دعا لأخيه الميت؛ يؤجر هو، وينتفع الميت بالدعاء، نعم. المقدم: جزاكم الله خيرًا، إذًا الأعمال الصالحة تنفع الميت وترفع درجاته في الجنة كما يقول؟ الشيخ: الأعمال الصالحة التي شرع الله فعلها عن الميت، من حج، أو عمرة، أو قضاء دين، أو دعاء، أو صدقة عنه، نعم. المقدم: جزاكم الله خيرًا، إذًا هناك أعمال لا يصح أن يعملها الإنسان؟ الشيخ: عن الميت مثل الصلاة عنه ..... الصلاة عنه، أو القراءة عنه، لم يرد في الشرع ما يدل على شرعيتها، أو الصيام عنه تطوعًا، نعم. المقدم: جزاكم الله خيرًا، الواقع يا سماحة الشيخ أن الناس يخلطون بين هذا وذاك، لعلها مناسبة أن تتفضلوا بتوجيه المسلمين في ... الشيخ: الذي ثبت عندنا بالشرع أن الميت ينتفع بالحج عنه، وبالعمرة عنه، وبالصدقة عنه، وبالدعاء، والاستغفار له، وبقضاء دينه، وهكذا إذا كان عليه صوم فريضة من رمضان، أو كفارة، أو نذر يصام عنه.  أما كونه يصام عنه تطوعًا، أو يصلى عنه، أو يطاف عنه، فليس عليه دليل فيما نعلم، وهكذا كونه يقرأ عنه القرآن، ليس عليه دليل، وإن كان بعض العلماء يرى ذلك، وأنه ينتفع بقراءة القرآن عنه، لكن ليس عليه دليل، والقربات بابها التوقيف، يقول النبي ﷺ: من عمل عملًا ليس عليه أمرنا؛ فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد. ولا نعلم في الشريعة ما يدل على أنه يشرع للمؤمن أن يصلي عن فلان، أو يصوم عن فلان تطوعًا، أو يقرأ عنه، أو يطوف عنه، أو يذكر الله عنه، إنما الثابت يكون الحج تامًا، يحج عنه حجًا تامًا، أو عمرة تامة، أو يتصدق عنه بالمال، أو يدعو له، ويستغفر له، أو يقضي دينه، كل هذا ثابت، نعم. المقدم: بارك الله فيكم، وأحسن إليكم. سماحة الشيخ أيضًا لعله من المهم أن تتفضلوا ببيان ما هو توقيفي، وغير توقيفي حتى لا يخلط الناس بين هذين الأمرين؟  الشيخ: التوقيفي العبادات ما يتعلق بالقربات، والطاعات، لا يشرع منها إلا ما جاء به الشرع، وأما من غير التوقيفي فهو ما يتعلق بأمور الدنيا، والمعاملات، فهذه لا بأس بها، يتعامل الناس فيما ينفعهم بشرط ألا يخالف الشرع. المقدم: جزاكم الله خيرًا، وأحسن إليكم. المقدم: ننتقل إلى قضية أخرى؟ الشيخ: نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/15388/الحج-والعمرة-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71718.mp3","categories":["إهداء القرب للميت"]},{"id":16856,"question":"هل تجوز قراءة القرآن، وكذلك صيام يوم عرفة، ويوم عاشوراء، وتثويبها للميت؟ وجهونا جزاكم الله خيرًا.","title":"حكم تثويب قراءة القرآن وصيام التطوع للميت","answer":"الجواب:  لا يصام عن الميت تطوعًا، ولا يقرأ عنه، ما ورد في السنة ما يدل على هذا، ليس في السنة ما يدل على تثويب القرآن، أو الصيام، أو الصلوات فيما نعلم، أما إذا كان عليه دين صيام؛ يقضى عنه، يقول النبي ﷺ: من مات وعليه صيام؛ صام عنه وليه فالصلاة عنه، أو القراءة عنه هذا غير مشروع فيما نعلم، وإنما يشرع الصدقة عنه، الدعاء له، الحج عنه، العمرة، هذا هو المشروع، قضاء دينه، إذا كان عليه صيام، أو دين؛ يقضى عنه أيضًا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15596/حكم-تثويب-قراءة-القران-وصيام-التطوع-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_719/nour_71905.mp3","categories":["إهداء القرب للميت"]},{"id":16939,"question":"جزاكم الله خيرًا سماحة الشيخ، يقول السائل في ثاني أسئلته: والدي متوفى منذ أربع سنوات، ولكنه لم يحج، ولم يوص بالحج عنه؛ وذلك لأنه مات موتًا مفاجئًا، فما واجبنا، هل نحج عنه؟ علمًا بأنه لم يوصينا بذلك، وهل يجوز أن نقرأ له القرآن، وندفع مالًا على ذلك؟","title":"حكم الحج عن الميت وقراءة القرآن له","answer":"الجواب: إذا كان لم يحج، وخلف تركة؛ وجب أن يحج عنه من التركة إذا كان يستطيع الحج في حياته، ولكن تساهل وجب أن يخرج من ماله ما يحج به عنه، وإن حج عنه بعض أولاده كفى، أما إذا كان فقيرًا، مات ما يستطيع الحج، فإن أولاده إذا حجوا عنه مأجورون، لهم أجر إذا حج عنه بعض أولاده، أو إن حجت عنه زوجته، أو بعض أقاربه مأجورون، أما إذا كان لا، يستطيع الحج، عنده قدرة ولكن تساهل؛ فإنه يجب أن يخرج من ماله حجة، يعطاها الثقة حتى يحج بها عنه، وإن حج عنه بعض أولاده الطيبين كفى. المقدم: وبالنسبة لقراءة القرآن يقول يا سماحة الشيخ؟ الجواب: أما أن يقرأ على الميت، يقرأ القرآن على الميت هذا لا دليل عليه، ولا يشرع، ولكن يدعى له، أما قراءة القرآن للموتى هذا لا دليل عليه، ولا يشرع، لكن السنة أن يدعى للميت، يستغفر له، يترحم عليه، يتصدق عنه، يحج عنه، يعتمر عنه، كل هذا طيب.  أما أن يقرأ قرآنًا يثوبه له، هذا لا دليل عليه، أو يقرأ عند قبره هذا كله منكر، لكن إذا قرأ له في البيت، أو في المسجد ينويه له هذا لا دليل عليه، تركه أولى، ولكن يدعو له، يستغفر له، يترحم عليه، يتصدق عنه، يحج عنه، أو يعتمر عنه، نعم.","link":"https://binbaz.org.sa/fatwas/15713/حكم-الحج-عن-الميت-وقراءة-القران-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_586/58612.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":16982,"question":"هل تجوز قراءة القرآن على الميت؟","title":"هل تجوز قراءة القرآن على الميت؟","answer":"الجواب: لم يشرع هذا، الميت ينقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له كما قاله النبي ﷺ فقراءة القرآن عليه لا تنفعه، ولا يستفيد منها؛ لأنه لا يسمعها، ولا يستفيد منها بعد الموت، نعم.","link":"https://binbaz.org.sa/fatwas/15773/هل-تجوز-قراءة-القران-على-الميت ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82904.mp3","categories":["إهداء القرب للميت"]},{"id":16997,"question":"هل تجوز قراءة القرآن على الميت؟","title":"هل تجوز قراءة القرآن على الميت؟","answer":"الجواب: لم يشرع هذا، الميت ينقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له كما قاله النبي ﷺ فقراءة القرآن عليه لا تنفعه، ولا يستفيد منها؛ لأنه لا يسمعها، ولا يستفيد منها بعد الموت، نعم.","link":"https://binbaz.org.sa/fatwas/15773/هل-تجوز-قراءة-القران-على-الميت ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82904.mp3","categories":["إهداء القرب للميت"]},{"id":17009,"question":"بعد هذا رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين آثر فيها عدم ذكر اسمه، له أسئلة كثيرة من بينها سؤال يقول: الدعاء أفضل شيء للميت، فهل يصل إليه ثواب التسبيح، والأذكار، وقراءة القرآن الكريم، والصلاة، وصيام التطوع، وتقديم الصدقة من ثياب، وطعام، ونحوها، مع علمنا بأن ثواب هذه الأعمال يكون للميت، وليس لفاعلها نصيب في ثوابها؟ حيث أن ذلك قد ورد في إحدى حلقات نور على الدرب، ولكن فاعلها يكررها له أيضًا مثل قراءة سورة الإخلاص عشر مرات، وينوي ثوابها للميت، ثم يقرؤها عشر مرات أخرى لنفسه علمًا بأن الميت في السنة الثالثة عشرة وشهرين منذ أن توفي، جزاكم الله خيرًا، وما الحكم إذا كان المتوفى لم يبلغ؟ جزاكم الله خيرًا.","title":"الأعمال التي يصل ثوابها إلى الميت","answer":"الجواب: الصدقة عن الميت تنفع الميت بالملابس، أو بالنقود، أو بالطعام بإجماع المسلمين، وهكذا الدعاء للميت بالمغفرة، والرحمة، ورفيع المنازل، والنجاة من النار ينفع الميت، سواء كان الميت بالغًا، أو دون البلوغ، فالدعاء، والصدقات كلها تنفع الميت، الميت ينتفع بالصدقات، بالدعاء، وإن كان صغيرًا لم يبلغ، وهكذا الحج عنه، والعمرة. أما القراءة.. قراءة القرآن للميت، أو التسبيح، أو التهليل فهذا لا نعرف فيه حجة، وليس عليه دليل أنه يلحق الميت، فالأفضل، والأحوط ترك ذلك، وقد زعم بعض أهل العلم أنه يلحق الميت، ولكن ليس عليه دليل فيما نعلم، كونه يقرأ للميت، أو يسبح، ويهلل له، أو يصوم له تطوعًا، ليس عليه دليل فيما أعلم. وإنما المعروف من الأدلة الشرعية الدعاء له، الصدقة عنه، كل هذا يلحق الميت، ينفع الميت، الحج عنه، العمرة عنه، قضاء دينه، هذا ينفعه، الصوم عنه إذا كان عليه صوم، مات وعليه صوم رمضان، أو صوم نذر، أو كفارة يصام عنه، هذا ينفعه لقوله ﷺ: من مات وعليه صيام؛ صام عنه وليه. وسئل -عليه الصلاة والسلام- عن من مات وعليه صوم، فأمر السائل أن يصوم عن من مات، وعليه صوم نذر، صوم رمضان، صوم كفارة، أما أن يصوم تطوعًا، أو يصلي تطوعًا فليس عليه دليل فيما نعلم، إنما الدليل فيما إذا كان عليه صوم واجب، هذا يستحب الصيام عنه، فإن لم يتيسر الصيام أطعم عنه عن كل يوم مسكينًا، طعام نصف صاع إذا لم يتيسر الصوم عنه، إذا أفطر من رمضان من أجل السفر، أو المرأة من ..... الحيض، والنفاس، ثم تساهلت، وماتت قبل أن تقضي، أو مات الرجل بعد السفر قبل أن يقضي فإنه يشرع الصيام عنه لأقاربه، أو غيرهم، فإن لم يصم عنه أحد؛ أطعم عنه من التركة عن كل يوم مسكينًا، نصف صاع عن كل يوم، نعم. المقدم: جزاكم الله خيرًا. يسأل سماحتكم عن المكلف، وغير المكلف في ........ الشيخ: لا حرج .... مثلما تقدم عن المكلف، وغير المكلف، لا بأس إذا تصدق عن المكلف، أو غير المكلف أو دعا له، أو حج عنه، أو اعتمر ينفعه ذلك.. والفاعل له أجر؛ الميت له أجر، والفاعل له أجر. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15785/الاعمال-التي-يصل-ثوابها-الى-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_720/nour_72008.mp3","categories":["إهداء القرب للميت"]},{"id":17052,"question":"أحمد سالم له هذا السؤال، يقول: سماحة الشيخ! عندنا أراضي زراعية وقف لمسجد صغير وقديم، فهل يجوز لنا أن نبيع بعض هذه الأوقاف لمصلحة إنشاء مسجد كبير، ومتسع للقرية؟ علمًا بأن أصحاب الوقف أموات، وهذه المزارع الموقوفة لا يستفيد المسجد القديم من وقفها بشيء؛ لأنها بأيدي أشخاص لا يؤدون حقها.","title":"حكم بيع أراضي الوقف وبناء مسجد بثمنها","answer":"الجواب:  عليكم مراجعة المحكمة، هذه المسائل من خصائص المحاكم، فعليكم أن تراجعوا المحكمة في هذا الأمر العظيم، وفيما تراه المحكمة الكفاية، إن شاء الله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15841/حكم-بيع-اراضي-الوقف-وبناء-مسجد-بثمنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58727.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17068,"question":"يقول السائل: هل يلزم أهل الميت العيد له -أي: ذبح الأضحية- في عيد الأضحى له؟","title":"حكم التضحية عن الميت","answer":"الجواب: لا يلزمهم، لكن إذا ضحوا فهم مأجورون، من باب التطوع، كالصدقة عنه، وإلا فلا يلزمهم، إلا إذا أوصى بذلك، أوصى في بيت، أو مزرعة عليهم أن ينفذوا الوصية في الثلث فأقل. أما إذا كان ما أوصى فلا يلزمهم، لكن إذا تطوعوا ضحوا عنه، أو تصدقوا عنه فلهم أجر، لقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقةٍ جارية، أو علمٍ ينتفع به، أو ولدٍ صالح يدعو له «وسأله رجل قال: يا رسول الله! إن أمي ماتت، أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم. هذا يدل على أنه إذا تصدق عن أمه، أو أبيه، أو فلان، أو فلان له أجر. نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/15873/حكم-التضحية-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_588/58808.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":17088,"question":"يسأل عن حكم قراءة الفاتحة على أرواح الموتى؟","title":"حكم قراءة الفاتحة على أرواح الموتى","answer":"الجواب: ليس له أصل، ليس لهذا أصل.... استحبه بعض العلماء، ولكن الصحيح أنه لا يستحب، لا يستحب قراءة الفاتحة، ولا غيرها للأموات، ولا غيرهم، لم يرد عن النبي ﷺ ما يدل على شرعية قراءة القرآن يثوب للموتى، أو غيرهم، ولكن تقرؤه لتستفيد.. لتعمل به، لتعرف معناه، وتعمل به، لا لتثوبه لغيرك، ولكن تقرؤه للعمل للعلم والفائدة. وأما قراءته للثواب يعني حتى تثوبه إلى غيرك من الأموات، أو غيره هذا لا دليل عليه، والمشروع تركه، ولكن تقرؤه لتعمل به، وتعرف معناه، وليحصل لك الثواب من الله على القراءة والعمل.","link":"https://binbaz.org.sa/fatwas/15953/حكم-قراءة-الفاتحة-على-ارواح-الموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83116.mp3","categories":["إهداء القرب للميت"]},{"id":17114,"question":"أيهما أفضل: الإثابة على الهدية عندما تعطى لي، أم إنفاق المال على الوالدين والأقربين؟ علمًا بأنني لا أستطيع الجمع بينهما؟","title":"استحباب الإثابة على الهدية","answer":"الجواب: كان النبي ﷺ إذا أهدي إليه هدية يقبلها، ويثيب عليها من جاء له هدية، وصاحبها يمكن أن يقبل الثواب يثاب، يعني: يعطى مقابل. أما إذا كان لا، ما يريد الثواب فلا حرج، إذا كان إنما هي صدقة لأجل فقره، أعطاه إياه لأجل فقره، أو أعطاه إياه من الزكاة هذا ما يحتاج أن يثاب، أما الهدية العادية التي للتحبب فالأفضل أن يقابل، ويعطى مقابل هديته، كان الرسول ﷺ يقبل الهدية ويثيب عليها، اللهم صل عليه. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15921/استحباب-الاثابة-على-الهدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58911.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17164,"question":"ما أفضل شيء يصل إلى الميت بعد وفاته سماحة الشيخ؟","title":"أفضل ما يصل الميت من أجور","answer":"الجواب: الدعاء له، السنة الدعاء له، والصدقة عنه، كل هذا ينفع الميت، فالسنة لأقاربه وغيرهم الدعاء له بالمغفرة، والرحمة، والصدقة عنه، والحج عنه، والعمرة لا بأس، كله طيب، «قيل: يا رسول الله! هل بقي من بر أبوي شيء أبرهما به؟ قال: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وإكرام صديقهما، وصلة الرحم التي لا توصل إلا بهما وقال رجل: «يا رسول الله! إن أمي ماتت، فهل لها أجر إن تصدقت عنها؟ قال النبيﷺ: نعم ويقول ﷺ إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقةٍ جارية، أو علمٍ ينتفع به، أو ولد صالح يدعو له قال تعالى: وَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ [الحشر:10]الآية، وشرعت الجنازة على الميت لهذا؛ يدعى له بعد موته، يترحم عليه في صلاة الجنازة. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15983/افضل-ما-يصل-الميت-من-اجور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59002.mp3","categories":["إهداء القرب للميت"]},{"id":17363,"question":"هذا سائل للبرنامج يقول في هذا  هل يجوز لي يا سماحة الشيخ الاستغفار لشخص من أحد أقاربي مات، وأنا لا أدري أهو مات على حسن الخاتمة، أم لا؟ علمًا بأنه كان يجلل، أو يقدس الأولياء، وأصحاب القبور، والأضرحة، ويعتقد بأن هذا من الدين، وجهوني في سؤالي.","title":"حكم الاستغفار لمن كان يعظم أصحاب القبور","answer":"الجواب: إذا كان ظاهره الشرك، والغلو في الأموات، ودعاء الأموات، والاستغاثة بالأموات لا، لا يدعى له، ولكن إذا كان ظاهره الإسلام، ولا تعلم عنه إلا الإسلام؛ فلا بأس تدعو له، وتستغفر لأخيك، هذا مشروع، المؤمن يدعو لإخوانه، ويستغفر لهم، كما قال أتباع المهاجرين والأنصار بإحسان: رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ [الحشر:10]، فأنت تستغفر لإخوانك، تدعو لهم بالرحمة إذا كان ظاهره الإسلام. أما من كان ظاهره الشرك -وهو الغلو في القبور ودعاء الأموات والاستغاثة بالأموات- فهذا لا يدعى له؛ لأن دعاء الأموات، والاستغاثة بالأموات، وطلب الحوائج منهم هذا من الشرك الأكبر، هذا دين المشركين، نسأل الله العافية. وهكذا دعاء الجن .. دعاء الأصنام .. دعاء الكواكب، كل هذا من الشرك الأكبر، يقول الله -جل وعلا-: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113]. ولما مات أبو طالب على دين قومه قال النبي ﷺ: لأستغفرن لك ما لم أُنْهَ عنك فأنزل الله في ذلك هذه الآية: مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُوْلِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ [التوبة:113] من مات على الشرك فهو من أصحاب الجحيم. فالمقصود: أن من كان معروفًا بدعاء الأموات، والاستغاثة بأهل القبور أو بالأصنام أو بالجن أو بالكواكب، أو بالملائكة، أو بالأنبياء، هذا كله شرك أكبر داخل في قوله -جل وعلا-: إِنَّ اللَّهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ [النساء:48] وداخل في قوله سبحانه: إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ [لقمان:13] وداخل في قوله سبحانه: إِنَّهُ مَنْ يُشْرِكْ بِاللَّهِ فَقَدْ حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ وَمَأْوَاهُ النَّارُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ [المائدة:72] وفي قوله سبحانه: وَلَوْ أَشْرَكُوا لَحَبِطَ عَنْهُمْ مَا كَانُوا يَعْمَلُونَ [الأنعام:88] وقال سبحانه: وَلَقَدْ أُوحِيَ إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ لَئِنْ أَشْرَكْتَ لَيَحْبَطَنَّ عَمَلُكَ وَلَتَكُونَنَّ مِنَ الْخَاسِرِينَ ۝ بَلِ اللَّهَ فَاعْبُدْ وَكُنْ مِنَ الشَّاكِرِينَ [الزمر:66]، وقال سبحانه: وَمَنْ يَدْعُ مَعَ اللَّهِ إِلَهًا آخَرَ لا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِنْدَ رَبِّهِ إِنَّهُ لا يُفْلِحُ الْكَافِرُونَ [المؤمنون:117] وقال -جل وعلا-: ذَلِكُمُ اللَّهُ رَبُّكُمْ لَهُ الْمُلْكُ وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ[فاطر:13].  القطمير: اللفافة التي على النواة وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ مَا يَمْلِكُونَ مِنْ قِطْمِيرٍ ۝ إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا لَكُمْ وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] هذا يعم الجميع، يعم الغائبين، ويعم الموتى من الأنبياء، وغيرهم إِنْ تَدْعُوهُمْ لا يَسْمَعُوا دُعَاءَكُمْ وَلَوْ سَمِعُوا مَا اسْتَجَابُوا [فاطر:14] ولو قدرنا أنهم سمعوا لم يستجيبوا وَيَوْمَ الْقِيَامَةِ يَكْفُرُونَ بِشِرْكِكُمْ [فاطر:14] يعني: ينكرون ويتبرؤون إلى الله يقول سبحانه: تَبَرَّأْنَا إِلَيْكَ مَا كَانُوا إِيَّانَا يَعْبُدُونَ [القصص:63] نعم، نسأل الله العافية. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16208/حكم-الاستغفار-لمن-كان-يعظم-اصحاب-القبور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77004.mp3","categories":["إهداء القرب للميت","نواقض الإسلام","البدع والمحدثات"]},{"id":17498,"question":"يقول: في ليلة العيد والجمعة يؤتى بطعامٍ من كل بيت في المسجد، أو في وسط القرية، يأكلونه، وبعد ذلك يقرأ الإمام من آيات القرآن الكريم، ويختم بالدعاء بطلب الرحمة والمغفرة للأموات، اعتقادًا منهم أن بركة الطعام تصل إلى الأموات، وهذه الوليمة تسمى: الفاتحة، أو الفواتح، والأسئلة حول هذا الموضوع: هل هذه الفاتحة تنفع الميت، وهل تسمى صدقة عندما يأكلها الغني؟ ثم ما هو العمل الذي يجب على أهل الميت القيام به نحو فقيدهم، والذي يصل إليه العمل الصالح؟ جزاكم الله خيرًا.","title":"ما يصل إلى الميت وما لا يصل من القُرَب","answer":"الجواب: هذا الاجتماع على الميت المذكور لا أعلم له أصلًا في الشرع، بل هو من البدع، والرسول عليه السلام يقول: من عمل عملًا ليس عليه أمرنا، فهو رد ويقول ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد. أما الدعاء للأموات، والصدقة عنهم، هذا ينفعهم، الصدقة تنفع الميت، والدعاء ينفع الميت، صلاة الجنازة، الحج عن الميت، والعمرة عن الميت، قضاء دينه، كل هذا ينفع الميت.\nأما القراءة ... قراءة الفاتحة وغير الفاتحة فهذا ليس عليه دليل، وقد ذكر ابن القيم رحمه الله وغيره عن بعض العلماء؛ أنه لا بأس بالقراءة للميت، أنه يقرأ له يثوب له القرآن، ذكر هذا جماعةٌ من أهل العلم، ذكره ابن القيم في كتاب الروح، ولكن لا أعلم عليه دليلًا، تثويب القراءة كونه يقرأ ويثوبه للميت، لا أعلم عليه دليلًا، فتركه أحوط، وأولى، ولكن الدعاء ليس فيه خلاف، الدعاء للميت، الترحم عليه، الدعاء له بالمغفرة، هذا أمر معلوم، متفق عليه بين المسلمين، أنه ينفع الميت، وهكذا الصدقة عنه تنفع الميت. ثبت عن النبي ﷺ أنه سأله رجلٌ، وقال: يا رسول الله! إن أمي ماتت، وأظنها لو تكلمت تصدقت، فهل لها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم. فالصدقة تنفع الميت، والدعاء له، وصلاة الجنازة تنفعه، دعاء المسلمين له ينفعه، الحج عنه، العمرة، قضاء الدين، كل هذا أمر معروف.\nأما كونه يقرأ ويثوب له، هذا هو محل النزاع، ولا أعلم دليلًا شرعيًا على استحباب ذلك، وشرعيته، والأصل في العبادة التوقيف، هذا هو الأصل، إلا ما شرعه الله على لسان رسوله عليه الصلاة والسلام، فالأحوط في هذا ترك القراءة للميت، ولكن يدعى له، يترحم عليه، يتصدق عنه، يحج عنه، يعتمر عنه، كل هذا طيب، كله نافع. نعم.\nالمقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/16405/ما-يصل-الى-الميت-وما-لا-يصل-من-القرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_726/nour_72602.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":17558,"question":"هذا سائل من سوريا فهمت الحقيقة من رسالته الطويلة وأسلوبه بحكم الشرع في نظركم فضيلة الشيخ في الأب الذي يفرق بين أولاده في الأعطية؟","title":"الواجب العدل بين الأبناء في العطية","answer":"الجواب: لا يجوز، الواجب على الآباء العدل؛ لأنه ثبت عن النبي ﷺ أنه قال: اتقوا الله واعدلوا بين أولادكم، فلا يجوز للأب ولا للأم التفضيل بين الأولاد بل يجب التسوية للذكر مثل حظ الأنثيين، هذا هو الواجب على الرجل والمرأة في أولادهم، لكن لو كانوا مرشدين، وسمحوا أن يخص واحد منهم بشيء فلا بأس إذا كانوا مرشدين وسمحوا لأبيهم أو لأمهم أن تخص أحدًا منهم بشيء لأسباب اقتضت ذلك فلا بأس، أما أن يخص أحد دون أحد، أو يفضل أحد على أحد؛ فلا يجوز إلا بإذن المرشدين. نعم.\nالمقدم: شكر الله لكم يا سماحة الشيخ وبارك الله فيكم وفي علمكم ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/16487/الواجب-العدل-بين-الابناء-في-العطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77523.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17670,"question":"من أسئلة السائلة هيلة المرشد من القصيم تقول: يا سماحة الشيخ حفظكم الله، هل تكفر الذنوب بالهدايا والأعطيات للفقراء والمحتاجين وذوي القرابة والأصدقاء؟","title":"هل الهدايا والأعطيات تكفر الذنوب؟","answer":"الجواب: الصدقات تطفئ الخطيئـة كما قال ﷺ: الصدقة تطفئ الخطيئة كما يطفئ الماء النار الصدقات ثوابها عظيم وأجرها كبير، وهي من أسباب تكفير الخطايا وحط السيئات.\nأما الهدايا فيها تفصيل، الهدايا إذا أهداها لقريبه لصلة الرحم هذه من أسباب تكفير السيئات، صلة الرحم عمل صالح، أما إذا أهداها لشيء آخر؛ لمجاملة أو لطلب مكافأة، هذا لم يقصد بها عملًا صالح.\nأما إذا أهداها لقريبه أو لأرحامه أو لفقير تسمى صدقة، وللقريب تسمى صلة، صلة رحم يؤجر عليها. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16601/هل-الهدايا-والاعطيات-تكفر-الذنوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59434.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":17838,"question":"يقول السائل محمد عيد في سؤاله الثاني سماحة الشيخ: نريد أن نتعرف هل الصدقة تصل المتوفى على حساب النية؟ مثل: أن نذبح شاة على سبيل المثال ونعزم الجيران والأقارب فيأكلون منها، فهل هذه الصدقة تصل إلى المتوفى؟","title":"هل الصدقة تصل إلى الميت؟","answer":"الجواب: نعم، الصدقة تصل إلى المتوفى سواء كانت الصدقة بالنقود، أو بالطعام، أو بالملابس، أو بالأوقاف أو غير ذلك، فإذا صنع وليمة، ودعا إليها الفقراء، أو أكرم بها أقاربه، وأرحامه، وجيرانه يقصد ثواب ذلك لوالده، أو أخيه، أو أمه أو نحو ذلك حصل له بذلك الخير العظيم، قد أجمع العلماء على أن الصدقة تصل إلى الميت، ثوابها يصل إلى الميت، وجاء في هذا أحاديث كثيرة عن النبي ﷺ أنه سئل عن ذلك، قالت له امرأة: «يا رسول الله! إن أمي ماتت ولم توص أفلها أجر إن تصدقت عنها؟ قال: نعم، وسأله رجل مثل ذلك قال: نعم، فالصدقة تصل إلى الأموات، وهكذا الدعاء، والاستغفار لهم، والترحم عليهم، والحج والعمرة، والضحية؛ كل ذلك يصل إليهم. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16832/هل-الصدقة-تصل-الى-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77912.mp3","categories":["إهداء القرب للميت"]},{"id":17839,"question":"يقول السائل محمد عيد في سؤاله الثاني سماحة الشيخ: نريد أن نتعرف هل الصدقة تصل المتوفى على حساب النية؟ مثل: أن نذبح شاة على سبيل المثال ونعزم الجيران والأقارب فيأكلون منها، فهل هذه الصدقة تصل إلى المتوفى؟","title":"هل الصدقة تصل إلى الميت؟","answer":"الجواب: نعم، الصدقة تصل إلى المتوفى سواء كانت الصدقة بالنقود، أو بالطعام، أو بالملابس، أو بالأوقاف أو غير ذلك، فإذا صنع وليمة، ودعا إليها الفقراء، أو أكرم بها أقاربه، وأرحامه، وجيرانه يقصد ثواب ذلك لوالده، أو أخيه، أو أمه أو نحو ذلك حصل له بذلك الخير العظيم، قد أجمع العلماء على أن الصدقة تصل إلى الميت، ثوابها يصل إلى الميت، وجاء في هذا أحاديث كثيرة عن النبي ﷺ أنه سئل عن ذلك، قالت له امرأة: «يا رسول الله! إن أمي ماتت ولم توص أفلها أجر إن تصدقت عنها؟ قال: نعم، وسأله رجل مثل ذلك قال: نعم، فالصدقة تصل إلى الأموات، وهكذا الدعاء، والاستغفار لهم، والترحم عليهم، والحج والعمرة، والضحية؛ كل ذلك يصل إليهم. نعم.\nالمقدم: أحسن الله إليكم وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16832/هل-الصدقة-تصل-الى-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_779/nour_77912.mp3","categories":["إهداء القرب للميت"]},{"id":17997,"question":"على بركة الله نبدأ هذا اللقاء برسالة وصلت من اليمن تقول السائلة: توفيت أمي منذ فترة، فهل يجوز أن أصوم عنها وإن لم يكن عليها صيام؟ ماذا أفعل تجاهها مأجورين؟","title":"حكم الصوم عمن ليس عليه صوم","answer":"الجواب: بسم الله الرحمن الرحيم ،الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفالميت لا يصام عنه، ولا يصلى عنه، إلا إذا كان عليه صوم واجب، مثل كفارة أو صوم رمضان ولم يقضه فإن أقاربه يستحب لهم أن يقضوا عنه لقول النبي ﷺ: من مات وعليه صيام صام عنه وليه يعني: قريبه، فإذا مات وعليه صوم من رمضان أو كفارة يستحب لأقربائه أن يصوموا عنه، أما النافلة فلا يصام عنه، ولا يصلى عنه، ولكن يتصدق عنه بالمال، يتصدق عنه .. يدعى له بالمغفرة والرحمة .. نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ","link":"https://binbaz.org.sa/fatwas/17027/حكم-الصوم-عمن-ليس-عليه-صوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78101.mp3","categories":["إهداء القرب للميت"]},{"id":18103,"question":"ما حكم قراءة القرآن للميت بعد الدفن بعدة أيام، هل يستفيد منها؟ خاصة قراءة سورة يس وتبارك و(قل هو الله أحد) أم أن الدعاء له أن يرحمه ويغفر له ربه أنفع؟ وما الذي ورد عن الرسول الكريم ﷺفي ذلك؟","title":"حكم قراءة القرآن بنية الأجر للميت","answer":"الجواب: الذي ورد هو الدعاء للموتى والترحم عليهم، أما أن يقرأ لهم القرآن عند القبور، أو في مكان آخر فهذا لا نعلم له أصلًا، وإن كان قاله بعض أهل العلم واستحبه بعض أهل العلم، وقال: إنه يلحق الميت وينفعه، لكن ليس عليه دليل. فالذي ينبغي أن يكون الإحسان للميت بالدعاء والصدقة له، والحج عنه، والعمرة عنه، وقضاء دينه، هذا هو الذي ينفعه، هذا هو الذي جاء في الأحاديث الصحيحة، الصدقة عن الميت، الدعاء له بالمغفرة والرحمة، قضاء دينه، الحج عنه، العمرة عنه هذا هو المحفوظ. أما أن يقرأ عنه أو يقرأ له سورة يس أو تبارك في أي مكان أو عند القبور هذا لا أصل له ولا ينبغي وليس بمشروع، وإنما تشرع قراءة يس عند المحتضر قبل أن يموت لينتفع بذلك وليوعظ ويذكر ويقرأ عنده القرآن هذا ينفعه قبل أن يموت، أما بعد الموت فقد انتهى الأمر. ومما قد يقع من بعض الناس أن بعض الناس يقرأ في القبر إذا انحفر القبر جعل يقرأ فيه وبعضهم يؤذن فيه ويقيم، هذا كله بدعة لا أصل له، لا أذان في القبر، ولا إقامة في القبر، ولا قراءة في القبر، كل هذا مما أحدثه الناس، والله المستعان. نعم. المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17138/حكم-قراءة-القران-بنية-الاجر-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_904/nour_90403.mp3","categories":["إهداء القرب للميت"]},{"id":18120,"question":"هذا السائل (عبد الكريم . أ. أ) يقول: سماحة الشيخ! ما حكم الأضحية عن الميت؛ حيث إن البعض من الناس يقولون: بأن الأضحية عن الميت بدعة، فهي للأحياء وجهونا في ذلك؟","title":"هل الأضحية عن الميت بدعة؟","answer":"الجواب: الأضحية سنة عن الحي والميت، والذي يقول: إنها بدعة، قد غلط، والصواب أنها سنة عن الحي والميت، وقد ضحى النبي ﷺ بكبشين أحدهما عن محمد وآله وفيهم الميت كبناته، وضحى بكبش ثان عن من وحد الله من أمة محمد، وفيهم الحي والميت، فالضحية عن الميت قربة وطاعة كالحي، فإذا ضحى عن أبيه الميت، أو عن أمه الميتة، أو عن أخيه، أو زوجته؛ فكله قربة وكله طاعة. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17162/هل-الاضحية-عن-الميت-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78109.mp3","categories":["النيابة في الحج","الهدي والأضاحي","إهداء القرب للميت"]},{"id":18144,"question":"يقول السائل من الكويت: هل يجوز وضع المصاحف في المساجد؟ وهل يكون لمن وضعها أجر على كل حرف يقرأ من هذا المصحف، ووضع هذا المصحف بنية أن يكون أجر القارئ للمتوفى فهل هذا مشروع؟","title":"ثواب من أوقف المصاحف في المسجد","answer":"الجواب: وضع المصاحف في المساجد مشروع؛ لأنه يعين من جاء للمسجد على القراءة، وصاحبه له أجر، يرجى له أجر كبير؛ لأنه ممن أعان على الخير، والرسول  يقول: والله في عون العبد ما كان العبد في عون أخيه، ويقول ﷺ: من كان في حاجة أخيه كان الله في حاجته. وإذا سبل المصاحف للأموات، أو كُتبَ علم؛ فلهم أجر في ذلك، إذا سبل مصحفًا، أو كتاب علم من كتب الحديث الشريف، أو من كتب التفسير، أو الفقه؛ فله أجر في ذلك، وإذا نوى هذا الوقف لأبيه أو أمه فله أجر في ذلك، وللموقوف له أجر في ذلك. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/17194/ثواب-من-اوقف-المصاحف-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78117.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18195,"question":"يسأل سؤالاً آخر ويقول: إن أنا تصدقت عن والدي، فهل يصيبني نفس الأجر، حيث أن والدي متوفى، وأرجو بيان الأوجه التي يمكن الإنفاق فيها عن الميت، وهل الدعاء أفضل من هذا كله؟","title":"الصدقة مفيدة للميت والمتصدق","answer":"الجواب: الصدقة عن الميت مشروعة ومفيدة ونافعة للميت، وقد ثبت في الصحيحين عن النبي ﷺ أنه سئل عن ذلك قال له رجل: «يا رسول الله! إن أمي ماتت أفلها أجر إن تصدقت عنها، قال: نعم فالصدقة تنفع الميت، ويرجى للمتصدق مثل الأجر الذي يحصل للميت؛ لأنه محسن متبرع، فيرجى له مثل ما بذل، كما قال عليه الصلاة والسلام: من دل على خير فله مثل أجر فاعله. فالمؤمن إذا دعا إلى خير، أو فعل خيرًا في غيره يرجى له مثل أجره، فإذا تصدق عن أبيه، أو عن أمه، أو ما أشبه ذلك، فللمتصدق عنه أجر وللباذل أجر، وهكذا إذا حج عن أبيه أو عن أمه فله أجر ولأبيه وأمه أجر، ويرجى أن يكون مثلهم أو أكثر؛ لفعله الطيب وصلته الرحم وبره لوالديه، وهكذا أمثال ذلك فضل الله واسع. وقاعدة الشرع في مثل هذا أن المحسن إلى غيره له أجر عظيم، وأنه إذا فعل معروفًا عن غيره يرجى له مثل الأجر الذي يحصل لمن فعل له ذلك المعروف، وقد قال عليه الصلاة والسلام: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. فأنت -يا عبد الله- في صدقتك عن والديك، وفي إحسانك إلى عباد الله بما تفعله من المعروف لك فيه أجر عظيم، ولمن أحسنت إليهم بأن علمتهم وقبلوا منك، وأرشدتهم وقبلوا منك، ودللتهم على الخير وقبلوا منك لهم أجر أيضًا ولك مثلهم. نعم. المقدم: طيب.. طيب جزاكم الله خيرًا، يسأل هل الدعاء يقوم مقام الصدقة شيخ عبد العزيز؟ الجواب: الدعاء مستقل، الدعاء فيه خير عظيم، ولكن لا يقوم مقام الصدقة، فالصدقة مشروعة والدعاء مشروع، والدعاء عام للوالدين ولغير الوالدين، وهكذا الصدقة، فالصدقة نوع من البر والخير والعبادة والدعاء كذلك فلا يغني هذا عن هذا، وينبغي للولد ونحوه أن يفعل هذا وهذا يدعو لوالديه ويتصدق، وهكذا عن أقاربه، وهكذا عن أحبابه وأصدقائه الطيبين يدعو لهم ويتصدق عنهم كله طيب. المقدم: جزاكم الله خيرًا، إذًا ليس الدعاء أفضل من العمل وليس العمل أفضل من الدعاء. الشيخ: هذا يختلف قد يكون الدعاء في حال أفضل وقد تكون الصدقة في حال أفضل، والدعاء ميسور بحمد الله ما يكلف شيئًا، الدعاء ميسور والصدقة قد تكلف، فقد يكون أجرها أكبر، ولاسيما إذا وقعت في محلها في الفقراء والمحاويج وعند الحاجة، فأجرها عظيم مع الدعاء مع الدعاء. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17230/الصدقة-مفيدة-للميت-والمتصدق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_907/nour_90703.mp3","categories":["إهداء القرب للميت"]},{"id":18209,"question":"أرى على الشوارع كثيرًا من الفقراء ومنهم المعوق، فاتحين أيديهم يطلبون المال إني أعطيهم دائمًا، وبعض الأحيان أهدي أجر ذلك أو أقول: هذا صدقة لأمي المتوفاة، لا أدري هم فقراء أم لا؟ ولكن شكل بعضهم يبين أنهم فقراء، هل يجوز أن أعطيهم المال وأنا لا أعرف هل هم فقراء أم لا؟","title":"حكم إعطاء المتسولين وإهداء الثواب للميت","answer":"الجواب: نعم من تعرض للسؤال يعطى قال الله جل وعلا: وَالَّذِينَ فِي أَمْوَالِهِمْ حَقٌّ مَعْلُومٌ [المعارج:24] فمن سأل يعطى، وهكذا المحروم وهو الفقير يعطى، فإذا مر الإنسان بقوم يشحذون الناس ويرفعون أيديهم شرع أن يعطوا ما تيسر من الصدقة، يقول النبي ﷺ: اتقوا النار ولو بشق تمرة، فمن لمن يجد فبكلمة طيبة. وإذا أراد المتصدق بصدقته عن أبيه أو عن أمه أو عن فلان فله نيته، فالصدقة يجوز أن تفعل عن الأموات وهي تلحقهم وتنفعهم كما قال النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية أو علم ينتفع به أو ولد صالح يدعو له وسأل النبي ﷺ رجل قال: إن أمي ماتت أفلها أجر إن تصدقت عنها؟ قال النبي ﷺ: نعم، فالصدقة عن الموتى تنفعهم، بإجماع المسلمين. لكن إذا علم المار أو غيره أن هذا الذي يشحذ غني وأنه غير محتاج فإنه ينصحه ويوبخه ويقول له: إن هذا لا يجوز لك، ولا يحل لك أن تسأل، وأنت قد أغناك الله ، يقول النبي ﷺ في الحديث الصحيح: من سأل الناس أموالًا تكثرًا فإنما يسأل الجمر، فليستقل أو ليستكثر رواه مسلم في الصحيح، وقال عليه الصلاة والسلام: لا تزال المسألة بالرجل حتى يأتي يوم القيامة وليس في وجهه مزعة لحم متفق عليه. فالواجب على المؤمن والمؤمنة ألا يسألا إلا عن حاجة، أما من أغناه الله بمال عنده عن كسب أو عن إرث، أو عن هدية أو غير هذا من الطرق الشرعية، فالواجب عليه أن يستغني بالله وألا يسأل ولا يحل له السؤال، ولهذا قال عليه الصلاة والسلام: إن المسألة لا تحل إلا لأحد ثلاثة: رجل تحمل حمالة يعني: دين فحلت له المسألة حتى يصيبها ثم يمسك يتحمل حمالة لإصلاح ذات البين بين الناس أو لحاجة بيته وعائلته فله أن يسأل حتى يصيبها ثم يمسك، ورجل أصابته جائحة اجتاحت ماله حلت له المسألة حتى يصيب قوامًا من عيش أو قال: سدادًا من عيش، يعني: من أصابته جائحة كالسيل أو الحريق أو الجراد أكل زرعه، فافتقر بسبب ذلك يعطى ما تيسر، حتى تسد حاجته، ويحل له أن يسأل إذا لم يتيسر له إلا بالسؤال، والثالث رجل أصابته فاقة يعني: حاجة حتى يقول ثلاثة من ذوي الحجا من قومه: لقد أصابت فلان الفاقة، فحلت له المسألة حتى يصيب قوامًا من عيش، ثم قال عليه الصلاة والسلام للسائل قبيصة: وما سوى ذلك يا قبيصة سحت يأكله صاحبه سحتًا يعني: ما عدا الثلاث فهو سحت يعني: فهو حرام. فالواجب على أهل الإيمان أن يحذروا ما حرم الله، ومن ذلك أن يسأل وقد أغناه الله، فالمسألة إنما تحل في هذه الحالات الثلاث، وكثير من الناس والعياذ بالله لا يبالي لأنه قد اعتاد السؤال وهو لا يبالي بالسؤال وإن كان غنيًا، لما أصيب به من الجشع والحرص على المال وعدم المبالاة بأمر الشرع -نعوذ بالله من ذلك-. لكن السائل إذا لم يعلم هذا الشخص يعطي من سأل، يعطيه وَفِي أَمْوَالِهِمْ حَقٌّ لِلسَّائِلِ وَالْمَحْرُومِ [الذاريات:19] إذا سألك أو وجدته يسأل في الطريق أو في المسجد أو في أي مكان يشرع لك أن تعطيه ما تيسر كما قال المصطفى عليه الصلاة والسلام: اتقوا النار ولو بشق تمرة ما لم تعرف أنه غني، فإذا عرفت أنه غني مثلما تقدم تنصحه وتوبخه ولا تعطيه؛ لأن إعطاءه إعانة له على الإثم والعدوان. نسأل الله العافية والسلامة. نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/17263/حكم-اعطاء-المتسولين-واهداء-الثواب-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_856/nour_85604.mp3","categories":["إهداء القرب للميت"]},{"id":18218,"question":"هذا سائل للبرنامج من الطائف يقول: بعض الناس يفعلون قهوة، أو يعملون قهوة، ويدعون بعض الأقارب، ويفرقون عليهم شيء من الكعك مع القهوة، ويقولون بأن هذه هبة لموتانا، فهل يجوز ذلك وتكون صدقة، وتصل إلى الميت، أم لا؟ وهل يجوز حضور مثل ذلك مأجورين؟","title":"حكم دعوة الناس على القهوة والكعك صدقة عن الميت","answer":"الجواب: إذا فعلوا هذا لأقاربهم، أو لجيرانهم لا بأس، إذا كانوا فقراء صارت صدقة، أما إذا كانوا أغنياء ما هي بصدقة، الصدقة تكون على الفقراء، أما هذه إذا كانت مع أغنياء ليست صدقة، لكن من باب الهدية، ومن باب الإكرام مع الأقارب، أو مع الجيران لا بأس، الصدقة تكون على الفقراء. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17275/حكم-دعوة-الناس-على-القهوة-والكعك-صدقة-عن-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78215.mp3","categories":["إهداء القرب للميت"]},{"id":18247,"question":"في آخر أسئلة هذه السائلة، تقول سماحة الشيخ: أنا أحب معلمتي تذكر بأنها .. تقول السائلة: أنا أحب معلمتي في الله، وفي نهاية الدراسة أهديت لها هدية من باب التآلف والمحبة بيننا، هل يجوز لي هذا؟","title":"حكم الهدايا بين الطلاب والمدرسين","answer":"الجواب: ترك الهدية أحوط؛ لأنه قد يسبب الميل إليك دون بقية التلميذات، ترك الهدية أولى وأحوط؛ لأن المدرسة من العمال، ولا تنبغي الهدية للعمال، فالأحوط لك والذي ينبغي أن لا تهدي شيئًا؛ لأن هذه الهدية قد تسبب ميلًا من المدرسة إليك، وحيفًا على البقية بسبب الهدية، فالأحوط والذي يظهر من الأدلة عدم الهدية للمدرسات والمدرسين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17296/حكم-الهدايا-بين-الطلاب-والمدرسين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78303.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18283,"question":"ننتقل إلى رسالة أخرى وصلت من الأخوين: محمود فرحات، وعبد الرحمن الشدوي من الظهران، الإخوان لهم مجموعة من الأسئلة يسألون في سؤالهم الأول ويقولون:هناك عادة متبعة بين أفراد إحدى القبائل، تتمثل بأنه يجب على كل من يحضر ختان المولود الذكر دفع مبلغ من المال للوالد يتراوح من خمسين إلى مائة ريال، ما رأي سماحتكم في هذه العادة من الناحية الشرعية؟","title":"حكم دفع الأموال لمن رزق بمولود يوم ختانه","answer":"الجواب: إذا كان من عادة القبيلة، أو من عادة الأقارب بينهم الإهداء إلى أصحاب المولود في وقت الختان، أو في وقت العقيقة، أو في أي وقت بعد الولادة، فلا حرج في هذا من باب التبرع، ومن باب التعاون لا نعلم بأسًا في ذلك، كما أن من عادة الكثير من الناس مساعدة المتزوج إذا بلغهم أنه سيتزوج، أو دعاهم إلى الوليمة ساعدوه في الزواج؛ كل هذا من باب التعاون على الخير. والمسلمون شيء واحد يتعاونون على البر والتقوى وعلى مصالحهم وعلى سد حاجة الفقير، ولا سيما إذا كان صاحب المولود فقيرًا؛ فإن مساعدته من أهم القربات، لا في العقيقة ولا في غيرها. نعم.","link":"https://binbaz.org.sa/fatwas/17332/حكم-دفع-الاموال-لمن-رزق-بمولود-يوم-ختانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_911/nour_91102.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18313,"question":"شيخ: عبد العزيز أخونا يسأل -لو تكرمتم- عن الدعاء للميت في الصلاة؟","title":"حكم الدعاء للميت في الصلاة","answer":"الجواب: لا بأس أن يدعو للميت في الصلاة، وفي خارج الصلاة، يقول: اللهم اغفر لي ولوالدي في التحيات، بين السجدتين، في السجود، اللهم اغفر لأخي فلان، اللهم اغفر لشيخي فلان، اللهم اغفر لأصحاب الرسول ﷺ وارض عنهم، اللهم صل على رسول الله واجزه عنا خيرًا، وهكذا يدعو لمن شاء من المسلمين، في سجوده، في آخر الصلاة، بين السجدتين، محل دعاء، حيًّا أو ميتًا. نعم.","link":"https://binbaz.org.sa/fatwas/17370/حكم-الدعاء-للميت-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_859/nour_85902.mp3","categories":["إهداء القرب للميت"]},{"id":18330,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع: عبد الله أحمد نايل، سوداني، أخونا يسأل ويقول: في رد لسماحتكم مجيبين عن السؤال الآتي: هل يجوز تلاوة القرآن على المتوفى، أو إهداء ثوابه له، علمت من ردكم أن هناك خلافًا بين العلماء في هذا الأمر، وكما قلتم: إنه ليس هناك دليل من الشارع على هذه المسألة، أرجو من فضيلة مولانا المزيد من الإيضاح في تعليقه على هذه الملاحظات، إذا جاز لنا أن نحج عن المتوفى، وأن نتصدق له ألا يعني هذا أن من يحج عن المتوفى أن يؤدي مناسك الحج جميعها المفروضة منها والمسنون؟فإذا قام -مثلاً- لصلاة ركعتين عند المقام والسنة، ألا يهدي ثواب هذه الصلاة للمتوفى؟ وبالتالي: ألا يكون ما قرأه من القرآن في صلاته كان مهداه للمتوفى كسائر أعمال الحج؟فضيلة مولانا الدعاء على المتوفى جائز، أليس الدعاء مخ العبادة، وإذا كان القرآن رحمة وشفاء للمؤمنين ألا يكون المتوفى أحوج لهذه الرحمة، وأن القرآن يحتوي على الكثير من آيات الدعاء.والخلاصة: إذا كانت تلاوة القرآن لا تجوز على المتوفى هذا يعني: ألا نتلو الآيات الشاملة على الترحم له، أرجو إلقاء المزيد من الضوء على هذا الدرب، وجزاكم الله عن الأحياء والأموات خيرًا، أخوكم: عبد الله أحمد نايل.","title":"حكم إهداء ثواب قراء القرآن للميت","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فإني أشكر للسائل عنايته واهتمامه بهذه الأمور الشرعية العظيمة، وأسأل الله لنا وله المزيد من كل خير، أيها الأخ السائل: إن أمور العبادات ليست محل القياس، والعبادات توقيفية كما قال أهل العلم، لا يقال فيها بالرأي المجرد والقياس من عبادة على عبادة، ولكن يتلقى أمر العبادة عن الشارع -عن الله وعن رسوله عليه الصلاة والسلام- ولا نقيس شيئًا على شيء بدون حجة. فالرسول ﷺ أقر الحج عن الميت وأذن فيه، وعن العاجز أيضًا -كالشيخ الكبير العاجز- يحج عنه، والصلاة التي يصليها الطائف تبعًا للطواف، يكون ثوابها وثواب الطواف للميت، من غير حاجة إلى أن يهدي الصلاة أو يهدي القراءة؛ لأنه صلى تبعًا للطواف، وهذه الصلاة جازت تبعًا لا استقالًا، ولا يشرع لأحد أن يصلي عن ميت أو يصوم عنه تنفلًا؛ لأن هذا لم يرد في الشرع، والعبادات مثل ما تقدم توقيفية، يقول النبي ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد، ويقول الله  في ذلك ما هو أعم من هذا: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21]، ويقول عليه الصلاة والسلام: من أحدث في أمرنا هذا يعني: في ديننا وفي شرعنا ما ليس منه فهو رد يعني: فهو مردود. فالواجب على أهل الإسلام الاتباع لما جاء به نبيهم -عليه الصلاة والسلام- وليس لهم أن يبتدعوا، فالحج بأعماله الواجبة والمشروعة جاءت عن الشارع فإذا حج عن الميت أو عن العاجز صار الأجر للمحجوج عنه عن النفل والفرض جميعًا حسب ما جاء عن الشارع، ولا نقيس على ذلك فنقول: كما جازت الصلاة تبع الطواف للميت المحجوج عنه نقول: لنا أن نصلي عن الموتى ونصوم عنهم؟! لا، هذا قياس. الحج عبادة مستقلة، فلا يقاس عليها أن نصوم عنه نافلة أو نصلي عنه نافلة، بل علينا أن نتبع ونقف عند الشرع، وهكذا التلاوة، التلاوة التي يقرأها الإنسان في الصلاة على الميت، والتلاوة في ركعتي الطواف، والتلاوة في الطواف كل هذه تبع، فلا يقاس عليها التلاوة المستقلة كونه يقرأ على الميت فيجعل الثواب للميت، أو يقرأ على القبر أو يقرأ خارج ذلك في أي مكان وينويه للميت، هذا يحتاج إلى دليل. وإن كان جملة من أهل العلم ذهبوا إلى جواز ذلك وأنه لا بأس به، وقاسوه على الحج، والدعاء والصدقة، لكن مثل ما تقدم، القاعدة الشرعية، عدم القياس وأن علينا أن نتبع ولا نخترع ولا نبتدع في الدين ما لم يأذن به الله، وإذا فتح هذا الباب دخل الناس في البدع ولم يقفوا عند حد، فلهذا قلت سابقًا وأقول الآن: إن الأرجح عدم تثويب التلاوة للميت وعدم الصلاة عنه، وعدم الصوم عنه، إلا إذا كان عليه دين، عليه صوم واجب من رمضان، أو من كفارة أو من نذر فلا مانع من الصوم عنه لقول النبي ﷺ: من مات وعليه صيام صام عنه وليه. وسئل غير مرة عمن مات وعليه صيام فأفتى المستفتي بأن يصوم عن ميته، هكذا نقول مثلما قال النبي ﷺ: \"من مات وعليه صيام يصام عنه\"، هذا مشروع بأمر النبي عليه الصلاة والسلام حتى رمضان على الصحيح، إذا مات وعليه صيام ولم يقضه من دون عذر شرع لأوليائه أن يصوموا عنه، كما يصوموا عنه الكفارات والنذور، وبعض أهل العلم خص ذلك بالنذر، والصواب: أنه لا يخص النذر بل يعم، لما في الصحيحين من حديث عائشة رضي الله عنها عن النبي ﷺ أنه قال: من مات وعليه صيام صام عنه وليه، هكذا قال عليه الصلاة والسلام: من مات هذا عموم وعليه صيام، صام عنه وليه، فيعم من مات وعليه صوم رمضان، أو صوم كفارة أو صوم نذر. ومن زعم تخصيص ذلك بالنذر فلا دليل عليه، وليس معه حجة يحسن الاعتماد عليها، ولم يقل ﷺ: من مات وعليه صلاة صلى عنه وليه! ولم يقل: من مات فيقرأ عنه وليه! لكن الدعاء نعم، شرع لنا أن ندعو للأموات ونصلي وندعو لهم، والله يقول  في كتابه العظيم مثنيًا على عباده الصالحين بقوله: وَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ [الحشر:10]. فالدعاء أمر مطلوب للميت والحي جميعًا، ولهذا شرع الله صلاة الجنازة لما فيها من الدعاء للميت، فأرجو يا أخي! ألا يشتبه عليك الأمر وأن تطمئن إلى أن السنة أن تلزم ما جاءت به الشريعة وألا تحيد عنه، وألا تزيد عليه في العبادات لأنها توقيفية، والله ولي التوفيق. المقدم: جزاكم الله خيرًا. شيخ عبد العزيز ! يكثر بعض إخواننا من كلمة (مولانا)، وقد علقتم ذات مرة في إجابة في حلقة مضت على هذه الكلمة؟ الشيخ: كذلك ينبغي ألا يستعمل هذا؛ لأن الرسول ﷺ قال: لا تقولوا: مولانا فإن مولاكم الله، هكذا رواه مسلم في الصحيح، فينبغي للمؤمن تركها، وقد أجازها بعض أهل العلم، واحتجوا بقوله ﷺ في حق العبد وليقل: سيدي ومولاي، قالوا: هذا دليل على جوازها، لما جازت في حق العبد أن يقولها لسيده، فالأولى في هذا ألا نقيس على العبد، بل هذا خاص بالعبد يقوله لسيده، أما غيره فينبغي له أن يتأدب بالأدب الشرعي فيقول: يا فلان، يا أخي، يا أبا فلان، يا شيخ فلان، ويكفي هذا، ويحتاط لدينه ويبتعد عن الشيء اللي فيه شبهة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17386/حكم-اهداء-ثواب-قراء-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_860/nour_86001.mp3","categories":["إهداء القرب للميت"]},{"id":18365,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من المستمع بهاء أحمد محمد أحمد، أخونا عرضنا له بعض أسئلة في حلقة مضت، وفي هذه الحلقة يسأل سماحتكم، فيقول:أسألكم عن صديق كان عاقًا لوالده قبل وفاته، وبعد وفاته بدأ يصلي له كل يوم ركعتين، ويدعو له؛ حتى يكفر عن وضعه ذلكم الذي ذكره، وجهونا، هل ما يعمله صحيح؟ جزاكم الله خيرًا؟","title":"أفضل ما يتعاهد به الولد والده بعد وفاته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالصلاة للميت، ليس لها أصل في الشرع فيما نعلم، ولكن يشرع له الدعاء له، يدعو لوالده، في سجوده، وفي الليل، وفي كل وقت، يدعو له بالمغفرة، والرحمة، والعفو، ورفيع الدرجات، ومضاعفة الحسنات، يتصدق عنه بما يسر الله من المال، يحج عنه، يعتمر، هذه الطرق الشرعية التي تنفع والده، أما كونه يصلي عنه، أو يصوم عنه؛ فليس لهذا أصل فيما نعلم. ومما ينبغي الإكثار من الدعاء، الإكثار من الدعاء لأبيك.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17427/افضل-ما-يتعاهد-به-الولد-والده-بعد-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73211.mp3","categories":["إهداء القرب للميت"]},{"id":18368,"question":"من إحدى الأخوات المستمعات، تقول: أختكم في الإسلام (د. ع. ح) من العريش، أختنا لها قضيةٌ تقول فيها: سيدة كانت متزوجة، فمات عنها زوجها، وترك لها ولدين، ولم يترك لها أي مال، فتركت الأولاد لأهلهم، وتزوجت من رجلٍ آخر، وأنجبت منه ولدًا وبنتًا، ثم قام هذا الرجل الذي تزوجته بكتابة قطعة أرضٍ زراعية لها، فهل يجوز أن تكتب هذه الأرض باسم أولادها من هذا الرجل؛ لأنها أرض أبيهم في الأصل، أم تترك الأرض يرث فيها أولادها من الرجل الأول؟ جزاكم الله خيرًا.","title":"هل يجوز تخصيص بعض الأولاد بالعطية؟","answer":"الجواب: الواجب عليها ترك الأرض للجميع، فليس لها أن تخص أولادها من الزوج الجديد، الأرض تكون للجميع، تعدل بينهم؛ يقول النبي ﷺ: اتقوا الله، واعدلوا بين أولادكم ولو كانت الأرض من الزوج الجديد صارت ملكًا لها، فليس لها أن تعطيها أحدهم، وليس لها أن توصي بها لأحدهم، بل للجميع، تبقى في يدها، في ملكها، ويرثونها عنها، أو تقسمها بينهم لا بأس، أما أن تخص بها أحدًا منهم؛ فلا. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17435/هل-يجوز-تخصيص-بعض-الاولاد-بالعطية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73212.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":18389,"question":"المقدم:سماحة الشيخ! يستفسر الحقيقة كثير من الناس عن إهداء ثواب الأعمال فما حكمها؟ وما هو أفضل شيء يعمله الإنسان لوالديه المتوفى؟","title":"الأعمال التي يشرع إهداؤها إلى الميت","answer":"الجواب: الوارد في الأحاديث إنما هو الصدقة عن الميت وعن الحي، والحج عن الميت والعمرة عنه، وعن العاجز لكبر سن، أو مرض لا يرجى برؤه، والدعاء كذلك. أما كونه يصلي عنه، أو يصوم عنه؛ لا، غير مشروع، المشروع أن يدعو له، ويتصدق عنه؛ هذا المشروع، أما الحج عن الميت، أو العاجز، أو العمرة عنه؛ فلا بأس، وهكذا الصدقة عن الحي والميت، الصدقة طيبة ونافعة للحي والميت، هكذا الدعاء للحي والميت. نعم.","link":"https://binbaz.org.sa/fatwas/17459/الاعمال-التي-يشرع-اهداوها-الى-الميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_784/nour_78407.mp3","categories":["إهداء القرب للميت"]},{"id":18625,"question":"السائل حمزة يقول: الصدقة الجارية هل تصل إلى الميت؟ وهل المال أيضًا يصل أجره إلى الميت؟ يا سماحة الشيخ.","title":"حكم الصدقة للميت","answer":"الجواب: نعم، الصدقة تصل الميت إذا تصدق عنه غيره، وأحسن بالنية عنه بماء أو مال آخر كالذهب والفضة، أو غيرهما، يقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له نعم.","link":"https://binbaz.org.sa/fatwas/17733/حكم-الصدقة-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91824.mp3","categories":["إهداء القرب للميت"]},{"id":18688,"question":"عندما نريد قراءة القرآن، أو بعض السور من القرآن الكريم إلى بعض أموات المسلمين، هل يشترط ذكر اسم المتوفى مع اسم والدته أم لا؟ وهل يصل إليهم ثواب قراءة القرآن؟جزاكم الله خيرًا.","title":"حكم إهداء ثواب قراءة القرآن للميت","answer":"الجواب: الصحيح من أقوال العلماء أنه لا يشرع أن يقرأ القرآن عن الموتى، إنما يقرأ الإنسان القرآن لنفسه ليستفيد؛ ليتعلم، وله الأجر، أما أن يقرأ للميت فهذا لا أصل له، ليس عليه دليل. فالراجح: أنه لا يقرأ للميت، ولكن يقرأ لنفسه ويستفيد ويتدبر ويتعقل ويعمل، وله الأجر العظيم، كل حرف بحسنة، والحسنة بعشر أمثالها، يقول ﷺ: اقرؤوا القرآن، فإنه يأتي شفيعًا لأصحابه يوم القيامة لكن المؤمن يدعو لأمواته، يدعو لهم بالمغفرة والرحمة، يتصدق عنهم، يحج عنهم يعتمر كل هذا طيب، ومن أهم شيء الدعاء، الدعاء للأموات بالمغفرة والرحمة، بالنجاة من النار، بعلو الدرجات، بمضاعفة الحسنات كله طيب، والحج عن الميت، والعمرة كذلك، والصدقات كله طيب ينفع الميت، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17779/حكم-اهداء-ثواب-قراءة-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_735/nour_73508.mp3","categories":["إهداء القرب للميت"]},{"id":18783,"question":"رسالة وصلت إلى البرنامج من المستمع أحمد حسن أحمد من الخرج، أخونا بدأ رسالته بقوله:بسم الله الرحمن الرحيم، إنني سوداني مقيم بمدينة الخرج، وتوفي لرحمة مولاه والدي قبل شهرين، ومن العادات التي عندنا بالسودان بدون سند أن يقرأ الابن لوالده المتوفى دبر كل صلاة سورة الإخلاص إحدى عشرة مرة ويهب ثواب ما تلاه لروح المرحوم والده، يا سماحة الشيخ، هل لهذا العمل من دليل؟أفيدونا عنه جزاكم الله خيرًا.","title":"حكم إهداء ثواب سورة الإخلاص للميت","answer":"الجواب: هذا العمل ليس له دليل، بل هو بدعة، ولو اعتاده جماعتهم، فإن البدع لا تبررها العادات، والواجب ترك هذه البدعة، والحذر منها، ويكفي أن تدعو لأبيك، وأن تتصدق عنه، هذا هو المشروع الدعاء، والصدقة، والحج عنه، والعمرة، كل هذا ينفعه بإذن الله. فنوصيك بالاستكثار من الدعاء لوالدك بالمغفرة والرحمة، وهكذا الصدقة عنه بما تيسر ولو بالقليل، والله -جل وعلا- يثيبك، ويخلف عليك ما أنفقت في هذا السبيل الخلف العظيم، ويأجرك على دعواتك لأبيك، وقد قال -عليه الصلاة والسلام-: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. فمما يلحق الميت بعد وفاته دعاء الولد، والولد يشمل الذكر والأنثى، البنت والابن كلاهما يقال له: ولد، كما قال تعالى: يُوصِيكُمُ اللَّهُ فِي أَوْلادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الأُنثَيَيْنِ [النساء:11] فالأولاد تطلق على الذكور والإناث، والولد يقال للذكر والأنثى، ويقال للذكر: ابن، للأنثى بنت، وقوله ﷺ: أو ولد صالح يدعو له يعني: ذكر أو أنثى. فمن البر للوالد بعد وفاته الدعاء له، وقد سئل -عليه الصلاة والسلام- سأله بعض الصحابة قال: «يا رسول الله، هل بقي من بر أبوي شيء أبرهما بعد وفاتهما؟ قال -عليه الصلاة والسلام-: نعم، الصلاة عليهما، والاستغفار لهما، وإنفاذ عهدهما من بعدهما، وصلة الرحم التي لا توصل إلا بهما، وإكرام صديقهما فذكر خمسة أشياء: الصلاة عليهم، يعني: الدعاء الدعاء لهم، ومن الصلاة عليهم صلاة الجنازة أيضًا.  والاستغفار لهما طلب المغفرة لهما.  والثالث: إنفاذ عهدهما من بعدهما إذا أوصيا بشيء تنفذه إذا كانت وصية لا تخالف الشرع تنفذها، والرابع: صلة الرحم التي لا توصل إلا بهما كإكرام أعمامك وعماتك، وأخوالك وخالاتك، والإحسان إليهم، وصلتهم كل هذا من بر والديك.  والخامس: إكرام صديقهما إذا كان لهما صديق تكرمه بما تستطيع من الكلام الطيب، والزيارة، والدعوة إلى البيت لإكرامه بالضيافة، ومواساته إن كان فقيرًا كل هذا من إكرام الصديق، والله المستعان. المقدم: الله المستعان جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17910/حكم-اهداء-ثواب-سورة-الاخلاص-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90603.mp3","categories":["البدع والمحدثات","إهداء القرب للميت"]},{"id":18784,"question":"أيضًا من العادات لديهم ما ذكره بقوله: يجتمع حوالي عشرة أشخاص، ويتلون المصحف الشريف، ويهبون للمتوفى الثواب مرة في كل عام، هل هذا العمل صحيح؟","title":"حكم قراءة القرآن كل عام وإهداء ثوابه للميت","answer":"الجواب: وهذا كالذي قبله ليس بمشروع، بل هو بدعة، وقد اختلف العلماء -رحمة الله عليهم- هل يصل ثواب القراءة إلى الميت على قولين: أرجحهما أن ذلك لا يصل؛ لعدم الدليل، والعبادات توقيفية ليست بالرأي والاستحسان، ولا بالقياس، وقد قال -عليه الصلاة والسلام-: من عمل عملًا ليس عليه أمرنا فهو رد. فالأرجح: أنه لا يشرع الصلاة عن الميت، ولا الطواف عن الميت، ولا القراءة عنه، بل تدعو له في صلاتك، في طوافك، في قراءتك، تدعو لأبيك، لأمك، لأمواتك، هذا طيبًا إذا كانوا مسلمين. أما الصدقة عن والديك هذا أمر مشروع وينفعهما وينفع غيرهما أيضًا من أقاربك والمسلمين جميعًا، هكذا الدعاء لوالديك ولغيرهم، الدعاء نافع ومفيد، كما قال الله سبحانه عن الصالحين أنهم يقولون في دعواتهم: رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالإِيمَانِ وَلا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَحِيمٌ [الحشر:10] هذا من دعوات الأخيار لسلفهم الصالح. ومن ذلك أيضًا: الحج عن الميت والعاجز والعمرة كذلك، فإنها تنفع الميت، وهكذا العاجز الكبير في السن العاجز عن العمرة وعن الحج إذا حج عنه ولده أو غيره نفعه ذلك لما جاء في الأحاديث الصحيحة الدالة على ذلك.  ومما يلتحق بهذا الإشارة إلى ما يفعله بعض الناس من العمرة عن أمواتهم، وهم في مكة، أو عن نفسه وهو مقيم بمكة كالذي جاء للحج، أو من أهل مكة، فيأخذ عمرة له من الحل، فقد ذهب بعض أهل العلم إلى عدم شرعية ذلك، وقالوا: إن النبي ﷺ لم يفعل ذلك حين كان بمكة يوم الفتح، وذهب الجمهور إلى أنه لا بأس بذلك، وأنه مشروع، واحتجوا على هذا بأن النبي ﷺ أعمر عائشة وهي من أهل مكة كانت في مكة يوم حجة الوداع أعمرها من التنعيم، وأمر عبد الرحمن أخاها أن يخرج معها فأدت عمرة من التنعيم، وهي في ذلك الوقت في مكة، فدل ذلك على أنه لا حرج في الخروج من مكة إلى الحل لأداء العمرة. وكون النبي ﷺ لم يفعل ذلك لا يدل على عدم شرعية ذلك، فإنه قد يدع الشيء لأسباب كثيرة -عليه الصلاة والسلام-، ومنها أنه قد يدعه لئلا يشق على أمته -عليه الصلاة والسلام-، كما كان -عليه الصلاة والسلام- لا يواظب على صلاة الضحى، مع أنه أوصى بذلك أبا هريرة وأبا الدرداء أوصاهما بصلاة الضحى دائمًا وهي سنة، صلاة الضحى دائمًا سنة مؤكدة؛ لأن الرسول أوصى بها -عليه الصلاة والسلام-، وإن كان لم يداوم عليها كما أخبرت بذلك عائشة -رضي الله عنها- عنه -عليه الصلاة والسلام-. فالمقصود: أنه قد يدع الشيء وهو مستحب؛ لئلا يشق على أمته، أو لأسباب أخرى -عليه الصلاة والسلام-، وقد أخبر ﷺ أن أحب الصيام إلى الله صيام داود كان يصوم يومًا ويفطر يومًا، ومع هذا ما كان النبي يفعل هذا -عليه الصلاة والسلام- فالقول غير الفعل، التشريع القولي مقدم على التشريع الفعلي. وقد أمر عائشة بالقول -عليه الصلاة والسلام- أن تخرج إلى الحل فتعتمر، فدل ذلك على أنه لا حرج ولا بأس في حق من خرج من مكة لأخذ العمرة عن نفسه أو عن أمواته أو عن العاجزين من قراباته وغيرهم كل ذلك لا بأس به، وحديث عائشة حجة قائمة، وهو متفق على صحته بين الشيخين البخاري ومسلم -رحمة الله عليهما- ونسأل الله للجميع التوفيق، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17911/حكم-قراءة-القران-كل-عام-واهداء-ثوابه-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90604.mp3","categories":["إهداء القرب للميت"]},{"id":19075,"question":"هذه أخت سائلة تقول: ما حكم تقديم الهدية بالنسبة للمعلمات يا سماحة الشيخ في آخر العام الدراسي؟","title":"حكم تقديم الطالبة هدية لمعلمتها","answer":"الجواب: تركه أولى لا، لا تعطي لا يعطين الهديات لا تقدم الطالبة هدية؛ لأن الهدية للمعلمة قد تفضي إلى المحاباة والحيف ولا ينبغي للمعلمة أن تقبل هدايا الطالبات؛ لأن هذا قد يفضي إلى اتهامها أو حيفها؛ ولأنها بمنزلة العمال وهدايا العمال غلول فينبغي للأمير والمعلم عدم قبول الهدايا ممن تحت يده حتى لا يجره ذلك إلى الحيف والظلم. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18246/حكم-تقديم-الطالبة-هدية-لمعلمتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88322.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19250,"question":"تسأل أختنا هل يجوز للمعلمة قبول الهدية من الطالبات؟ وإذا كان لا يجوز لها ذلك فهل يجوز قبولها بعد انتهاء العام الدراسي وتسليم النتائج؟ وإذا كان ذلك أيضًا لا يجوز، فهل يجوز لها قبولها من الطالبات بعد انتهاء مدة تدريسها في تلك المدرسة إذا أرادت الانتقال من هذه المدرسة لمدرسة أخرى؟","title":"حكم قبول الهدية من الطلاب","answer":"الجواب: الذي ينبغي للمعلمة ترك قبول الهدايا؛ لأنها قد تجرها إلى الحيف، وعدم النصح في حق من لم يهد والزيادة في حق المهدية والغش، فالأحوط للمؤمنة في هذا أن لا تقبل الهدية من الطالبات بالكلية؛ لأن ذلك قد يفضي إلى ما لا تحمد عقباه، والمؤمن يحتاط لدينه ويبتعد عن أسباب الريبة والخطر. أما بعد انتقالها من المدرسة إلى مدرسة أخرى فلا يضر ذلك؛ لأن الريبة قد انتهت حينئذ والخطر مأمون، وهكذا بعد فصلها من العمل إذا أهدوا إليها شيئًا فلا بأس. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18443/حكم-قبول-الهدية-من-الطلاب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73813.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19328,"question":"أخ لنا يقول: المرسل ولدكم المعذب -كما يصف نفسه - عبد الله بن علي المعيطب من الرياض: والدي سماحة الشيخ عبد العزيز أفتوني عن أمر ضاق به صدري، وحالتي الصحية تأثرت به كثيرًا، إنني عصيت والدي كثيرًا وفي يوم من الأيام حصلت لي قضية، وقام والدي بالمتابعة لها، وأثناء هذا حدثت له حادثة سيارة وتعذب كثيرًا في المستشفى، ثم توفي وهو غير راض عني، وفي بعض الأوقات يقول أهلي: إنني أنا الذي قتلته، وأنا الذي تسببت في هذا الحادث، وهذه الكلمات تجرح قلبي، وفي بعض الأوقات أفكر - كما يقول شيخ عبدالعزيز - في الانتحار بسبب تلكم الكلمات، أنا الآن أدعو لوالدي، وأقرأ له القرآن إلا أن حالتي الصحية في تأثر، كيف أكفر عما فعلت تجاه والدي، وبماذا تنصحونني وتنصحون أهلي؟ جزاكم الله خيرًا.","title":"كيفية التوبة من عقوق الوالد بعد وفاته","answer":"الجواب:  أما أنت فننصحك بأن تلزم التوبة النصوح التي تشتمل على الندم على ما فعلت مع والدك من الإساءة، والعزم الصادق أنك لا تعود إلى أمثال ذلك من العقوق والقطيعة، وعليك مع ذلك أن تتبع هذا بالعمل الصالح كما قال الله  في كتابه العظيم : إِلَّا مَنْ تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُوْلَئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ [الفرقان:70]، قال سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى [طه:82]. فنصيحتي لك أن تلزم التوبة والندم على ما مضى منك، وتكثر الاستغفار والعمل الصالح من صلاة وصدقات وغير ذلك، وتسبيح وتهليل وتحميد وتكبير، وتكثر من قراءة القرآن وغير هذا من العمل الصالح، مع الدعاء لوالدك بالمغفرة والرحمة ورفيع الدرجة في الجنة، وتتصدق عنه بما تستطيع. الصدقات تنفع والدك، أما قراءة القرآن عنه فليس عليها دليل؛ وإن قال بها جمع من أهل العلم، لكن الأفضل أن تجعل بدل القراءة له الدعاء؛ لأنه لم يرد دليل واضح على أنه يقرأ عن الأموات، وإنما الدعاء هو المشروع، الدعاء له، والصدقة عنه، والحج عنه، والعمرة عنه، كل هذا أمر ينفعه، يقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية أو علم ينتفع به أو ولد صالح يدعو له، كن أنت ولدًا صالحًا، وأكثر من الدعاء والاستغفار لأبيك مع توبتك الصادقة عما جرى منك سابقًا وأبشر بالخير، والتوبة تجب ما قبلها والحمد لله، وإياك والوساوس، وإياك وطاعة من يقول لك: إنك فعلت وإنك فعلت.. التوبة تهدم ما كان قبلها، وتجب ما قبلها الحمد لله، أعظم من العقوق الشرك، وإذا تاب المشرك تاب الله عليه؛ فالعقوق دون الشرك، فالتوبة تجب ما قبلها. ونصيحتي لأهلك أن يتقوا الله فيك، وأن لا يتعرضوا لهذا الأمر وأن يبشروك بالخير؛ لأنك تبت والتوبة تجب ما قبلها فلا يجوز لهم أبدًا أن يذكروك بما جرى منك مما يضرك، ويسبب ضيق صدرك وتحرجك، بل ينبغي لهم أن يسلوك عن هذا، وأن يقولوا لك: احمد لله لما تاب عليك، وليس لك في هذا الحادث ما يوجب تأثرك، فالأمر بيد الله  هو الذي قضى ما قضى، ويرجى له الخير، ولعله يكون شهيداً بسبب الحادث. فالحاصل أن الواجب عليك التوبة فقط ولزومها، ويشرع لك الدعاء لأبيك والإكثار من ذلك، والصدقة كما تقدم إذا تيسرت ولو بالقليل، والحج إذا تيسر عن والدك والعمرة كذلك، كل هذا طيب. وأبشر بالخير وإياك وسوء الظن بالله وإياك وسوء الظن بالله من تاب أفلح من تاب أفلح، يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31]، والرسول عليه الصلاة والسلام يقول: التوبة تهدم ما كان قبلها، ويقول: التائب من الذنب كمن لا ذنب له، فاتق الله وأحسن الظن بمولاك واستقم على طاعته جل وعلا ولا تلتفت إلى من يلومك أو يقول لك بعد هذا فهم مخطئون وغالطون في كونهم يؤذونك وقد تبت إلى الله، بل الواجب عليهم أن يبشروك، وأن يفرحوك، وأن يعينوك على الفرح وحسن الظن بالله فالتائب لا يؤذى، التائب يبشر ويعان. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18534/كيفية-التوبة-من-عقوق-الوالد-بعد-وفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_896/nour_89603.mp3","categories":["إهداء القرب للميت","زيارة القبور","الحكم على الأحاديث","بر الوالدين"]},{"id":19508,"question":"يقول هذا السائل: ما الأشياء التي أوقفها لوالدي رحمه الله؟","title":"الأشياء المشروع وقفها للوالدين","answer":"الجواب: الأشياء كثيرة، توقف له بيتًا يؤجر، ويتصدق بأجرته على الفقراء والمساكين، أو نخلًا أو أرضًا تزرع، وتكون غلتها تصرف في سبيل الله في الفقراء، والمحاويج، ويعمر منها المساجد، ويوصل منها الرحم، كل هذا خير عظيم. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18759/الاشياء-المشروع-وقفها-للوالدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94609.mp3","categories":["إهداء القرب للميت"]},{"id":19552,"question":"تقول: لها صديقة توفيت، فهل إذا تصدقت لها من مالها الخاص هل يصلها الثواب لاسيما أنها لها ولد؟","title":"حكم الصدقة للميت","answer":"الجواب: نعم، إذا تصدقت المرأة لبعض أقربائها أو صديقاتها فلا بأس، يقول النبي ﷺ: إذا مات ابن آدم انقطع عمله إلا من ثلاث: صدقة جارية... فإذا تصدق هو وأوقف شيئًا نفعه، وإذا تصدق عنه غيره نفعه ذلك. كما ينفعه الدعاء، فإذا تصدقت عن زميلتها وصديقتها، أو قريبتها تصدقت عنها أو دعت لها بعد الموت، أو حجت عنها، أو اعتمرت؛ كله طيب ينفع الله به الموتى. نعم.","link":"https://binbaz.org.sa/fatwas/18806/حكم-الصدقة-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_947/nour_94705.mp3","categories":["إهداء القرب للميت"]},{"id":19603,"question":"ما حكم الأضحية عن الأموات يا شيخ؟","title":"ما حكم الأضحية عن الأموات؟","answer":"الجواب: إذا ضحى لا أرى فيه حرجًا، وإذا ضحى عن نفسه وأهل بيته الحي والميت فلا بأس، النبي ﷺ كان يضحي بكبشين، أحدهما عنه وعن أهل بيته، والثاني عمن وحد الله من أمته عليه الصلاة والسلام، فإذا ذبح الإنسان ضحية عنه وعن أهل بيته من زوجة وأولاد ووالدين فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/18858/ما-حكم-الاضحية-عن-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94912.mp3","categories":["الهدي والأضاحي","إهداء القرب للميت"]},{"id":19621,"question":"السائل محمد يحيى من اليمن يقول: يا سماحة الشيخ! بأنه يختم القرآن ختمات متعددة، ويريد أن يتصدق بها على أقاربه المتوفين، هل يجوز له ذلك، وهل يكتب له الأجر، وماذا يقول عند الإهداء؟","title":"حكم قراءة القرآن وتثويبه للموتى","answer":"الجواب: ليس لهذا أصل، بل يقرأ لنفسه، ويدعو لهم، أما إهداء الختمات أو بعض السور ما لها أصل، ليس له أصل في أصح قولي العلماء، فلا يجوز إهداء القراءة، ولا إهداء الصلاة، ولكن يقرأ لنفسه، ويصلي لنفسه، ويدعو لوالديه، ولأقاربه، ولأحبابه الدعاء كافي، أما هدية القرآن أو الصلاة فهو غير مشروع.","link":"https://binbaz.org.sa/fatwas/18894/حكم-قراءة-القران-وتثويبه-للموتى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94825.mp3","categories":["إهداء القرب للميت"]},{"id":19626,"question":"هذه السائلة أم عبد العزيز تقول: ما حكم تثويب الاستغفار للميت؟ وأيهما أفضل يا سماحة الشيخ: وضع برادة ماء وقف عن شخص ميت، أم توضع في مساعدة حج من أسلم حديثًا عن طريق مكاتب الجاليات وفقهم الله؟","title":"حكم تثويب الاستغفار للميت ومشروعية وقف الماء في المساجد وتحجيج الغير","answer":"الجواب: التبرع بالاستغفار تثويبه له ما هو بمشروع، لكن الدعاء تقول: اللهم اغفر له، أما أن تستغفري لنفسك، وتقولي: اللهم اجعل ثوابه له؛ هذا لا أصل لهذا، لكن تقولي: اللهم اغفر لفلان، اللهم ارحمه، اللهم أنجه من النار، هذا دعاء تدعو له، أما تثويب الاستغفار هذا لا أصل له، استغفارك لك، لكن تقول: اللهم اغفر لفلان، اللهم ارحمه، اللهم أنجه من النار وما أشبه ذلك. والصدقة بالمال للصوام في المساجد ولغيرهم قربة، ومساعدة المحتاج للحج قربة، كلها قرب طيبة، كلها قرب نافعة، وعظيمة النفع، وفيها ثواب جزيل، أما التفضيل بينها فالله أعلم، لكن إيجاد الماء في المساجد ينفع الله به جمًا غفيرًا، وأما مساعدة واحد في الحج فهي مساعدة فردية، أما وضع الماء في المساجد فهذا ينفع الله به أممًا كثيرة. نعم. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18899/حكم-تثويب-الاستغفار-للميت-ومشروعية-وقف-الماء-في-المساجد-وتحجيج-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_948/nour_94830.mp3","categories":["إهداء القرب للميت"]},{"id":19643,"question":"من جدة السائل (ع. ب. ي) يقول: سماحة الشيخ حفظكم الله، أنا متزوج من امرأة صالحة ولم يرزقني الله منها بولد، وقد أكد الأطباء على عدم قدرتها على الإنجاب ولا أملك غير البيت الذي نسكن فيه، فهل يمكنني أن أسجل البيت الذي نسكن فيه باسمها حتى يكون عونًا لها في حياتها، أم أن هذا محرم، علمًا بأنها زوجتي الوحيدة، ولا أنوي الزواج مرة أخرى ولي ستة من الإخوة والأخوات؟","title":"حكم الهبة للزوجة","answer":"الجواب: لا حرج في ذلك إذا أعطيتها بيتك وسجلته باسمها في صحتك فلا بأس، أما في حال المرض لا، أما في صحتك إذا أعطيتها بيتك أو أعطيتها شيئًا آخر من مالك فلا حرج في ذلك. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18924/حكم-الهبة-للزوجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94932.mp3","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19646,"question":"يقول هذا السائل: ما هو حكم قراءة القرآن على الميت مأجورين؟","title":"حكم إهداء قراءة القرآن للميت","answer":"الجواب: القرآن لا يقرأ على الموتى، يقرأ على المحتضر قبل أن يموت، إذا قرأ عنده يس أو قرأ عنده شيئًا من القرآن حتى يؤنسه، وحتى يذكره بالله كله طيب، أما الموتى لا يقرأ عليهم، إذا مات انتهى، انقطع عمله إلا من ثلاث: صدقة جارية، أو علم ينتفع به، أو ولد صالح يدعو له. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/18927/حكم-اهداء-قراءة-القران-للميت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94933.mp3","categories":["إهداء القرب للميت"]},{"id":19693,"question":"رجل له أربعة أولاد، منهم واحد موظف ومتزوج وله خمسة أولاد، وجزء من المال الذي بيد والده توفير من رواتب الولد المذكور، مع العلم بأن هذا الولد قائم بنفقة أولاده ووالديه وإخوانه؛ لأنهم في بيت واحد، فأحب والده أن يتبرع لابنه المذكور بخمس المال الذي بيده، مقابل عن عمله ودخله.","title":"هل للوالد أن يخص بعض أولاده بشيء دون الباقين؟","answer":"الجواب:\n\nقد ثبت عن النبي ﷺ أنه قال: اتقوا الله، واعدلوا بين أولادكم[1] متفق على صحته. فليس للوالد أن يخص بعض أولاده بشيء إلا برضا الباقين المكلفين المرشدين في أصح قولي العلماء. لكن إذا أحب أن يجعل ما قبضه من رواتبه في المستقبل قرضًا عليه، أو أمانة عنده، فلا بأس، وعليه أن يوضح ذلك في وثيقة معتمدة، وبذلك يكون قد حفظ له حقه الذي دخل عليه أو بعضه، ولا يكون أعطاه شيئًا، وإنما هو ماله حفظه له. والله أعلم[2].\n\n\n\n\tرواه البخاري في (الهبة وفضلها)، باب (الإشهاد في الهبة)، برقم: 2587، ومسلم في (الهبات)، باب (كراهة تفضيل بعض الأولاد في الهبة)، برقم: 1623.\n\tاستفتاء مقدم لسماحته من السائل /أ. ع. ن، وأجاب عنه سماحته برقم 841، في 25/3/1395هـ، عندما كان رئيسًا للجامعة الإسلامية. (مجموع فتاوى ومقالات الشيخ ابن باز 20/49).","link":"https://binbaz.org.sa/fatwas/19053/هل-للوالد-ان-يخص-بعض-اولاده-بشيء-دون-الباقين","audio":"","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]},{"id":19694,"question":"في حالة اختلاف شخصين على مال، وتحكيم ثالث بينهما، واغتصاب الثالث شيئًا من هذا المال بموافقتنا هل يحل له ذلك أم يحرم عليه؟","title":"جواز قبول الهبة لفاعل المعروف","answer":"الجواب:\n\nإذا حكَّم شخصان ثالثًا بينهما في مالٍ، فأخذ منه شيئًا بإذنهما وموافقتهما فلا أعلم فيه بأسًا، ولا يسمى ذلك اغتصابًا، بل هو هبة منهما له. أما إن شرط عليهما أن لا يحكم بينهما إلا بجعل، فهذا في حله نظر وتفصيل[1].\n\n\n\n\tمجموع فتاوى ومقالات الشيخ ابن باز (20/62).","link":"https://binbaz.org.sa/fatwas/19089/جواز-قبول-الهبة-لفاعل-المعروف","audio":"","categories":["الوقف","الهبة والعطية","إهداء القرب للميت"]}]
